--   DELETE FROM project_repository_links WHERE jurisdiction = 'IN-KL' AND repository_project_id = (SELECT id FROM projects WHERE slug = 'kerala-school-curriculum-repository');
--   DELETE FROM projects WHERE slug = 'kerala-school-curriculum-repository';

SET search_path = public, extensions;

DO $MIGRATION$
DECLARE
  v_india UUID;
  v_owner_id UUID;
  v_owner_invited_by UUID;
  v_kl UUID;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM projects WHERE slug = 'uttar-pradesh-curriculum-repository') THEN
    RAISE EXCEPTION 'Apply migration 200 first: the Uttar Pradesh repository is missing.';
  END IF;
  SELECT id INTO v_india FROM projects WHERE slug = 'india-curriculum-repository';
  SELECT user_id, invited_by INTO v_owner_id, v_owner_invited_by FROM project_members WHERE project_id = v_india AND role = 'owner' LIMIT 1;
  INSERT INTO projects (slug, name, description, project_kind, parent_project_id, is_private, epistemic_status, epistemic_status_note, focus_type, region_tags, created_by)
  SELECT
    'kerala-school-curriculum-repository',
    'Kerala School Curriculum Repository',
    'School curriculum goals and standards for Kerala: the Kerala Curriculum Framework, the SCERT Kerala textbooks for science, social science and ICT, and the state programmes that bear on them. First layer, written 2026-10-30 from public documents. Research on the education of Scheduled Tribe communities is held separately in the Kerala Curriculum Repository.',
    'curriculum-repository',
    v_india,
    TRUE,
    'in-development',
    'AI-drafted from public documents and summarised in our own words. No Indian curriculum expert has reviewed it. Each record says which document was read and which passage; treat anything marked secondary-source-only as unconfirmed.',
    'regional',
    ARRAY['IN-KL'],
    v_owner_id
  WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug = 'kerala-school-curriculum-repository');
  SELECT id INTO v_kl FROM projects WHERE slug = 'kerala-school-curriculum-repository';
  IF v_owner_id IS NOT NULL THEN
    INSERT INTO project_members (project_id, user_id, role, invited_by)
    VALUES (v_kl, v_owner_id, 'owner', v_owner_invited_by)
    ON CONFLICT (project_id, user_id) DO NOTHING;
  END IF;
END
$MIGRATION$;

