INSERT INTO curriculum_repository_records (id, project_id, record_type, jurisdiction, source_repo, source_record_id, title, content, access_tier, event_date)
SELECT v.id::uuid, p.id, v.record_type, v.jurisdiction, v.source_repo, v.source_record_id, v.title, v.content::jsonb, 'summary-only', NULLIF(v.event_date, '')::date
FROM (VALUES
  ('f6e6e02d-6005-548f-982b-9fd075df7458', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2023-ict-coding-ai-robotics-across-subjects', 'SCERT Kerala, Kerala Curriculum Framework 2023 (School Education), section 6.6: ICT, coding, AI and robotics across subjects', '{"id":"IN-KL-MANDATE-kcf-2023-ict-coding-ai-robotics-across-subjects","label":"SCERT Kerala, Kerala Curriculum Framework 2023 (School Education), section 6.6: ICT, coding, AI and robotics across subjects","sourceUrl":"https://drive.google.com/open?id=1obj0di-Nh_4aoxigC_EwtDnW3zBvni8t","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Kerala Curriculum Framework 2023 (School Education), SCERT Kerala, English PDF linked from https://scert.kerala.gov.in/kerala-curriculum-framework-2023/. Section 6.6 ICT-friendly education, printed pages 93 to 104 (6.6.1 Approach p.94-96; 6.6.6 ICT and Mathematics Learning p.100-101; AI chat boxes p.104); section 6.7 point 12 (p.112); Chapter 7 optional subjects (p.125). Printed page numbers; PDF page equals printed page plus 3.. AI-drafted, unreviewed. The AI reader downloaded and read the English ''Kerala Curriculum Framework 2023 (School Education)'' PDF (223 PDF pages, text layer readable) from the Google Drive link on SCERT Kerala''s framework page. Read closely: section 6.6 and its sub-sections (p.93-104), the passage at p.112 (a list of points on work-integrated education that includes AI, data analytics and robotics) and the optional-subjects passage at p.125. Skimmed: sections 6.6.3 to 6.6.5 (language, science and social science with ICT). Not read: the Malayalam text, the pre-primary and adult-education frameworks, the position papers. The framework gives no class-by-class computing outcomes, so the links go to whole strands and are rated weak. Status and date: SCERT''s menu and the Malayalam heading label the 2023 framework a draft. The English school-education PDF has no printed date or status line, so the year comes from the title only. News items seen in search results describe a final version being approved, but the AI reader did not open them. A reviewer should confirm the adopted status and date. Kerala''s stages (section 7.1, p.118): pre-primary from age 3, primary Classes 1 to 7, secondary Classes 8 to 12. Section 6.6.1 (p.94) prefers integrating ICT into subjects over a separate subject, and Kerala also issues separate ICT textbooks for Classes 1 to 10 (see the textbook records). Section 6.6 (p.96) asks for the present IT curriculum, syllabus and textbooks to be revised. Hi-Tech classrooms with computers and projectors are mentioned at p.102. Checker (verify-kl-computing, 30 October 2026): re-downloaded the English PDF and confirmed every cited page. The PDF''s file properties show a creation date of 20 May 2025, which says nothing about the issue date, so the year stays 2023 from the title. SCERT''s pages label the framework a draft. A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2023 (School Education), SCERT Kerala, English PDF linked from https://scert.kerala.gov.in/kerala-curriculum-framework-2023/. Section 6.6 ICT-friendly education, printed pages 93 to 104 (6.6.1 Approach p.94-96; 6.6.6 ICT and Mathematics Learning p.100-101; AI chat boxes p.104); section 6.7 point 12 (p.112); Chapter 7 optional subjects (p.125). Printed page numbers; PDF page equals printed page plus 3.","description":"The framework, which SCERT''s website labels a draft, asks for ICT to be built into each subject instead of taught as a separate subject, and says the present IT syllabus and textbooks need revising. It suggests coding and Python in mathematics and AI-supported search chat boxes for digital learning resources. It lists AI, data analytics and robotics as content to add, and AI as a possible optional secondary subject.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, for the Government of Kerala General Education Department","mandateType":"curriculum-framework","adoptionDate":"2023","dateGranularity":"year","statementText":"The framework, which SCERT''s website labels a draft, asks for ICT to be built into each subject instead of taught as a separate subject, and says the present IT syllabus and textbooks need revising. It suggests coding and Python in mathematics and AI-supported search chat boxes for digital learning resources. It lists AI, data analytics and robotics as content to add, and AI as a possible optional secondary subject.","subject":"computer-science","gradeFrom":1,"gradeTo":12,"topicTags":["ict","coding","python","artificial-intelligence","robotics","data-analytics","digital-textbooks"]}', ''),
  ('0f2db1eb-236b-58ad-a430-f5ba1d13c736', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2023-mathematics-computational-thinking-and-data', 'SCERT Kerala, Kerala Curriculum Framework 2023, section 8.2 Mathematics: computational thinking, data and programming tools', '{"id":"IN-KL-MANDATE-kcf-2023-mathematics-computational-thinking-and-data","label":"SCERT Kerala, Kerala Curriculum Framework 2023, section 8.2 Mathematics: computational thinking, data and programming tools","sourceUrl":"https://drive.google.com/open?id=1obj0di-Nh_4aoxigC_EwtDnW3zBvni8t","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Kerala Curriculum Framework 2023 (School Education), SCERT Kerala: 6.6.6 ICT and Mathematics Learning (p.100-101); 8.2.1 Learning Mathematics, the New Perspective (p.145-146); 8.2.2 Objectives (p.146-148); 8.2.4 Content (p.149-152); 8.2.6 Textbooks (p.155-156). Printed page numbers; PDF page equals printed page plus 3.. AI-drafted, unreviewed. The AI reader read sections 8.2.1 to 8.2.7 in the English PDF. The list of computational thinking habits is on p.146. The remark that choosing efficient methods is the first step toward computer programming is on p.148. Classes 8 to 10 content (p.151) names mean, median and mode and the first lessons of probability. Ratio and scaling are linked to computer graphics (p.150), and matrices to computer graphics (p.152). The framework gives these ideas without class bands for computational thinking itself, so the links go to whole strands. The framework does not use the word ''algorithm'' in the passages read. Check on textbooks: the framework says (p.156) that Turtle Art, Scratch and Python from the ICT books may be used in mathematics books. The AI reader searched the text of SCERT''s English-medium mathematics books, First Edition 2025, for Class 6 (Parts 1 and 2), Class 8 (Parts 1 and 2) and Class 10 (Parts 1 and 2). Class 8 Part 1 has a ''Computer help'' box with a short Python loop (p.43) and a definition of ''algorithm'' (p.87). Class 10 Part 1 has a Python sum example (p.70). GeoGebra activities appear in the Class 8 and Class 10 books. The Class 6 books and the remaining parts had no match for Scratch, Python, algorithm or spreadsheet. Mathematics books for Classes 1 to 5, 7 and 9 were not searched. Status and date caveats are the same as in the sibling record on section 6.6: the English PDF carries no printed date and SCERT''s page labels the framework a draft in Malayalam. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2023 (School Education), SCERT Kerala: 6.6.6 ICT and Mathematics Learning (p.100-101); 8.2.1 Learning Mathematics, the New Perspective (p.145-146); 8.2.2 Objectives (p.146-148); 8.2.4 Content (p.149-152); 8.2.6 Textbooks (p.155-156). Printed page numbers; PDF page equals printed page plus 3.","description":"The mathematics section says computational thinking grew from the analysis of mathematical problems, and lists its habits: focus on the key elements, break a complex problem into parts, organise the steps, and spot repeated operations that differ only in numbers. It asks for larger data sets analysed with ICT, mean, median and mode in Classes 8 to 10, and use of Turtle Art, Scratch and Python in mathematics books.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, for the Government of Kerala General Education Department","mandateType":"curriculum-framework","adoptionDate":"2023","dateGranularity":"year","statementText":"The mathematics section says computational thinking grew from the analysis of mathematical problems, and lists its habits: focus on the key elements, break a complex problem into parts, organise the steps, and spot repeated operations that differ only in numbers. It asks for larger data sets analysed with ICT, mean, median and mode in Classes 8 to 10, and use of Turtle Art, Scratch and Python in mathematics books.","subject":"mathematics","gradeFrom":1,"gradeTo":12,"topicTags":["computational-thinking","mathematics","decomposition","statistics","scratch","python","computer-graphics"]}', ''),
  ('81df72fd-f0b1-5b56-a138-68a887b4d5c4', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-ict-textbooks-classes-1-to-7-logic-games-scratch-spreadsheets-vision', 'SCERT Kerala and KITE, ICT textbooks for Classes 1 to 7 (2024 and 2025 editions): logic games, Scratch, spreadsheets, vision', '{"id":"IN-KL-UNIT-ict-textbooks-classes-1-to-7-logic-games-scratch-spreadsheets-vision","label":"SCERT Kerala and KITE, ICT textbooks for Classes 1 to 7 (2024 and 2025 editions): logic games, Scratch, spreadsheets, vision","sourceUrl":"https://samagra.kite.kerala.gov.in/#/textbook/page/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: SCERT Kerala ICT textbooks, English medium. Class 3 (First Edition 2024) chapters 1 to 8 and 17; Class 4 (First Edition 2025) ch.15 Show the Way p.40-41 and ch.17 The Obedient Computer p.45-47; Class 5 (First Edition 2024) ch.4 Coding for Drawing p.29-39; Class 6 (First Edition 2025) ch.4 Coding: the Matters in the Game p.34-44 and ch.8 Let''s Use Spreadsheets p.70-80; Class 7 (First Edition 2024) ch.1 Information Analysis p.7-18, ch.5 Creating Computer Games p.54-67, ch.9 Computer Vision p.94-102. Classes 1 and 2 (editions 2024 and 2025): contents pages only.. AI-drafted, unreviewed. This record groups chapters from seven books so a reader can compare the stage with the model; it is a cluster of chapters, so the ''curriculum-unit'' label is a loose fit. The AI reader downloaded the PDFs from KITE''s Samagra portal (the textbook page linked from SCERT Kerala''s site; the file paths were taken from the portal''s own listing). Base: https://samagra.kite.kerala.gov.in/files/samagra-resource/uploads2/tbookscmq plus Class 1 /eng/1/16/ICT_1762771063298_228427076.pdf, Class 2 /eng/2/16/STD_2_ICT_1748857986794_759185111.pdf, Class 3 /Class_III/ICT_3_E/book.pdf, Class 4 /eng/4/16/STD_IV_ICT_1748858059120_834433133.pdf, Class 5 /Class_V/IT_5_E/1-56.pdf, Class 6 /eng/6/16/STD_VI_ICT_1748858154674_295704417.pdf, Class 7 /Class_VII/IT_7_E/1-64.pdf. Edition years are the ''First Edition'' lines printed in each book (Class 1: 2024; 2: 2025; 3: 2024; 4: 2025; 5: 2024; 6: 2025; 7: 2024). These are the editions the portal lists on 30 October 2026. A KITE circular of 30 July 2025 (No. KITE/2025/1234 (32), read as a Malayalam scan) sets teacher training on the renewed ICT books for Classes 2, 4 and 6. No 2026-27 document naming the ICT textbook editions for Classes 1 to 7 was found on SCERT, KITE or General Education Department pages or in the KITE circular list on 30 October 2026. These are the editions the portal lists, but their use in 2026-27 is not confirmed by any 2026-27 document. Read closely: Class 5 ch.4 (Scratch sprites, the ''when flag clicked'' event, forever loop, ''if on edge, bounce'', pen drawing and patterns), Class 6 ch.4 (a Scratch game built from a backdrop, sprites and event, if-then and sensing blocks; the chapter says it builds on the pattern drawing of the year before), Class 6 ch.8 start (spreadsheet cells, labels, values, formulas), Class 7 ch.1 start and ch.9. Class 7 ch.9 defines AI as computers using stored experience, introduces PictoBlox, and has pupils use a trained model that reads seven expressions; it describes the computer as ''trained'' on thousands of faces. Class 3 and 4 activities are picture-led play on GCompris games (pattern, sorting, mazes, a ''programming maze'' in Class 4 ch.15). Not read in detail: Class 1 and 2 chapters (titles only, such as ''Let''s Categorise'' in Class 1), Class 7 ch.2 to 4 and 6 to 8, Class 6 ch.1 to 3 and 5 to 7. A text search of Classes 1 to 7 found no ''variable'', ''binary'', user-defined function or written test case. AI appears as a taught topic first in Class 7; Class 6 has a side note on AI and audio editing, and Classes 1 to 5 have no AI lesson. Kerala''s Class 3 to 5 mathematics books were not read, so any earlier data-handling in those books is unknown. The data link therefore says ''relates''. Checker (verify-kl-computing, 30 October 2026): chapter lists confirmed from each book''s contents page. Class 1 (Playbox, 2024): 15 chapters (Let''s Draw Looking the Sky to Whose Shadow?). Class 2 (2025): 16 chapters (Tic Tac Toe to Chase the Germs). Class 3 (2024): 17 chapters (Which Train is it? to Hanoi''s Tower). Class 4 (2025): 19 chapters (Let''s Draw a Picture to Catch the Fish). Class 5 (2024): 8 chapters. Class 6 (2025): 10 chapters. Class 7 (2024): 10 chapters. The teacher notes of Classes 1 to 4 name GCompris (and Tux Paint, Tux Typing, Scratch 3 in Class 4). Class 4 chapter 17 The Obedient Computer (p.45-47) is a short Scratch activity, so block coding starts in Class 4. The Class 4 teacher note says children have to acquire coding skills at the lower primary level. Class 6 chapter 4 first shows the if-then block on p.39. Class 6 chapter 8 covers cells, a multiplication formula, sum and merging cells and says averages and charts come in higher classes. Spreadsheet charts first appear in Class 7 chapter 1. No variable, function or algorithm lesson appears in Classes 1 to 7. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"SCERT Kerala ICT textbooks, English medium. Class 3 (First Edition 2024) chapters 1 to 8 and 17; Class 4 (First Edition 2025) ch.15 Show the Way p.40-41 and ch.17 The Obedient Computer p.45-47; Class 5 (First Edition 2024) ch.4 Coding for Drawing p.29-39; Class 6 (First Edition 2025) ch.4 Coding: the Matters in the Game p.34-44 and ch.8 Let''s Use Spreadsheets p.70-80; Class 7 (First Edition 2024) ch.1 Information Analysis p.7-18, ch.5 Creating Computer Games p.54-67, ch.9 Computer Vision p.94-102. Classes 1 and 2 (editions 2024 and 2025): contents pages only.","description":"The ICT textbooks for Classes 1 to 4 are built around GCompris and similar games for logic, sorting, pattern and number work. Class 4 adds a first short Scratch activity. Class 5 draws patterns with a forever loop, Class 6 builds a game with conditions and introduces spreadsheets, and Class 7 makes spreadsheet charts and uses a ready-made AI model that detects facial expressions.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, textbooks prepared by Kerala Infrastructure and Technology for Education (KITE)","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"The ICT textbooks for Classes 1 to 4 are built around GCompris and similar games for logic, sorting, pattern and number work. Class 4 adds a first short Scratch activity. Class 5 draws patterns with a forever loop, Class 6 builds a game with conditions and introduces spreadsheets, and Class 7 makes spreadsheet charts and uses a ready-made AI model that detects facial expressions.","subject":"computer-science","gradeFrom":1,"gradeTo":7,"topicTags":["ict","scratch","block-coding","spreadsheets","charts","computer-vision","games"]}', ''),
  ('509e5ef1-1b04-5d2f-9cc9-2c384da21086', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-ict-textbooks-classes-8-to-10-machine-learning-python-databases-robotics', 'SCERT Kerala and KITE, ICT textbooks for Classes 8 to 10 (2025): machine learning, AI, Python, databases, robotics', '{"id":"IN-KL-UNIT-ict-textbooks-classes-8-to-10-machine-learning-python-databases-robotics","label":"SCERT Kerala and KITE, ICT textbooks for Classes 8 to 10 (2025): machine learning, AI, Python, databases, robotics","sourceUrl":"https://samagra.kite.kerala.gov.in/#/textbook/page/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: SCERT Kerala ICT textbooks, English medium, First Edition 2025. Class 8 Part 2 ch.6 Machines That Learn p.7-21 and ch.7 Data Analysis on a Computer p.22-35; Class 8 Part 1 ch.4 Computer Games p.45-60. Class 9 Part 1 ch.3 Let''s Develop Software p.37-47 and ch.4 Data Analysis Made Easy p.48-57; Class 9 Part 2 ch.6 Intelligent Machines p.7-19. Class 10 Part 1 ch.3 Computer Language p.45-66, ch.4 Cyber Space p.67-84, ch.6 The World of Robots from p.98; Class 10 Part 2 ch.9 To the Information Storehouse p.54-69.. AI-drafted, unreviewed. The AI reader downloaded the PDFs from KITE''s Samagra portal. Base https://samagra.kite.kerala.gov.in/files/samagra-resource/uploads2/tbookscmq plus Class 8 Part 1 /eng/8/16/ICT%20English_1748858225045_369095968.pdf, Class 8 Part 2 /eng/8/16/ICT%20English_1759036419216_748030517.pdf, Class 9 Part 1 /eng/9/16/ICT_Eng_IX_1748858267171_290040121.pdf, Class 9 Part 2 /eng/9/16/ICT_1759035833725_234685715.pdf, Class 10 Part 1 /eng/10/16/ICT_1744356521966_36587747.pdf (its cover reads ''Activity Book''), Class 10 Part 2 /eng/10/16/ICT_1759033695822_226884868.pdf. Every book prints ''First Edition 2025''. A KITE circular of 10 March 2025 (No. KITE/2025/1234 (9), docs/1013.pdf, read as a Malayalam scan) says the ICT textbooks for Classes 8, 9 and 10 are revised from 2025-26. A circular of the Director of General Education dated 15 October 2026 (No. DGE/13619/2026-QIP1, docs/1153.pdf, read as a Malayalam scan) sets the 2026-27 half-yearly IT examination for Classes 8 to 10 from 16 October to 10 November 2026. Its portions are named by chapter titles that match Part 1 of the 2025 editions: Class 8 chapters 1 to 4, Class 9 chapters 1 to 4, and for Class 10 Design Factory, Let''s Prepare a Newspaper, the computer language and web page chapters, and The World of Robots. The circular names no edition and does not list the Part 2 chapters. Read closely: Class 8 ch.6 (prepare dataset, train, test; supervised, unsupervised and reinforcement learning; a sign-language image classifier built in PictoBlox), Class 9 ch.6 (AI as data collection, pattern recognition and decision making; models; language models; prompts; a ''Responsible Use of AI'' box at p.17-18), Class 10 ch.3 (binary language and translators, an algorithm defined at p.48, variables, input, if-else and elif with a flowchart, while and for loops, turtle drawing), Class 10 ch.9 (tables linked by IDs, database software, fields, data types, primary key, DB Browser for SQLite), Class 10 ch.6 (sensors, microcontroller, Arduino Uno kit, LED and buzzer programs, a face-detecting door that uses computer vision). Class 8 ch.4 is the first place in the series where variables appear (a Scratch game with ''bullets'' and ''score''). Class 9 ch.3 builds an app in PictoBlox and shows a Python version. Not read in detail: Class 8 ch.1 to 3, 5, 8 to 10; Class 9 ch.1, 2, 5, 7 to 10; Class 10 ch.1, 2, 5, 7, 8, 10. Wording: Class 8 (p.10) and Class 9 (p.8) define AI as imitating human intelligence; the Computational-Core model avoids that vocabulary, which is a difference in framing worth showing educators. Text searches of all ten ICT books found no user-defined functions; binary appears only as machine language (Class 10) and in a note on number systems (Class 9 Part 2). Class 10 ch.3 and ch.9 page ranges come from each book''s contents page. Class 10 ch.4 (p.79-80) tells pupils to check AI answers against reliable sources. Checker (verify-kl-computing, 30 October 2026): chapter lists, page ranges and editions confirmed. Class 8 Part 1 (chapters 1 to 5), Part 2 (chapters 6 to 10), Class 9 Part 1 (chapters 1 to 5), Part 2 (chapters 6 to 10), Class 10 Part 1 (chapters 1 to 6), Part 2 (chapters 7 to 10). All print First Edition 2025. Class 8 chapter 6 and Class 9 chapter 6 define AI as imitating human intelligence. Class 8 chapter 6 covers dataset, training, testing, supervised, unsupervised and reinforcement learning and an Indian Sign Language image classifier in PictoBlox. Class 9 chapter 6 covers language models, prompts and a Responsible Use of AI section. Class 10 chapter 6 ends with a door that opens when a camera detects a face, and says computer vision was learned in previous classes. A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"SCERT Kerala ICT textbooks, English medium, First Edition 2025. Class 8 Part 2 ch.6 Machines That Learn p.7-21 and ch.7 Data Analysis on a Computer p.22-35; Class 8 Part 1 ch.4 Computer Games p.45-60. Class 9 Part 1 ch.3 Let''s Develop Software p.37-47 and ch.4 Data Analysis Made Easy p.48-57; Class 9 Part 2 ch.6 Intelligent Machines p.7-19. Class 10 Part 1 ch.3 Computer Language p.45-66, ch.4 Cyber Space p.67-84, ch.6 The World of Robots from p.98; Class 10 Part 2 ch.9 To the Information Storehouse p.54-69.","description":"The 2025 ICT textbooks for Classes 8 to 10 teach how a computer learns to classify images from labelled examples (Class 8), AI, language models and responsible use (Class 9), and Python programs, database tables and Arduino robotics (Class 10). Classes 8 and 9 also teach spreadsheet data analysis. The books describe AI as imitating human intelligence.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, textbooks prepared by Kerala Infrastructure and Technology for Education (KITE)","mandateType":"curriculum-unit","adoptionDate":"2025","dateGranularity":"year","statementText":"The 2025 ICT textbooks for Classes 8 to 10 teach how a computer learns to classify images from labelled examples (Class 8), AI, language models and responsible use (Class 9), and Python programs, database tables and Arduino robotics (Class 10). Classes 8 and 9 also teach spreadsheet data analysis. The books describe AI as imitating human intelligence.","subject":"computer-science","gradeFrom":8,"gradeTo":10,"topicTags":["machine-learning","artificial-intelligence","python","databases","robotics","spreadsheets","responsible-ai"]}', ''),
  ('df40e4a2-ee34-501e-90dc-3042cd159e82', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-higher-secondary-computer-science-and-computer-applications-2026', 'SCERT Kerala, Higher Secondary Plus One Computer Science and Computer Applications textbooks (2026): data, Python, algorithms, AI', '{"id":"IN-KL-MANDATE-higher-secondary-computer-science-and-computer-applications-2026","label":"SCERT Kerala, Higher Secondary Plus One Computer Science and Computer Applications textbooks (2026): data, Python, algorithms, AI","sourceUrl":"https://samagra.kite.kerala.gov.in/files/samagra-resource/uploads2/tbookscmq/eng/11/33/Computer%20Science_1782381216210_558180826.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Higher Secondary Course Computer Science XI, SCERT Kerala, First Edition 2026: contents (ch.1 Introduction to Computing p.7-20; ch.2 Data Representation and Boolean Algebra p.21-50; ch.3 Computer System Organisation p.51-74 with 3.5 Algorithmic Problem Solving from p.70; ch.4 to 5 Python p.75-102; ch.6 Control Statements p.103-140; ch.7 Functions and Modules p.141-166; ch.9 Lists p.181-206 with linear search at 9.8.1; ch.12 Sorting and Searching p.241-252). Computer Applications (Commerce) XI ch.8 AI and its Applications p.181-206; Computer Applications (Humanities) XI ch.7 AI and Its Applications p.195-220. Both First Edition 2026.. AI-drafted, unreviewed. The AI reader downloaded the books from KITE''s Samagra portal and read their contents pages, forewords and the chapters named above (ch.2 data representation, 3.5, 12.2.1 binary search, the AI chapter headings and the machine learning section of the Commerce book). Class 11 Computer Science: ch.2 covers number systems, integer, floating-point, character (ASCII, Unicode), image (pixels, resolution, colour depth), audio and video representation (printed pages 33 to 38 for floating point, ASCII, Unicode and images). Ch.12 teaches bubble and selection sort and compares linear and binary search by speed and number of comparisons; the AI reader found no formal argument of correctness or count of steps as input grows in the pages read. Ch.7 covers user-defined functions, arguments, scope, recursion, modules. SCERT Kerala''s page https://scert.kerala.gov.in/hss-2026/ carries the heading ''HSS - Plus One Revised Textbooks'' and no printed date. The book list on that page is loaded by script, so the checker could not confirm from the page source that it lists the Computer Science and Computer Applications books. Computer Applications (Commerce) also has Programming Concepts, Elements of Python and Python control structures (p.59-132). Class 12: the Computer Science Part 1 on the portal is a 2015 edition built around C++ (structures, pointers, OOP, data structures, web technology); Part 2 is a scanned file with no text layer and was not read; the Class 12 Computer Applications books were not read. The Higher Secondary syllabus document from the Directorate of Higher Secondary Education was not read because that site did not respond. Whether every Plus One student studies these subjects was not checked (subject-combination rules not read); the AI reader assumes they are chosen subjects. The 2026 foreword states the book''s main focus is problem-solving through Python and lists debugging and testing as practice aims. Checker (verify-kl-computing, 30 October 2026): re-opened the Computer Science book (264 pages, First Edition 2026) and confirmed the contents list and page ranges (chapters 1 to 13 including Strings 167-180, Tuples 207-222, Dictionaries and Sets 223-240, Computers and Society 253-264), section 2.4 data representation, 3.5 algorithmic problem solving, 9.8.1 linear search, 12.1 bubble and selection sort, 12.2.1 binary search. The foreword names problem-solving through Python as the main focus. The two Computer Applications books could not be located on the portal by the checker, so the AI chapter claims (titles, pages, topics) are unconfirmed. Whether Plus One students choose these subjects was not checked. The record covers Class 11 only. A second AI reader could not confirm all of it: Computer Science (Class 11) content is confirmed: contents, page ranges, number systems, character, image, audio and video representation, Boolean algebra, flowcharts, Python chapters, functions and modules, sorting and searching.; The Computer Applications AI chapter claims (Commerce ch.8 p.181-206; Humanities ch.7 p.195-220; machine learning, neural networks, language models, robotics, computer vision, ethics) could not be re-checked. The books could not be found on the portal.; gradeTo is 12 but only the Class 11 book was read in full, and the Class 12 Computer Science Part 1 is a 2015 C++ edition. The record should cover Class 11.; The claim that the SCERT HSS page lists these books could not be confirmed, because the list is built by script. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Higher Secondary Course Computer Science XI, SCERT Kerala, First Edition 2026: contents (ch.1 Introduction to Computing p.7-20; ch.2 Data Representation and Boolean Algebra p.21-50; ch.3 Computer System Organisation p.51-74 with 3.5 Algorithmic Problem Solving from p.70; ch.4 to 5 Python p.75-102; ch.6 Control Statements p.103-140; ch.7 Functions and Modules p.141-166; ch.9 Lists p.181-206 with linear search at 9.8.1; ch.12 Sorting and Searching p.241-252). Computer Applications (Commerce) XI ch.8 AI and its Applications p.181-206; Computer Applications (Humanities) XI ch.7 AI and Its Applications p.195-220. Both First Edition 2026.","description":"The Plus One Computer Science textbook (First Edition 2026) covers number systems, how computers store numbers, text, images, audio and video, Boolean algebra, algorithms with flowcharts, Python (control statements, functions, strings, lists, tuples, dictionaries) and sorting and searching. Its foreword names problem-solving through Python as the main focus. The Plus One Computer Applications books (First Edition 2026) have a chapter on AI.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Government of Kerala General Education Department","mandateType":"curriculum-framework","adoptionDate":"2026","dateGranularity":"year","statementText":"The Plus One Computer Science textbook (First Edition 2026) covers number systems, how computers store numbers, text, images, audio and video, Boolean algebra, algorithms with flowcharts, Python (control statements, functions, strings, lists, tuples, dictionaries) and sorting and searching. Its foreword names problem-solving through Python as the main focus. The Plus One Computer Applications books (First Edition 2026) have a chapter on AI.","subject":"computer-science","gradeFrom":11,"gradeTo":11,"topicTags":["computer-science","data-representation","python","algorithms","sorting-searching","machine-learning","artificial-intelligence"]}', ''),
  ('5faf02c1-9945-57db-9290-43052c8963b7', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kite-little-kites-and-hi-tech-school-lab-programmes', 'KITE, Little KITEs IT clubs and the Hi-Tech School and Hi-Tech Lab projects: student ICT, AI and robotics training, 2018 to 2026', '{"id":"IN-KL-MANDATE-kite-little-kites-and-hi-tech-school-lab-programmes","label":"KITE, Little KITEs IT clubs and the Hi-Tech School and Hi-Tech Lab projects: student ICT, AI and robotics training, 2018 to 2026","sourceUrl":"https://littlekites.kite.kerala.gov.in/index.php/about_lkms","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Little KITEs site, About page and home page (members and schools); ''Little KITEs - Activity Areas'' tables for Class 8 and Class 9 (https://littlekites.kite.kerala.gov.in/assets-home/img/Little%20KITEs%20Syllabus-English.pdf); KITE About Us page https://kite.kerala.gov.in/KITE/index.php/welcome/about_us (Hi-Tech School and Hi-Tech Lab paragraph; 2025 and 2026 timeline lines); KITE order No. KITE/2026/1562-7 (13) dated 29 October 2026, https://kite.kerala.gov.in/KITE/itsadmin/uploads/docs/1158.pdf.. AI-drafted, unreviewed. The AI reader read KITE''s own pages on 30 October 2026. Little KITEs: the site says over 3.80 lakh students have benefited and 1.75 lakh are members in 2060 schools now. A KITE slide deck on the same site (file name carries 23 Oct 2025, no printed date) gives different numbers (2174 schools, 1.80 lakh members), so figures vary by page and date. The deck lists training in animation, robotics and IoT, hardware, electronics, language computing, cyber safety, mobile apps and AI, and says 29,000 Arduino kits reached 2000 schools. The Class 8 and Class 9 activity-area tables are undated and list topics by name only. Class 8 (15 periods): Hi-Tech equipment set-up 1, graphic design 2, animation 2, Malayalam computing 3, media and documentation 5, block programming 2. Class 9 (17 periods): animation 2, mobile app development 2, AI 3, electronics 1, robotics 6, desktop publishing 3. The tables do not say whether the period counts are required or suggested, and no AI session content is given, so no model link is drawn. Members are 8 to 10 (3-year batches such as 2026-29), which the AI reader infers from batch names. Hi-Tech projects (KITE About page): Rs 493 crore Hi-Tech School project, 45,000 classrooms of Classes 8 to 12 in 4752 government and aided schools; Rs 292 crore Hi-Tech Lab project in 11257 primary schools (Classes 1 to 7); the page''s timeline lists ''Robotics and AI included in School curriculum'' under 2025 and, under 2026, expansion of Little KITEs to upper primary and higher secondary, advanced robotic kits and AI training for 6 lakh parents. The 2018 date is the year of the Little KITEs programme on KITE''s timeline and in KITE''s slides; circulars cite a government order No. 361/2018 dated 20 January 2018 that the AI reader did not open. The 29 October 2026 order was read as a Malayalam scan, and the checker re-read it as page images: it is a proceedings order of the KITE Chief Executive Officer, No. KITE/2026/1562-7 (13). It says the Little KITEs Junior pilot was started in two phases (orders of 12 October and 23 October 2026) in 2069 government and aided upper primary schools, and adds 10 more schools in a third phase for 2026-27, with 16 to 25 seats each (list on page 2). A 19 June 2026 circular (docs/1117.pdf) lists an ''Advanced Robotic Kit'' for Little KITEs units, which the AI reader read only at summary level. KITE''s pages for Hi-Tech School, Hi-Tech Lab and ICT Textbooks (welcome/ict/1, 24 and 5) returned an unrelated page, so Hi-Tech figures come from the About page. The public ''AI Essentials'' online course (KITE circular of 22 February 2025) is for adults and is outside the school curriculum. Checker (verify-kl-computing, 30 October 2026): Little KITEs site figures (3.80 lakh benefited, 1.75 lakh members in 2060 schools), the Class 8 and Class 9 activity tables, and the KITE About page figures (Rs 493 crore, 4752 schools, Rs 292 crore, 11257 schools, 2025 and 2026 timeline lines) were re-read and match. Government Order (Ordinary) No. 361/2018 dated 20 January 2018 is the reference in both the 2025-26 and 2026-27 KITE orders the checker read, so the year 2018 fits, but the order itself was not opened. A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Little KITEs site, About page and home page (members and schools); ''Little KITEs - Activity Areas'' tables for Class 8 and Class 9 (https://littlekites.kite.kerala.gov.in/assets-home/img/Little%20KITEs%20Syllabus-English.pdf); KITE About Us page https://kite.kerala.gov.in/KITE/index.php/welcome/about_us (Hi-Tech School and Hi-Tech Lab paragraph; 2025 and 2026 timeline lines); KITE order No. KITE/2026/1562-7 (13) dated 29 October 2026, https://kite.kerala.gov.in/KITE/itsadmin/uploads/docs/1158.pdf.","description":"KITE runs Little KITEs IT clubs in secondary schools. Its Little KITEs site counts 1.75 lakh members in 2060 schools, with training that includes block programming, animation, mobile apps, electronics, robotics and AI. KITE reports Hi-Tech classrooms in 4752 secondary schools and Hi-Tech Labs in 11257 primary schools. An order of 29 October 2026 extends a pilot of Little KITEs Junior clubs to 10 more upper primary schools.","verificationStatus":"primary-source-confirmed","issuingBody":"Kerala Infrastructure and Technology for Education (KITE), Government of Kerala","mandateType":"other","adoptionDate":"2018","dateGranularity":"year","statementText":"KITE runs Little KITEs IT clubs in secondary schools. Its Little KITEs site counts 1.75 lakh members in 2060 schools, with training that includes block programming, animation, mobile apps, electronics, robotics and AI. KITE reports Hi-Tech classrooms in 4752 secondary schools and Hi-Tech Labs in 11257 primary schools. An order of 29 October 2026 extends a pilot of Little KITEs Junior clubs to 10 more upper primary schools.","subject":"computer-science","gradeFrom":8,"gradeTo":10,"topicTags":["little-kites","it-clubs","hi-tech-school","hi-tech-lab","robotics","artificial-intelligence","ict-infrastructure"]}', ''),
  ('380e0e87-3191-54f7-9d58-130d44c9e904', 'kerala-school-curriculum-repository', 'policy-timeline-event', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-EVENT-kite-class-10-robotics-training-order-2025-12-31', 'KITE circular of 31 December 2025: half-day robotics training for all Class 10 students in 2025-26', '{"id":"IN-KL-EVENT-kite-class-10-robotics-training-order-2025-12-31","label":"KITE circular of 31 December 2025: half-day robotics training for all Class 10 students in 2025-26","sourceUrl":"https://kite.kerala.gov.in/KITE/itsadmin/uploads/docs/1087.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: KITE circular No. KITE/2025/1562 (140) dated 31.12.2025, ''Little KITEs 2025-26: instructions on giving robotics training to Class 10 students'', points 1 to 7 (2 pages, Malayalam scan). Class 10 ICT Part 1 (First Edition 2025) ch.6 The World of Robots, from p.98.. AI-drafted, unreviewed. The circular is a scanned Malayalam document; the AI reader rendered the pages to images and read them, so the English wording is the AI reader''s translation. The checker re-read both pages as images. The training is described with the word അർദ്ധദിന, which means half-day. The first draft said one day, which was a misreading. Points read (confirmed by the checker): (1) training follows a KITE module; (2) led by Little KITEs members and KITE mentors, with school IT coordinators and trained teachers as helpers; (3) master trainers brief KITE mentors online by 6 January, then mentors brief members and teachers; (4) all Class 10 students trained by 15 January 2026 in batches, one robotics kit with a laptop per 4 to 5 students; (5) schools without a Little KITEs unit use a nearby unit; (6) each day''s training is logged in the Little KITEs online management system; (7) master trainers confirm completion. A reviewer who reads Malayalam should check these points first. The circular is an instruction to schools with Little KITEs units. The pages read do not report how many students were trained. The textbook chapter was read (sensors, an Arduino Uno robotics kit, LED and buzzer programs, a door that opens on recognising a face), see the Classes 8 to 10 textbook record. Press reports of 18 May 2025 (PTI via The Week, Deccan Herald) say robotics was made mandatory for all Class 10 students from June 2025; the AI reader found no matching notice on a KITE or Department page, and KITE''s About page lists ''Robotics and AI included in School curriculum'' under 2025 without a month. The circular is listed on KITE''s Little KITEs circular page with the date 31-12-2025. No model link: the nearest model part (machines follow rules people write) is a K-2 part, a different stage. Checker (verify-kl-computing, 30 October 2026): circular number KITE/2025/1562 (140), date 31.12.2025, signed by the KITE Chief Executive Officer, addressed to headmasters of all schools with a Little KITEs unit through district coordinators, copy to the Director of General Education and all deputy directors and district education officers. It cites G.O. (Ord.) No. 361/2018 dated 20.01.2018. Its opening says the renewed Class 10 ICT textbook has a special chapter on new technologies including robotics, and that Little KITEs members have had special training in robotics and AI. A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"KITE circular No. KITE/2025/1562 (140) dated 31.12.2025, ''Little KITEs 2025-26: instructions on giving robotics training to Class 10 students'', points 1 to 7 (2 pages, Malayalam scan). Class 10 ICT Part 1 (First Edition 2025) ch.6 The World of Robots, from p.98.","description":"KITE''s chief executive told schools with Little KITEs units to give every Class 10 student a half-day robotics training in 2025-26, led by Little KITEs members and KITE mentors, with one robotics kit and laptop for each 4 to 5 students, finishing by 15 January 2026. The circular says the renewed Class 10 ICT textbook has a special chapter on new technologies including robotics.","verificationStatus":"primary-source-confirmed","slug":"kite-class-10-robotics-training-order-2025-12-31","dateStart":"2025-12-31","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","topicTags":["robotics","class-10","little-kites","ict-textbook","teacher-training"]}', '2025-12-31'),
  ('4977ef6b-f7f3-5db3-ad9b-6e700ff52721', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-national-ct-ai-curriculum-classes-3-8-and-kerala-status', 'CBSE and Ministry of Education, Computational Thinking and AI curriculum for Classes 3 to 8 (2026-27): where Kerala state schools stand', '{"id":"IN-KL-MANDATE-national-ct-ai-curriculum-classes-3-8-and-kerala-status","label":"CBSE and Ministry of Education, Computational Thinking and AI curriculum for Classes 3 to 8 (2026-27): where Kerala state schools stand","sourceUrl":"https://www.pib.gov.in/PressReleasePage.aspx?PRID=2247963","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: PIB release of 1 April 2026 (ID 2247963); PIB release of 30 October 2025 (ID 2184211); PIB release of 5 August 2026 (ID 2295050, Rajya Sabha written reply); CBSE Notification TRG-02 dated 09.04.2026 (https://www.cbse.gov.in/cbsenew/documents/Notification_CT_AI_2026_27_09042026.pdf); CBSE Computational Thinking Class 3 Teacher Handbook, First Edition March 2026.. AI-drafted, unreviewed. National side, read directly: the 1 April 2026 PIB release calls it a CBSE curriculum for Classes 3 to 8 in 2026-27. The 30 October 2025 release says the Department of School Education supports CBSE, NCERT, KVS and NVS ''along with States and Union Territories'' in designing the curriculum through a consultation; it does not name Kerala. The 5 August 2026 Rajya Sabha reply says NCERT with CBSE introduced it, that most schools are under State and Union Territory governments, and that setting up AI and robotics labs is the responsibility of those governments. The CBSE notice of 9 April 2026 is addressed to heads of CBSE-affiliated schools; CBSE schools in Kerala are therefore covered by it, and the AI reader did not count them. The CBSE Class 3 handbook says CBSE built the CT work to run without dependence on any platform; Kerala''s Class 3 ICT book uses GCompris games on school computers. These are different delivery choices, and the AI reader did not compare learning goals (the national records cover the curriculum itself). Kerala side: the AI reader searched or read SCERT Kerala''s home page, framework page and Plus One textbook page; KITE''s home page, About page, AI page and its circular lists for all categories; the Little KITEs site; the General Education Department home page; and KITE''s Samagra textbook listing. None of them mentions the CBSE-NCERT curriculum or an order adopting it. Kerala''s own line since 2016 is separate ICT textbooks (Kalipetti for Classes 1 to 4, e@Vidya for Classes 5 to 7, then the 2024 and 2025 series), a Class 7 AI chapter from the 2024 edition, and the AI and robotics items on KITE''s pages. This is an absence of evidence in the pages searched. A reviewer should ask SCERT Kerala whether any order, circular or workshop on the national curriculum exists. No model link is drawn: this record states a status, and the content comparison belongs to the textbook records. Checker (verify-kl-computing, 30 October 2026): PIB release of 1 April 2026 (launch by the Union Education Minister), PIB release of 30 October 2025 (states and union territories named as supported in a consultation, Kerala not named), PIB release of 5 August 2026 and CBSE notification TRG-02 of 9 April 2026 (addressed to heads of CBSE-affiliated schools) were re-read and match. The checker searched the SCERT Kerala home page, textbook and Plus One pages, the KITE home page, About page and its full circular and order lists, and the General Education Department home page, and found no mention of the CBSE and NCERT curriculum. KITE circulars of 2026 deal with Little KITEs, the IT exam, robotics kits and the Key to Entrance AI training for higher secondary. This is an absence in the pages searched on that date. A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"PIB release of 1 April 2026 (ID 2247963); PIB release of 30 October 2025 (ID 2184211); PIB release of 5 August 2026 (ID 2295050, Rajya Sabha written reply); CBSE Notification TRG-02 dated 09.04.2026 (https://www.cbse.gov.in/cbsenew/documents/Notification_CT_AI_2026_27_09042026.pdf); CBSE Computational Thinking Class 3 Teacher Handbook, First Edition March 2026.","description":"The Computational Thinking and AI curriculum for Classes 3 to 8 was launched by the Union Education Minister on 1 April 2026 as a CBSE curriculum, built with NCERT, for the 2026-27 session. A CBSE notice of 9 April 2026 addresses CBSE-affiliated schools. No SCERT Kerala, KITE or General Education Department page or document searched on 30 October 2026 adopts it for Kerala state schools.","verificationStatus":"primary-source-confirmed","issuingBody":"Central Board of Secondary Education, with NCERT and the Ministry of Education (Government of India); Kerala bodies read: SCERT Kerala, KITE, General Education Department","mandateType":"policy-statement","adoptionDate":"2026-04-01","dateGranularity":"day","statementText":"The Computational Thinking and AI curriculum for Classes 3 to 8 was launched by the Union Education Minister on 1 April 2026 as a CBSE curriculum, built with NCERT, for the 2026-27 session. A CBSE notice of 9 April 2026 addresses CBSE-affiliated schools. No SCERT Kerala, KITE or General Education Department page or document searched on 30 October 2026 adopts it for Kerala state schools.","subject":"computer-science","gradeFrom":3,"gradeTo":8,"topicTags":["computational-thinking","artificial-intelligence","cbse","ncert","state-curriculum","kerala-status"]}', '2026-04-01'),
  ('8e2a6113-77fc-521a-ba03-67ac048b5764', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2023-commissioning-consultation-and-national-positioning', 'Government of Kerala and SCERT Kerala: how the Kerala Curriculum Framework 2023 was set up and prepared (order of 9 March 2022)', '{"id":"IN-KL-MANDATE-kcf-2023-commissioning-consultation-and-national-positioning","label":"Government of Kerala and SCERT Kerala: how the Kerala Curriculum Framework 2023 was set up and prepared (order of 9 March 2022)","sourceUrl":"https://education.kerala.gov.in/wp-content/uploads/2022/03/corecommittee09032022new.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Government of Kerala, General Education Department, G.O.(Ordinary) No. 1498/2022/GEDN dated 09-03-2022: p. 1 (heading, reference to G.O.(Printed) No. 22/2021 of 16-11-2021, paragraphs 1-3, chairperson), p. 2 (member list, convener), p. 3 (distribution list and signature); read as page images. SCERT Kerala, Kerala Curriculum Frameworks: note for community discussion (2022), foreword, printed p. 3 (PDF p. 4; page image). SCERT Kerala, Kerala Curriculum Framework 2023 (School Education, English), Foreword (PDF p. 3), Section 1.2 (printed p. 2), Section 3 (printed pp. 27-30), Section 7 opening (printed pp. 117-118). Printed page = PDF page minus 3 from Section 1 onward.. The AI reader read page 1 of the order of 9 March 2022 as a page image, because its text layer is broken. A second reader re-read all three pages as images and read the Malayalam directly. The order forms the core committee and names four framework areas. The permission to revise and the entrusting of the work to the SCERT director are recited from an earlier order (G.O.(Printed) No. 22/2021 of 16-11-2021), which was not found or read, so the start of the commissioning is earlier than this record''s date. The date of this record is the date printed on the 9 March order. The member list was not copied. A later order of 15 September 2022 (No. 5406/2022/GEDN, page 1 read by the first reader) changes committee members only. The first reader also read the foreword of SCERT''s 2022 note for community discussion; the second reader did not re-open it. The 26 focus groups and over 30 lakh students are the framework''s own statements. On positioning, the framework says on printed pp. 29-30 that the state does not take up every national suggestion because the national emphasis is access and retention while Kerala''s is quality and equity, and on p. 118 that Kerala adapts national positions and sets its own stages. This record reports those statements and takes no view on them. Text search of the English PDF: NCF 2023 named only on printed p. 2; NEP 2020 on pp. 2, 4, 117 and 118; NCF 2005 on pp. 27, 54, 55 and 147. Status of the framework text: SCERT''s framework page labels it a draft (Malayalam word for draft); the English PDF has no draft mark and no printed date beyond 2023; its file properties give 20 May 2025 (a file date only). Press reports dated 10 October 2023 say the Education Minister released the draft on the Monday before (9 October 2023); a third-party listing gives 21 September 2023 (unchecked). No final-approval notice was found. For a stable link, use the SCERT framework page, which links the English PDF. No links: this is a process record. A second AI reader corrected this record against the source (8 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Government of Kerala, General Education Department, G.O.(Ordinary) No. 1498/2022/GEDN dated 09-03-2022: p. 1 (heading, reference to G.O.(Printed) No. 22/2021 of 16-11-2021, paragraphs 1-3, chairperson), p. 2 (member list, convener), p. 3 (distribution list and signature); read as page images. SCERT Kerala, Kerala Curriculum Frameworks: note for community discussion (2022), foreword, printed p. 3 (PDF p. 4; page image). SCERT Kerala, Kerala Curriculum Framework 2023 (School Education, English), Foreword (PDF p. 3), Section 1.2 (printed p. 2), Section 3 (printed pp. 27-30), Section 7 opening (printed pp. 117-118). Printed page = PDF page minus 3 from Section 1 onward.","description":"A Government of Kerala order of 9 March 2022 formed a core committee for the state''s curriculum revision, chaired by the Principal Secretary for General Education, with the SCERT Kerala director as convener. It names four framework areas: pre-school, school, teacher and adult education. It says an earlier order of 16 November 2021 had allowed the revision after NEP 2020 and NCERT guidance, and had given the work to the SCERT director. The framework''s foreword reports 26 focus groups and classroom talks with over 30 lakh students.","verificationStatus":"primary-source-confirmed","issuingBody":"Government of Kerala, Department of General Education, with SCERT Kerala","mandateType":"policy-statement","adoptionDate":"2022-03-09","dateGranularity":"day","statementText":"A Government of Kerala order of 9 March 2022 formed a core committee for the state''s curriculum revision, chaired by the Principal Secretary for General Education, with the SCERT Kerala director as convener. It names four framework areas: pre-school, school, teacher and adult education. It says an earlier order of 16 November 2021 had allowed the revision after NEP 2020 and NCERT guidance, and had given the work to the SCERT director. The framework''s foreword reports 26 focus groups and classroom talks with over 30 lakh students.","subject":"general","topicTags":["curriculum-revision","core-committee","public-consultation","nep-2020","ncf-2023","state-curriculum-framework"]}', '2022-03-09'),
  ('0639ef87-3936-5587-a81e-5b1c50e3885b', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2023-aims-principles-stages-and-curricular-areas', 'Kerala Curriculum Framework 2023 (draft, SCERT Kerala): aims, principles, stages of general education and curricular areas', '{"id":"IN-KL-MANDATE-kcf-2023-aims-principles-stages-and-curricular-areas","label":"Kerala Curriculum Framework 2023 (draft, SCERT Kerala): aims, principles, stages of general education and curricular areas","sourceUrl":"https://drive.google.com/uc?export=download&id=1obj0di-Nh_4aoxigC_EwtDnW3zBvni8t","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Kerala Curriculum Framework 2023 (School Education, English text), SCERT Kerala: Chapter 4 Philosophic Foundation, printed pp. 41-56; Chapter 5 Aims, pp. 57-61; Chapter 6 Approach to the Curriculum, pp. 62-116 (6.1 to 6.7; 6.6.6 on pp. 100-101); Section 7 opening and 7.1 stages, pp. 117-129 (stage names p. 118; primary in two parts p. 121); Chapter 8 Approach to Subjects, pp. 130-182 (8.2.1 computational thinking, pp. 145-147). Printed page = PDF page minus 3.. The AI reader read the English PDF of the framework (223 PDF pages) from the link on SCERT Kerala''s framework page, which labels it a draft (see the first record for status and date). Read in full: Chapters 1, 4, 5, 7, 9, 10 and 11. Read in part: Chapters 2, 3, 6 (6.1, 6.5, 6.6.6) and 8 (8.1, 8.2 on computational thinking, 8.3, 8.4). The 16 aims are numbered on printed pp. 58-61. Stage detail: childcare and development from age 3; primary has a first stage of Classes 1-4 and a second of Classes 5-7 (p. 121); Classes 8-10 have languages, core subjects and optional subjects, with a choice of subject areas from Class 8, optional subjects from Class 9 and artificial intelligence named among possible optional subjects, all worded as proposals (pp. 124-125); Classes 11-12 are covered in the Higher Secondary record. Cross-cutting chapters: 6.2 inclusive education, 6.3 gender justice, 6.4 value education, 6.5 environment, 6.6 ICT, 6.7 work-integrated education. In the sections read the framework gives approaches and stage-level content ideas. No class-by-class learning standards were seen. Mapping to model bands: Kerala''s Classes 1-4 and 5-7 stages cut across the model''s 3-5 and 6-8 bands, so link by class number. The computational-thinking passage (pp. 146-147) and the suggestion of coding and Python in ICT (p. 101) are the basis of the one context link to the Computational-Core model. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2023 (School Education, English text), SCERT Kerala: Chapter 4 Philosophic Foundation, printed pp. 41-56; Chapter 5 Aims, pp. 57-61; Chapter 6 Approach to the Curriculum, pp. 62-116 (6.1 to 6.7; 6.6.6 on pp. 100-101); Section 7 opening and 7.1 stages, pp. 117-129 (stage names p. 118; primary in two parts p. 121); Chapter 8 Approach to Subjects, pp. 130-182 (8.2.1 computational thinking, pp. 145-147). Printed page = PDF page minus 3.","description":"SCERT Kerala''s page labels the framework a draft. It gives 16 aims, among them social justice, scientific temper, environmental awareness and vocational skills, and builds on constitutional values, social constructivism and critical pedagogy. Section 7.1 names three stages of general education: childcare from age 3, primary (Classes 1 to 7) and secondary (Classes 8 to 12). Subject chapters cover languages, mathematics, science, social science, art, and health and physical education; mathematics is framed around computational thinking.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, for the Department of General Education","mandateType":"curriculum-framework","adoptionDate":"2023","dateGranularity":"year","statementText":"SCERT Kerala''s page labels the framework a draft. It gives 16 aims, among them social justice, scientific temper, environmental awareness and vocational skills, and builds on constitutional values, social constructivism and critical pedagogy. Section 7.1 names three stages of general education: childcare from age 3, primary (Classes 1 to 7) and secondary (Classes 8 to 12). Subject chapters cover languages, mathematics, science, social science, art, and health and physical education; mathematics is framed around computational thinking.","subject":"general","gradeFrom":1,"gradeTo":12,"topicTags":["aims-of-education","school-stages","curricular-areas","social-constructivism","critical-pedagogy","computational-thinking"]}', ''),
  ('5c43ec25-caeb-5767-a720-55e9dc53b5f0', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2023-integrated-learning-learner-experience-and-assessment', 'Kerala Curriculum Framework 2023 (SCERT Kerala): integrated learning, the child as knowledge builder, and assessment', '{"id":"IN-KL-MANDATE-kcf-2023-integrated-learning-learner-experience-and-assessment","label":"Kerala Curriculum Framework 2023 (SCERT Kerala): integrated learning, the child as knowledge builder, and assessment","sourceUrl":"https://drive.google.com/uc?export=download&id=1obj0di-Nh_4aoxigC_EwtDnW3zBvni8t","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Kerala Curriculum Framework 2023 (School Education, English text), SCERT Kerala: Section 1.3, printed pp. 4-10 (child as constructor of knowledge, p. 8; children''s opinion, pp. 9-10; four skills, p. 7); interdisciplinary bullet, p. 37; Sections 6.1.1-6.1.3, pp. 63-67 (Classes 1-2 and Class 3, p. 67); Section 6.5 Environmental Education, pp. 86-92; science content, p. 161; social science, pp. 165-171; Chapter 9 Assessment, pp. 184-196. Printed page = PDF page minus 3.. The AI reader read the passages listed and searched the whole English PDF text for ''competen'' (no hits) and ''interdisciplin'' (hits on printed pp. 37, 44, 163, 167, 170 and 219, and ''inter-disciplinary'' on p. 171). A second reader repeated the ''competen'' search on layout text, raw text and whitespace-stripped text and found no hit; only competitive and competition occur. The Malayalam text was not searched. The project that crosses subjects is stated in the science section (p. 161: each learner should take at least one project on a local issue where subjects can be integrated). The wording is mostly ''should'' or ''can be'' because this is a framework. Subject categories from Class 3 ''can be'' used (p. 67). The need to reduce summative tests is stated as a need (p. 192); dropping grades for continuous assessment is stated as ''may be dropped'' (p. 190); portfolios and the Holistic Progress Card are on p. 188; assessment for, as and of learning are on p. 185. Facts used by the links: (1) p. 63 describes a cycle of posing a problem, an own attempt, a class presentation, agreed norms and revision, and asks for looking back on one''s own thinking (p. 8; p. 185 on self-assessment); (2) pp. 87-89 put environment education across subjects and p. 89 lists mitigating the side effects of human intervention in nature; (3) p. 169 lists the origin and evolution of man with cultural varieties, cultural change and migration as content to be explained with several social science disciplines, and pp. 168-169 name democratic systems and family; aims 8 and 10 on pp. 59-60 name a historic and cultural sense and awareness of technology; (4) p. 170 says the integrated approach continues in Classes 1 and 2 and that familiar social institutions are learned through experience. Not compared with the interdisciplinary chapter of NCF-SE 2023, which has its own national record. No early-years statement that lines up with a Class 3-5 model part was found, so there is no 3-5 link. A second AI reader corrected this record against the source (6 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2023 (School Education, English text), SCERT Kerala: Section 1.3, printed pp. 4-10 (child as constructor of knowledge, p. 8; children''s opinion, pp. 9-10; four skills, p. 7); interdisciplinary bullet, p. 37; Sections 6.1.1-6.1.3, pp. 63-67 (Classes 1-2 and Class 3, p. 67); Section 6.5 Environmental Education, pp. 86-92; science content, p. 161; social science, pp. 165-171; Chapter 9 Assessment, pp. 184-196. Printed page = PDF page minus 3.","description":"SCERT Kerala''s page labels the framework a draft. It promotes integrated, theme-based learning in Classes 1 and 2 and allows subject labels from Class 3. Its science section asks each learner for one cross-subject project on a local issue; environment education runs through all subjects. The child is a builder of knowledge. The English text never uses the word competency; it speaks of objectives, outcomes, abilities and skills. It favours formative assessment, with portfolios and a Holistic Progress Card, and suggests fewer summative tests.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, for the Department of General Education","mandateType":"curriculum-framework","adoptionDate":"2023","dateGranularity":"year","statementText":"SCERT Kerala''s page labels the framework a draft. It promotes integrated, theme-based learning in Classes 1 and 2 and allows subject labels from Class 3. Its science section asks each learner for one cross-subject project on a local issue; environment education runs through all subjects. The child is a builder of knowledge. The English text never uses the word competency; it speaks of objectives, outcomes, abilities and skills. It favours formative assessment, with portfolios and a Holistic Progress Card, and suggests fewer summative tests.","subject":"general","gradeFrom":1,"gradeTo":12,"topicTags":["interdisciplinary-learning","integrated-approach","knowledge-construction","formative-assessment","environment-education","learner-voice"]}', ''),
  ('11a9e8ad-c424-5637-ba51-2a0b5e5c29d6', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2007-to-2023-continuity-and-changes', 'Kerala Curriculum Framework 2023 compared with Kerala Curriculum Framework 2007 (SCERT Kerala): what continues and what changes', '{"id":"IN-KL-MANDATE-kcf-2007-to-2023-continuity-and-changes","label":"Kerala Curriculum Framework 2023 compared with Kerala Curriculum Framework 2007 (SCERT Kerala): what continues and what changes","sourceUrl":"https://www.slideshare.net/slideshow/kerala-curriculamframework2007/57455173","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: Kerala Curriculum Framework 2007 (SCERT Kerala, 88 pages; third-party copy): Preface pp. 5-9 (p. 7 on mother tongue and the trilingual system), Chapter 3 passage on issue-based textbooks p. 28, Chapter 4 The Stages of Education pp. 30-37 (4.3, 4.4), Section 5.8 Evaluation, Section 6.1.2 pp. 75-76. Compared with Kerala Curriculum Framework 2023 (School Education, English text): Section 1.2 p. 2; Section 2.4 pp. 22-24; Section 3 pp. 27-30; Section 1.3 p. 9 (evolving textbook); pp. 5-6 and 112 (AI, robotics); Section 7.1 pp. 118-129.. The 2023 side was read directly in the English PDF on SCERT''s framework page (labelled a draft there). The 2007 side was read as a third-party copy (a SlideShare upload of the SCERT 2007 print, whose contents page matches the 88-page SCERT document). No copy was found on SCERT''s or the Department''s current pages. A second reader found that the Internet Archive indexes SCERT''s own 2007 files (English: http://www.scert.kerala.gov.in/images/docs/kcf_englishfinal.pdf, captures 2012 and 2018; also http://www.scert.kerala.gov.in/2011pdf/kcf_final1.pdf and http://www.scert.kerala.gov.in/kcf8_07_0.pdf; Malayalam: http://www.scert.kerala.gov.in/images/docs/kcf8_07malayalam.pdf) but could not download them (HTTP 429 from the Archive), so the record stays secondary-source-only. A reviewer should open the English capture and check each statement that 2007 lacks a topic. Every such statement applies to the third-party copy read. A text search of that copy by the first reader found no ''disaster'' or ''global warming'', climate only in a school-calendar sentence, and no ''evolving textbook''; the second reader saw the same words absent in the first 36 of 88 pages. The 2007 copy has a section on IT-assisted education, so ICT itself is not new in 2023. 2023 says 2007 made many suggestions on work and vocational skills that were not carried out (p. 35). 2023 describes the 2007 framework as developed from NCF 2005 after public discussion, stressing inquiry learning (pp. 24, 27, 28), and says that a 2013 policy document stressed learning outcomes and the present textbooks were built on it (pp. 2, 24, 28); the 2013 document was not read. Stage comparison: the first reader reports 2007 sections 4.3 and 6.1 giving secondary as Classes 8-10 and higher secondary as 11-12, and 6.1.2 giving primary as Classes 1-7 (lower 1-4, upper 5-7). The second reader confirmed Classes 8-10 and 11-12 (p. 34 of the copy) and could not see 6.1.2, so the 2007 primary range is left out of the statement. 2023 Section 7.1 gives primary Classes 1-7 and secondary Classes 8-12 (printed p. 118). No links: a comparison record. A second AI reader could not confirm all of it: Official copy (task point c): not obtained, so the record stays secondary-source-only. SCERT''s current site has no KCF 2007 file. The Internet Archive''s index lists captures of SCERT''s own files: http://www.scert.kerala.gov.in/images/docs/kcf_englishfinal.pdf (captured 16 October 2012 with status 200, and a snapshot of 27 August 2018), http://www.scert.kerala.gov.in/2011pdf/kcf_final1.pdf (31 May 2011), http://www.scert.kerala.gov.in/kcf8_07_0.pdf (26 December 2010) and the Malayalam http://www.scert.kerala.gov.in/images/docs/kcf8_07malayalam.pdf (7 September 2012). So an official copy exists in the archive. The checker could not download any of them: the Archive answered every file request with HTTP 429, the live www.scert host did not connect, and the web-fetch tool cannot reach the Archive. A reviewer on an ordinary browser should open the English 2012 capture and re-check the points below.; What the checker could see: a SlideShare copy read through a web-fetch tool, first 36 of 88 pages only. In those pages the words disaster, global warming, climate change, artificial intelligence, robotics and evolving textbook do not appear (closest: ''victims of natural and man-made calamities'' on p. 18; ''flexible textbooks'' on p. 14). Secondary and higher secondary are given as Classes 8 to 10 and 11 and 12 (p. 34). The claim that 2007 gives primary as Classes 1 to 7 rests on Section 6.1.2 (pp. 75-76), which is outside the pages the checker could see. In the visible pages primary appears as lower primary and upper primary with no class numbers. That claim is not confirmed.; The 2023 side was re-checked in the English PDF. Evolving textbook: printed p. 9 (''we must switch to the concept of evolving textbook'' with changes each year); this is a proposal and no current practice. Climate change and disaster: pp. 1, 3, 6 and 36 (Section 1.2, p. 3, says disaster handling now has to be part of the curriculum). AI and robotics: pp. 5-6 and 112. Continuation: the foreword says KCF 2023 builds on KCF 2007; printed p. 30 says KCF 2007 was designed as a continuation of the 1997-98 revision and that its main visions are kept in view for 2023; p. 27 says KCF 2007 developed in the context of NCF 2005. The statement''s ''calls itself a continuation of KCF 2007'' should read ''says it builds on KCF 2007''. Issue-based learning: pp. 27, 62, 90, 91. Social constructivism and critical pedagogy: pp. 7, 46-56, 62-63.; Wording: ''KCF 2023 adds ... climate change and disaster risk, AI and robotics'' states as fact that these are absent from 2007. That holds only for the copy read, and only for the part of it that either reader saw. Every statement about what 2007 lacks must be worded as applying to the copy read. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2007 (SCERT Kerala, 88 pages; third-party copy): Preface pp. 5-9 (p. 7 on mother tongue and the trilingual system), Chapter 3 passage on issue-based textbooks p. 28, Chapter 4 The Stages of Education pp. 30-37 (4.3, 4.4), Section 5.8 Evaluation, Section 6.1.2 pp. 75-76. Compared with Kerala Curriculum Framework 2023 (School Education, English text): Section 1.2 p. 2; Section 2.4 pp. 22-24; Section 3 pp. 27-30; Section 1.3 p. 9 (evolving textbook); pp. 5-6 and 112 (AI, robotics); Section 7.1 pp. 118-129.","description":"KCF 2023 says it builds on KCF 2007 and keeps social constructivism, critical pedagogy and issue-based learning. It adds NEP 2020 and NCF 2023 as backdrop, climate change and disaster risk, AI and robotics, and a proposal for an ''evolving textbook''. A third-party copy of KCF 2007 (unchecked against an official copy) lacks disaster, global warming, AI, robotics and an evolving textbook. It puts Classes 8 to 10 in secondary and 11 and 12 in higher secondary; KCF 2023 groups Classes 8 to 12 as one secondary stage.","verificationStatus":"secondary-source-only","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala","mandateType":"curriculum-framework","adoptionDate":"2023","dateGranularity":"year","statementText":"KCF 2023 says it builds on KCF 2007 and keeps social constructivism, critical pedagogy and issue-based learning. It adds NEP 2020 and NCF 2023 as backdrop, climate change and disaster risk, AI and robotics, and a proposal for an ''evolving textbook''. A third-party copy of KCF 2007 (unchecked against an official copy) lacks disaster, global warming, AI, robotics and an evolving textbook. It puts Classes 8 to 10 in secondary and 11 and 12 in higher secondary; KCF 2023 groups Classes 8 to 12 as one secondary stage.","subject":"general","topicTags":["kcf-2007","kcf-2023","ncf-2005","curriculum-continuity","school-stages","issue-based-learning"]}', ''),
  ('a03c6972-8c7c-57ad-ad65-e47f7a55bbf6', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2023-language-policy-and-mother-tongue-instruction', 'Kerala Curriculum Framework 2023 (SCERT Kerala): language policy, mother-tongue instruction and the three-language curriculum', '{"id":"IN-KL-MANDATE-kcf-2023-language-policy-and-mother-tongue-instruction","label":"Kerala Curriculum Framework 2023 (SCERT Kerala): language policy, mother-tongue instruction and the three-language curriculum","sourceUrl":"https://drive.google.com/uc?export=download&id=1obj0di-Nh_4aoxigC_EwtDnW3zBvni8t","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Kerala Curriculum Framework 2023 (School Education, English text), SCERT Kerala: Section 3.2, printed p. 38 (medium of instruction); Section 6.1.4 Medium of instruction, pp. 68-71; Section 7.1.1, p. 120 (pre-school); Section 7.1.3, pp. 124-125; Section 7.1.4, p. 127 (English at higher secondary); Section 8.1, p. 131 (three-language statement); Section 8.1.2, pp. 134-136; Section 8.1.7, pp. 142-145 (English p. 143, Hindi p. 144, Arabic, Sanskrit and Urdu pp. 144-145). Printed page = PDF page minus 3.. The AI reader read the passages listed in the English PDF. ''Tri-lingual'' is the framework''s own word (p. 131). The framework gives reasons for mother-tongue instruction from psychology, brain research and named thinkers (pp. 68-71); they are not summarised here. The wording is mostly ''should''. The framework says foreign languages are open to Classes 11 and 12 (p. 131). SCERT''s textbook pages list books in Malayalam, English, Tamil and Kannada media. The 2007 framework also keeps the trilingual system and mother-tongue medium (Preface p. 7 and Sections 5.1.7-5.1.8 of the third-party copy read); see the comparison record. No links: no part of the four models concerns the language of instruction. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2023 (School Education, English text), SCERT Kerala: Section 3.2, printed p. 38 (medium of instruction); Section 6.1.4 Medium of instruction, pp. 68-71; Section 7.1.1, p. 120 (pre-school); Section 7.1.3, pp. 124-125; Section 7.1.4, p. 127 (English at higher secondary); Section 8.1, p. 131 (three-language statement); Section 8.1.2, pp. 134-136; Section 8.1.7, pp. 142-145 (English p. 143, Hindi p. 144, Arabic, Sanskrit and Urdu pp. 144-145). Printed page = PDF page minus 3.","description":"Kerala follows a three-language curriculum of the mother tongue, English and Hindi, and learners can take Tamil, Kannada, Arabic, Sanskrit or Urdu as a first language alongside Malayalam. The framework says teaching should be in the mother tongue, with regional dialects respected. English is taught from Class 1, and Hindi runs from Class 5 to 10 as the third language and is the second language at higher secondary.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, for the Department of General Education","mandateType":"curriculum-framework","adoptionDate":"2023","dateGranularity":"year","statementText":"Kerala follows a three-language curriculum of the mother tongue, English and Hindi, and learners can take Tamil, Kannada, Arabic, Sanskrit or Urdu as a first language alongside Malayalam. The framework says teaching should be in the mother tongue, with regional dialects respected. English is taught from Class 1, and Hindi runs from Class 5 to 10 as the third language and is the second language at higher secondary.","subject":"language","gradeFrom":1,"gradeTo":12,"topicTags":["language-policy","mother-tongue","medium-of-instruction","three-language-curriculum","english","hindi"]}', ''),
  ('90672188-0d31-5653-b266-aa5020b66618', 'kerala-school-curriculum-repository', 'policy-timeline-event', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-EVENT-revised-textbooks-rollout-2024-25-and-2025-26', 'Government of Kerala and SCERT Kerala: revised textbooks reach Classes 1, 3, 5, 7, 9 in 2024-25 and Classes 2, 4, 6, 8, 10 in 2025-26', '{"id":"IN-KL-EVENT-revised-textbooks-rollout-2024-25-and-2025-26","label":"Government of Kerala and SCERT Kerala: revised textbooks reach Classes 1, 3, 5, 7, 9 in 2024-25 and Classes 2, 4, 6, 8, 10 in 2025-26","sourceUrl":"https://education.kerala.gov.in/wp-content/uploads/2024/07/textbooks12072024.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Government of Kerala, General Education Department, G.O.(Ordinary) No. 4387/2024/GEDN dated 12-07-2024, p. 1 (read as a page image; its references cite an earlier order, No. 2458/2024 of 27-03-2024, for the first-volume prices). SCERT Kerala website pages: revised textbooks for Classes I, III, V, VII, IX (part 1) at /curriculum-2024/; Classes II, IV, VI, VIII at /2-8-tb/; Class X part 2 at /10thp2/. Printed imprint pages of Basic Science Standard VI Part 1 (First Edition 2025), Physics Standard X Part 2 (First Edition 2025) and Mathematics Standard I Part I (Second Edition 2025), all SCERT Kerala, English medium.. Primary evidence: the order of 12 July 2024 (title read as ''fixing the price of the 133 titles of the second volume of the curriculum-revised textbooks of Classes 1, 3, 5, 7, 9 for 2024-25''; its text layer is broken, so it was read as an image by the first reader and again by a second reader); SCERT''s own listing pages, which carry no dates; and the printed edition marks of three books. The 12 July order is a price order. It says the second-volume books keep the 2023-24 price and attaches a price table. The Class 1 mathematics copy on SCERT''s page is a Second Edition 2025 reprint, and its first-edition year was not read. No dated order or SCERT notice that starts the 2025-26 step was found by either reader, so 2025-26 rests on the 2025 first-edition marks and on press reports: Onmanorama, 20 July 2023 (plan: Classes 1, 3, 5, 7, 9 in 2024-25; Classes 2, 4, 6, 8, 10 in 2025-26); Careers360, 16 January 2024 (173 titles approved for Classes 1, 3, 5, 7, 9; Classes 2, 4, 6, 8, 10 due in 2025); Onmanorama, 27 January 2025 (steering committee to approve revised titles for Classes 2, 4, 6, 8; Class 10 titles approved the month before); Onmanorama, 1 February 2026 (revised books up to Class 10 over the past two years). The Department''s order No. 5264/2026/GEDN of 4 August 2026 allows the 2024-25 printing rate for 2025-26 textbooks; it names no classes. SCERT''s What''s New page lists these books under their class numbers and shows no dates, so the page order is not a date. Whether the 2025 and 2026 editions read are the ones in classrooms in 2026-27 was not checked. None of the Class 1-10 books read names the Kerala Curriculum Framework 2023 in its front matter (the Plus One English reader does), so the tie between these books and the framework rests on the order''s words ''curriculum-revised'' and on press reports. Class 12 is not covered here. No links: a timetable record. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Government of Kerala, General Education Department, G.O.(Ordinary) No. 4387/2024/GEDN dated 12-07-2024, p. 1 (read as a page image; its references cite an earlier order, No. 2458/2024 of 27-03-2024, for the first-volume prices). SCERT Kerala website pages: revised textbooks for Classes I, III, V, VII, IX (part 1) at /curriculum-2024/; Classes II, IV, VI, VIII at /2-8-tb/; Class X part 2 at /10thp2/. Printed imprint pages of Basic Science Standard VI Part 1 (First Edition 2025), Physics Standard X Part 2 (First Edition 2025) and Mathematics Standard I Part I (Second Edition 2025), all SCERT Kerala, English medium.","description":"Curriculum-revised textbooks went to Classes 1, 3, 5, 7 and 9 in 2024-25. A government order of 12 July 2024 set prices for the 133 second-volume titles for those classes; an earlier order of 27 March 2024 covered first volumes. Revised books for Classes 2, 4, 6, 8 and 10 followed. Press reports and the 2025 first-edition mark on two books read place them in 2025-26. No official notice giving that date was found. SCERT lists these books without dates.","verificationStatus":"primary-source-confirmed","slug":"revised-textbooks-rollout-2024-25-and-2025-26","dateStart":"2024","dateGranularity":"year","eventType":"other","temporalStatus":"past-completed","topicTags":["textbook-revision","rollout-timetable","scert-textbooks","2024-25","2025-26"]}', ''),
  ('ae05f343-744a-5cf1-a979-a773122be77a', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kerala-school-curriculum-governance-scert-dge-pareeksha-bhavan-ssk', 'SCERT Kerala and the Department of General Education: who sets and delivers the school curriculum in Kerala', '{"id":"IN-KL-MANDATE-kerala-school-curriculum-governance-scert-dge-pareeksha-bhavan-ssk","label":"SCERT Kerala and the Department of General Education: who sets and delivers the school curriculum in Kerala","sourceUrl":"https://scert.kerala.gov.in/about-scert/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: SCERT Kerala website: About SCERT Kerala; Department of Curriculum, Text Books and Evaluation (roles and responsibilities). Department of General Education portal (education.kerala.gov.in), pages SCERT, Directorate of General Education, Pareekshabhavan, Samagra Shiksha Kerala, KITE (IT@School Project). Kerala Curriculum Framework 2023 (School Education, English text), Section 2.2 on the unified directorate, printed pp. 20-21; Section 10.3.1 State level, pp. 199-201. All web pages read on 30 October 2026.. The web pages are undated, so no adoption date is given; the descriptions are as read on 30 October 2026 by the first reader and re-read the same day by a second reader. Details from the pages read: SCERT was set up in 1994; the Education Minister chairs its governing body, the Secretary for General Education is vice chair and the SCERT director is convener; SCERT also advises the government on school-education policy. The Director of General Education is the former Director of Public Instruction and heads the department; the department is organised by revenue district and by educational district and sub-district offices, and Class 12 was brought under it after three separate directorates were merged (framework printed pp. 20-21; the DGE page says only that school education up to Class 12 was combined under one directorate after the 2009 Right to Education Act). The Directorate of Higher Secondary Education dates from an order of June 1990 (framework printed p. 20; the DGE page gives no date). Samagra Shiksha is described on the department''s page as a programme from pre-school to Class 12 that subsumes SSA, RMSA and Teacher Education; the page says nothing about what Samagra Shiksha Kerala itself runs beyond naming a State Project Director. IT@School was transformed into KITE in August 2017, per the department''s page; the page lists ICT infrastructure, ICT textbooks, teacher ICT training, a TV channel and the Samagra Content Portal among KITE''s activities. The portal''s name has no stated link to the Samagra Shiksha scheme. Textbooks are printed by the Kerala Books and Publications Society (imprint of a Class 6 book; the order of 22 November 2023 cites the society). Government orders of the General Education Department set up committees and fix textbook prices (the orders of 9 March 2022 and 12 July 2024 were read). A Curriculum Steering Committee chaired by the Education Minister approves textbook titles according to press reports in January 2024 and January 2025; no Department page naming it was read. Office-holders'' names are left out on purpose. No links: a governance record. A second AI reader corrected this record against the source (7 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"SCERT Kerala website: About SCERT Kerala; Department of Curriculum, Text Books and Evaluation (roles and responsibilities). Department of General Education portal (education.kerala.gov.in), pages SCERT, Directorate of General Education, Pareekshabhavan, Samagra Shiksha Kerala, KITE (IT@School Project). Kerala Curriculum Framework 2023 (School Education, English text), Section 2.2 on the unified directorate, printed pp. 20-21; Section 10.3.1 State level, pp. 199-201. All web pages read on 30 October 2026.","description":"SCERT Kerala, an autonomous body of the Department of General Education, is responsible for curriculum, textbooks, teacher handbooks and teacher training from pre-school to higher secondary. The Director of General Education heads the department and is also Commissioner for Government Examinations; Pareeksha Bhavan is that office and conducts SSLC, K-TET and similar exams. Samagra Shiksha Kerala is the state office of the Samagra Shiksha school programme. KITE, formerly IT@School, runs ICT programmes for schools. The 2023 framework says Samagra Shiksha Kerala should plan under SCERT''s academic supervision.","verificationStatus":"primary-source-confirmed","issuingBody":"Department of General Education, Government of Kerala (with SCERT Kerala, Pareeksha Bhavan, Samagra Shiksha Kerala and KITE)","mandateType":"other","statementText":"SCERT Kerala, an autonomous body of the Department of General Education, is responsible for curriculum, textbooks, teacher handbooks and teacher training from pre-school to higher secondary. The Director of General Education heads the department and is also Commissioner for Government Examinations; Pareeksha Bhavan is that office and conducts SSLC, K-TET and similar exams. Samagra Shiksha Kerala is the state office of the Samagra Shiksha school programme. KITE, formerly IT@School, runs ICT programmes for schools. The 2023 framework says Samagra Shiksha Kerala should plan under SCERT''s academic supervision.","subject":"general","gradeFrom":1,"gradeTo":12,"topicTags":["governance","scert-kerala","directorate-of-general-education","pareeksha-bhavan","samagra-shiksha-kerala","kite"]}', ''),
  ('cee79f57-3722-55dd-87b7-2d10621ec793', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kerala-higher-secondary-classes-11-12-kcf-2023-and-revised-plus-one-2026', 'SCERT Kerala: Higher Secondary (Classes 11 and 12) in the Kerala Curriculum Framework 2023 and the revised Plus One books for 2026-27', '{"id":"IN-KL-MANDATE-kerala-higher-secondary-classes-11-12-kcf-2023-and-revised-plus-one-2026","label":"SCERT Kerala: Higher Secondary (Classes 11 and 12) in the Kerala Curriculum Framework 2023 and the revised Plus One books for 2026-27","sourceUrl":"https://drive.google.com/uc?export=download&id=1obj0di-Nh_4aoxigC_EwtDnW3zBvni8t","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Kerala Curriculum Framework 2023 (School Education, English text), SCERT Kerala: Section 7.1.4 Classes 11, 12, printed pp. 126-129; Section 2.2, p. 20; Chapter 11, pp. 217-220. SCERT Kerala website page ''Revised Higher Secondary first year textbooks'' (/hss-2026/, 41 titles). Higher Secondary Course English XI Part I (SCERT Kerala, First Edition 2026), foreword. SCERT Kerala, Plus One Scheme of Work 2026-27 (45-page PDF linked from What''s New), cover, Anthropology scheme (printed p. 11) and Computer Science scheme (printed p. 41) read. Printed page = PDF page minus 3 for the framework.. The framework wording is a proposal throughout: English compulsory ''as at present'', a change to three compulsory subjects and one optional ''can also be considered'', social service ''for at least six months'' (p. 127), a credit system as proposed for Classes 8-10, and seminar papers in continuous assessment (p. 128). The framework says courses are now offered as Science, Humanities and Commerce (p. 126) and that about 7.5 lakh students are in higher secondary (p. 20), and Higher Secondary began in schools in 1990 (p. 20). Chapter 11 (p. 219) proposes interdisciplinary and multidisciplinary courses and a choice of subject combinations. The English reader''s foreword says it was developed in accordance with the framework; no other book read says so. The scheme-of-work PDF is a bundle of subject schemes, some pages marked DRAFT, with units, months and periods or scores; the Plus One Anthropology scheme lists units on social-cultural, biological, archaeological and linguistic anthropology, and the Computer Science scheme lists Python and data chapters, with titles only. Neither Physics, Chemistry, Biology, Mathematics, Economics, History nor Political Science appears in that PDF or in SCERT''s 41-title list, and which books those subjects use was not established. SCERT also hosts six ''additional textbooks'' (Class 11 economics, history, political science; Class 12 history, political science, sociology) that its page describes as incorporating topics deleted by NCERT. No Class 12 revised-book list was found. No links: the Anthropology course might be worth a reader''s look against the cross-system strands, but only unit titles were read. A second AI reader could not confirm all of it: Checked and confirmed: framework Section 7.1.4 (printed pp. 126-127): Classes 11 and 12 organised as language, core and vocational subjects with choice of compulsory and optional subjects; English compulsory ''as it is currently in practice''; three compulsory subjects and one optional ''can also be considered''; social service, Student Police Cadet or voluntary service for at least six months, which the text words with ''compulsorily'' inside a list of should-statements. SCERT''s page ''HSS - Plus One Revised Textbooks'' (scert.kerala.gov.in/hss-2026/) lists 41 numbered titles.; Not re-opened by the checker: the English XI Part I foreword (First Edition 2026), the 45-page scheme-of-work PDF and the ''additional textbooks'' page. Those claims stay as the first reader gave them.; The social-service line uses the word ''compulsorily'' in the source. The statement should say so, so a reader does not take it as softer than the text. Draft label: not mentioned in the record. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2023 (School Education, English text), SCERT Kerala: Section 7.1.4 Classes 11, 12, printed pp. 126-129; Section 2.2, p. 20; Chapter 11, pp. 217-220. SCERT Kerala website page ''Revised Higher Secondary first year textbooks'' (/hss-2026/, 41 titles). Higher Secondary Course English XI Part I (SCERT Kerala, First Edition 2026), foreword. SCERT Kerala, Plus One Scheme of Work 2026-27 (45-page PDF linked from What''s New), cover, Anthropology scheme (printed p. 11) and Computer Science scheme (printed p. 41) read. Printed page = PDF page minus 3 for the framework.","description":"SCERT Kerala''s page labels the framework a draft. For Classes 11 and 12 it proposes language, core and vocational subjects with elective choice, English as a compulsory language, three compulsory subjects and one optional subject as an idea to examine, and at least six months of social service, which the text words as compulsory. SCERT lists 41 revised Plus One (Class 11) textbooks for 2026-27, including a First Edition 2026 English reader built on the framework, and a scheme of work with some pages marked draft.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, for the Department of General Education","mandateType":"curriculum-framework","adoptionDate":"2026","dateGranularity":"year","statementText":"SCERT Kerala''s page labels the framework a draft. For Classes 11 and 12 it proposes language, core and vocational subjects with elective choice, English as a compulsory language, three compulsory subjects and one optional subject as an idea to examine, and at least six months of social service, which the text words as compulsory. SCERT lists 41 revised Plus One (Class 11) textbooks for 2026-27, including a First Edition 2026 English reader built on the framework, and a scheme of work with some pages marked draft.","subject":"general","gradeFrom":11,"gradeTo":12,"topicTags":["higher-secondary","class-11","class-12","plus-one","revised-textbooks","scheme-of-work"]}', ''),
  ('5c730bcc-6742-5fb6-a674-479ff2b77386', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2023-science-aims-and-methods', 'SCERT Kerala, Kerala Curriculum Framework 2023 (School Education; SCERT''s page labels it a draft): learning science', '{"id":"IN-KL-MANDATE-kcf-2023-science-aims-and-methods","label":"SCERT Kerala, Kerala Curriculum Framework 2023 (School Education; SCERT''s page labels it a draft): learning science","sourceUrl":"https://scert.kerala.gov.in/kerala-curriculum-framework-2023/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Kerala Curriculum Framework 2023 (School Education), English PDF, 223 pages: Chapter 5 aim 9 (p. 59); Chapter 7, sections 7.1 to 7.1.3 on stages (pp. 117-123); Chapter 8, section 8.3 Learning Science, subsections 8.3.1 to 8.3.6 (pp. 157-165).. The AI readers read the English PDF of the framework (223 pages) and the SCERT framework page. SCERT''s page marks the framework as a draft (site menu ''Draft''; Malayalam heading). The PDF prints no draft label, month or day, and its file properties (created 20 May 2025) are not an issue date. A press report (Onmanorama, 10 Oct 2023, secondary) says the draft was released on 9 October 2023; SCERT has not been asked to confirm. Section 8.3 (printed pp. 157-165) gives aims and methods only, with no outcomes by class or stage. Not read: the Malayalam edition, the pre-school and adult education frameworks, and the focus-group papers. The textbooks read do not name the framework, so the link between framework and books rests on press reports. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2023 (School Education), English PDF, 223 pages: Chapter 5 aim 9 (p. 59); Chapter 7, sections 7.1 to 7.1.3 on stages (pp. 117-123); Chapter 8, section 8.3 Learning Science, subsections 8.3.1 to 8.3.6 (pp. 157-165).","description":"SCERT Kerala''s school-education framework, which SCERT''s own page labels a draft, sets aims for learning science: observation, experiment and generalisation, a scientific attitude that includes re-examining what is known and telling science from pseudo-science, and textbooks that give weight to the history of science. Science enters the primary classes as Environmental Studies. The science section gives aims and methods and sets no outcomes by class or stage.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, for the Core Committee on Curriculum Reform","mandateType":"curriculum-framework","adoptionDate":"2023","dateGranularity":"year","statementText":"SCERT Kerala''s school-education framework, which SCERT''s own page labels a draft, sets aims for learning science: observation, experiment and generalisation, a scientific attitude that includes re-examining what is known and telling science from pseudo-science, and textbooks that give weight to the history of science. Science enters the primary classes as Environmental Studies. The science section gives aims and methods and sets no outcomes by class or stage.","subject":"science","gradeFrom":1,"gradeTo":12,"topicTags":["nature of science","scientific method","inquiry","history of science","pseudo-science","school stages"]}', ''),
  ('0cb852ab-e63d-577b-b744-620efc18204d', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-scert-kerala-class10-biology-genetics-of-life-2025', 'SCERT Kerala, Biology Standard X Part 1 (2025), Chapter 1 Genetics of Life: DNA, Mendel and sources of variation', '{"id":"IN-KL-UNIT-scert-kerala-class10-biology-genetics-of-life-2025","label":"SCERT Kerala, Biology Standard X Part 1 (2025), Chapter 1 Genetics of Life: DNA, Mendel and sources of variation","sourceUrl":"https://scert.kerala.gov.in/class-x/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Biology, Standard X, Part 1, English medium, First Edition 2025: Contents; Chapter 1 Genetics of Life, pp. 7-34 (Let us Assess on pp. 33-34).. The AI readers read the whole chapter in the English medium PDF (SCERT Class X page, Drive file 13Ahoa8RygMUCS1v0RPS2M0KtR9GAFgqu). The title page prints ''First Edition : 2025''. The chapter defines mutation as a sudden heritable change and names copying errors, chemicals and radiation as causes (p. 31). It does not say mutation is undirected. SCERT does not say which edition is used in 2026-27. Second reader (stage evidence): read the contents pages of the Class 3 and Class 4 Environmental Science books (Parts 1 and 2) and of the Class 5 to 9 science books (both parts), and searched the extracted text of all 14 books for gene, inherit, variation, adaptation, species, evolution, fossil, extinct, Darwin, Lamarck, natural selection, mutation and ancestor. Text inside pictures is not covered. SCERT''s textbook lists show no environment or science book for Classes 1 and 2 (Malayalam, English reader and mathematics only), so Classes 1 and 2 were not read. Findings: Class 4 Part 1 Chapter 1 (p. 10) defines adaptation. No book for Classes 3 to 9 uses natural selection, Darwin, Lamarck, mutation or allele. Gene appears only in passing (Class 8 Part 1 p. 112 on genetically modified crops; Class 8 Part 2 pp. 264-267 on classification; a Class 9 Part 2 box on muscular dystrophy). Class 8 Part 2 Chapter 18 teaches chromosomes and meiosis (pp. 302-303) and calls twins'' traits hereditary (pp. 304-305). Class 7 Part 1 teaches hybridisation (pp. 17-19). A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Biology, Standard X, Part 1, English medium, First Edition 2025: Contents; Chapter 1 Genetics of Life, pp. 7-34 (Let us Assess on pp. 33-34).","description":"Chapter 1 teaches the structure of DNA, chromosomes, genes and RNA, and how proteins are made. It then explains heredity and variation through Mendel''s pea experiments, alleles, monohybrid and dihybrid crosses, and patterns that depart from Mendel''s, such as incomplete dominance and multiple alleles. It names crossing over and mutation as sources of variation and says mutation matters in evolution.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education","mandateType":"curriculum-unit","adoptionDate":"2025","dateGranularity":"year","statementText":"Chapter 1 teaches the structure of DNA, chromosomes, genes and RNA, and how proteins are made. It then explains heredity and variation through Mendel''s pea experiments, alleles, monohybrid and dihybrid crosses, and patterns that depart from Mendel''s, such as incomplete dominance and multiple alleles. It names crossing over and mutation as sources of variation and says mutation matters in evolution.","subject":"science","gradeFrom":10,"gradeTo":10,"topicTags":["heredity","variation","genes","alleles","Mendel","mutation","crossing over","non-Mendelian inheritance"]}', ''),
  ('f1551ec7-32a8-53de-9518-8512fd1c5ecb', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-scert-kerala-class10-biology-paths-of-evolution-2025', 'SCERT Kerala, Biology Standard X Part 1 (2025), Chapter 2 Paths of Evolution: resistance, Lamarck, Darwin, speciation', '{"id":"IN-KL-UNIT-scert-kerala-class10-biology-paths-of-evolution-2025","label":"SCERT Kerala, Biology Standard X Part 1 (2025), Chapter 2 Paths of Evolution: resistance, Lamarck, Darwin, speciation","sourceUrl":"https://scert.kerala.gov.in/class-x/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Biology, Standard X, Part 1, English medium, First Edition 2025: Contents; Chapter 2 Paths of Evolution, pp. 35-70. Evolution content on pp. 36-53 (resistance case 36-37, Lamarck 38, Darwin 39-43, Lamarck and Darwin compared 43-44, Neo-Darwinism 45, speciation and tree 45-47, evidence 47-50, human tree 51-53); brain and nervous system pp. 54-67; Let us Assess pp. 68-69; Extended activities p. 70.. The AI readers read pages 35 to 70 of the English medium PDF (First Edition 2025, SCERT Class X page). The printed contents list Chapter 3, Behind Sensations, from p. 71, so pages 54 to 70 sit inside Chapter 2. Wording in the chapter includes ''survival of the fittest'' (p. 42) and says Lamarck''s idea was later shown wrong (p. 38). Genetic drift, allele frequency and artificial selection are not discussed. Population genetics is named only as a field (pp. 32, 45). Neither this book nor the other SCERT books read refers to NCERT''s removal of evolution from its Class 10 chapter. SCERT does not say which edition is used in 2026-27. Second reader (stage evidence): read the contents pages of the Class 3 and Class 4 Environmental Science books (Parts 1 and 2) and of the Class 5 to 9 science books (both parts), and searched the extracted text of all 14 books for gene, inherit, variation, adaptation, species, evolution, fossil, extinct, Darwin, Lamarck, natural selection, mutation and ancestor. Text inside pictures is not covered. SCERT''s textbook lists show no environment or science book for Classes 1 and 2 (Malayalam, English reader and mathematics only), so Classes 1 and 2 were not read. Findings: Class 4 Part 1 Chapter 1 (p. 10) defines adaptation. No book for Classes 3 to 9 uses natural selection, Darwin, Lamarck, mutation or allele. Gene appears only in passing (Class 8 Part 1 p. 112 on genetically modified crops; Class 8 Part 2 pp. 264-267 on classification; a Class 9 Part 2 box on muscular dystrophy). Class 8 Part 2 Chapter 18 teaches chromosomes and meiosis (pp. 302-303) and calls twins'' traits hereditary (pp. 304-305). Class 7 Part 1 teaches hybridisation (pp. 17-19). A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Biology, Standard X, Part 1, English medium, First Edition 2025: Contents; Chapter 2 Paths of Evolution, pp. 35-70. Evolution content on pp. 36-53 (resistance case 36-37, Lamarck 38, Darwin 39-43, Lamarck and Darwin compared 43-44, Neo-Darwinism 45, speciation and tree 45-47, evidence 47-50, human tree 51-53); brain and nervous system pp. 54-67; Let us Assess pp. 68-69; Extended activities p. 70.","description":"Chapter 2 opens with a tuberculosis case in which resistant bacteria arose by mutation, then compares Lamarck''s and Darwin''s accounts of the giraffe''s neck and sets out natural selection with the Galapagos finches. It adds later genetic findings, explains speciation by isolation, gives molecular, anatomical and fossil evidence, and presents the human evolutionary tree. The second half of the chapter covers the nervous system.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education","mandateType":"curriculum-unit","adoptionDate":"2025","dateGranularity":"year","statementText":"Chapter 2 opens with a tuberculosis case in which resistant bacteria arose by mutation, then compares Lamarck''s and Darwin''s accounts of the giraffe''s neck and sets out natural selection with the Galapagos finches. It adds later genetic findings, explains speciation by isolation, gives molecular, anatomical and fossil evidence, and presents the human evolutionary tree. The second half of the chapter covers the nervous system.","subject":"science","gradeFrom":10,"gradeTo":10,"topicTags":["evolution","natural selection","Lamarck","Darwin","speciation","fossils","antibiotic resistance","human evolution"]}', ''),
  ('094b9f49-d045-5881-9bb7-22d2507a8c45', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-scert-kerala-class8-basic-science-origin-of-life-and-diversity-2025', 'SCERT Kerala, Basic Science Standard VIII (2025), Chapters 8, 16 and 17: origin of life, tree of life, biodiversity', '{"id":"IN-KL-UNIT-scert-kerala-class8-basic-science-origin-of-life-and-diversity-2025","label":"SCERT Kerala, Basic Science Standard VIII (2025), Chapters 8, 16 and 17: origin of life, tree of life, biodiversity","sourceUrl":"https://scert.kerala.gov.in/2-8-tb/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Basic Science, Standard VIII, English medium, title page year 2025: Part 1, Chapter 8 Origin of Life, Origin of Living Things, pp. 122-133; Part 2, Chapter 16 Tree of Life, pp. 255-268, and Chapter 17 The Beauty of Diversity, pp. 269-286.. The AI readers read Part 1 Chapter 8 and Part 2 Chapters 16 and 17 in the English medium PDFs and the cell division pages of Chapter 18 (pp. 302-305). Title pages print 2025 with no ''First Edition'' line. Chapter 8 describes the Urey-Miller experiment as evidence for the chemical evolution theory (pp. 123-126) and says the direction of evolution is difficult to predict (p. 132). Chapter 16 says all humans share a common ancestor and belong to one species (p. 267). Chapter 17 says Kerala ranked first among Indian states for new animal species found in 2024 (p. 270) and, on p. 272, says ants evolved adaptations to different habitats, which is why many species emerged. Chapter 18 teaches chromosomes, mitosis and meiosis without naming genes. Second reader (stage evidence): read the contents pages of the Class 3 and Class 4 Environmental Science books (Parts 1 and 2) and of the Class 5 to 9 science books (both parts), and searched the extracted text of all 14 books for gene, inherit, variation, adaptation, species, evolution, fossil, extinct, Darwin, Lamarck, natural selection, mutation and ancestor. Text inside pictures is not covered. SCERT''s textbook lists show no environment or science book for Classes 1 and 2 (Malayalam, English reader and mathematics only), so Classes 1 and 2 were not read. Findings: Class 4 Part 1 Chapter 1 (p. 10) defines adaptation. No book for Classes 3 to 9 uses natural selection, Darwin, Lamarck, mutation or allele. Gene appears only in passing (Class 8 Part 1 p. 112 on genetically modified crops; Class 8 Part 2 pp. 264-267 on classification; a Class 9 Part 2 box on muscular dystrophy). Class 8 Part 2 Chapter 18 teaches chromosomes and meiosis (pp. 302-303) and calls twins'' traits hereditary (pp. 304-305). Class 7 Part 1 teaches hybridisation (pp. 17-19). A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Basic Science, Standard VIII, English medium, title page year 2025: Part 1, Chapter 8 Origin of Life, Origin of Living Things, pp. 122-133; Part 2, Chapter 16 Tree of Life, pp. 255-268, and Chapter 17 The Beauty of Diversity, pp. 269-286.","description":"Chapter 8 introduces evolution as change in living things linked to changes in their surroundings, using a fossil whale ancestor, two theories of the origin of life and a timeline. Chapter 16 covers the history of classification and says modern classification uses evolutionary and genetic relationships. Chapter 17 covers biodiversity at three levels: variation within a species, species, and ecosystems.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education","mandateType":"curriculum-unit","adoptionDate":"2025","dateGranularity":"year","statementText":"Chapter 8 introduces evolution as change in living things linked to changes in their surroundings, using a fossil whale ancestor, two theories of the origin of life and a timeline. Chapter 16 covers the history of classification and says modern classification uses evolutionary and genetic relationships. Chapter 17 covers biodiversity at three levels: variation within a species, species, and ecosystems.","subject":"science","gradeFrom":8,"gradeTo":8,"topicTags":["evolution","origin of life","classification","biodiversity","adaptation","deep time"]}', ''),
  ('049c5a09-c157-5066-bb22-c07eea5bd654', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-scert-kerala-class9-biology-evolution-evidence-and-classification-2024', 'SCERT Kerala, Biology Standard IX Part 2 (2024): evolution in ''Behind Movements'' and Chapter 6 Classification', '{"id":"IN-KL-UNIT-scert-kerala-class9-biology-evolution-evidence-and-classification-2024","label":"SCERT Kerala, Biology Standard IX Part 2 (2024): evolution in ''Behind Movements'' and Chapter 6 Classification","sourceUrl":"https://scert.kerala.gov.in/textbook2024part2/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Biology, Standard IX, Part 2, English medium, First Edition 2024: Contents; ''Bones and Evolution'' and ''Life history from Bones'', pp. 106-107 (within the chapter Behind Movements, pp. 87-112); Chapter 6 Classification, pp. 139-154 (Evolutionary Tree pp. 151-152, DNA Barcoding pp. 152-153, Let us Assess p. 154).. The AI readers read the two passages and the Classification chapter in the English medium PDF. Page 2 prints ''First Edition : 2024''. The passage on p. 107 says the picture of evolution rests on evidence and credits ancient-DNA work with the 2022 Nobel Prize. Part 1 (life processes, digestion, respiration) and the Reproductive Health chapter of Part 2 were searched and hold no genes-as-inheritance or evolution text (gene appears only in passing). Second reader (stage evidence): read the contents pages of the Class 3 and Class 4 Environmental Science books (Parts 1 and 2) and of the Class 5 to 9 science books (both parts), and searched the extracted text of all 14 books for gene, inherit, variation, adaptation, species, evolution, fossil, extinct, Darwin, Lamarck, natural selection, mutation and ancestor. Text inside pictures is not covered. SCERT''s textbook lists show no environment or science book for Classes 1 and 2 (Malayalam, English reader and mathematics only), so Classes 1 and 2 were not read. Findings: Class 4 Part 1 Chapter 1 (p. 10) defines adaptation. No book for Classes 3 to 9 uses natural selection, Darwin, Lamarck, mutation or allele. Gene appears only in passing (Class 8 Part 1 p. 112 on genetically modified crops; Class 8 Part 2 pp. 264-267 on classification; a Class 9 Part 2 box on muscular dystrophy). Class 8 Part 2 Chapter 18 teaches chromosomes and meiosis (pp. 302-303) and calls twins'' traits hereditary (pp. 304-305). Class 7 Part 1 teaches hybridisation (pp. 17-19). A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Biology, Standard IX, Part 2, English medium, First Edition 2024: Contents; ''Bones and Evolution'' and ''Life history from Bones'', pp. 106-107 (within the chapter Behind Movements, pp. 87-112); Chapter 6 Classification, pp. 139-154 (Evolutionary Tree pp. 151-152, DNA Barcoding pp. 152-153, Let us Assess p. 154).","description":"A short section in the movement chapter says the picture of evolution is built from genetics, embryology and fossils, and uses body frameworks, bipedal walking and ancient DNA as examples. Chapter 6 on classification covers the three-domain system, how an evolutionary tree is drawn from shared features (pupils analyse a given tree), and DNA barcoding.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"A short section in the movement chapter says the picture of evolution is built from genetics, embryology and fossils, and uses body frameworks, bipedal walking and ancient DNA as examples. Chapter 6 on classification covers the three-domain system, how an evolutionary tree is drawn from shared features (pupils analyse a given tree), and DNA barcoding.","subject":"science","gradeFrom":9,"gradeTo":9,"topicTags":["evolution","fossils","evolutionary tree","classification","DNA barcoding","evidence"]}', ''),
  ('12af96f9-be7d-54b8-a4da-5f2bac39da61', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-scert-kerala-class5-and-class7-basic-science-diverse-organisms-and-hybridization-2024', 'SCERT Kerala, Basic Science Standard V Part 2 Ch. 8 and Standard VII Part 1 Ch. 1 (2024): diverse organisms, hybridization', '{"id":"IN-KL-UNIT-scert-kerala-class5-and-class7-basic-science-diverse-organisms-and-hybridization-2024","label":"SCERT Kerala, Basic Science Standard V Part 2 Ch. 8 and Standard VII Part 1 Ch. 1 (2024): diverse organisms, hybridization","sourceUrl":"https://scert.kerala.gov.in/textbook2024part2/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Basic Science, Standard V, Part 2, English medium, 2024: Chapter 8 Diverse Organisms, pp. 139-157 (adaptations pp. 146-148, extinct creatures p. 153). Basic Science, Standard VII, Part 1, English medium, First Edition 2024: Chapter 1 Towards A Hundredfold Yield, pp. 7-26 (hybridization pp. 17-19).. The AI readers read both chapters in the English medium PDFs. Class 5 Part 1 prints ''First Edition : 2024''; Class 5 Part 2 prints 2024 only; Class 7 Part 1 prints ''First Edition : 2024''. Chapter 8 of Class 5 gives causes of extinction (p. 153). The Class 7 text does not use the words gene, heredity or selection for hybrids. Second reader (stage evidence): read the contents pages of the Class 3 and Class 4 Environmental Science books (Parts 1 and 2) and of the Class 5 to 9 science books (both parts), and searched the extracted text of all 14 books for gene, inherit, variation, adaptation, species, evolution, fossil, extinct, Darwin, Lamarck, natural selection, mutation and ancestor. Text inside pictures is not covered. SCERT''s textbook lists show no environment or science book for Classes 1 and 2 (Malayalam, English reader and mathematics only), so Classes 1 and 2 were not read. Findings: Class 4 Part 1 Chapter 1 (p. 10) defines adaptation. No book for Classes 3 to 9 uses natural selection, Darwin, Lamarck, mutation or allele. Gene appears only in passing (Class 8 Part 1 p. 112 on genetically modified crops; Class 8 Part 2 pp. 264-267 on classification; a Class 9 Part 2 box on muscular dystrophy). Class 8 Part 2 Chapter 18 teaches chromosomes and meiosis (pp. 302-303) and calls twins'' traits hereditary (pp. 304-305). Class 7 Part 1 teaches hybridisation (pp. 17-19). A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Basic Science, Standard V, Part 2, English medium, 2024: Chapter 8 Diverse Organisms, pp. 139-157 (adaptations pp. 146-148, extinct creatures p. 153). Basic Science, Standard VII, Part 1, English medium, First Edition 2024: Chapter 1 Towards A Hundredfold Yield, pp. 7-26 (hybridization pp. 17-19).","description":"In Class 5, Diverse Organisms covers life cycles, how fish and tadpoles are adapted to water, groups of animals sorted by body features, and creatures that have become extinct. In Class 7, a chapter on better yields teaches grafting, budding and hybridization, in which two varieties are crossed by hand pollination to produce seeds with chosen qualities.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"In Class 5, Diverse Organisms covers life cycles, how fish and tadpoles are adapted to water, groups of animals sorted by body features, and creatures that have become extinct. In Class 7, a chapter on better yields teaches grafting, budding and hybridization, in which two varieties are crossed by hand pollination to produce seeds with chosen qualities.","subject":"science","gradeFrom":5,"gradeTo":7,"topicTags":["adaptation","extinction","classification of animals","hybridization","plant breeding","life cycles"]}', ''),
  ('aec21d23-15de-5fe3-b0ee-e678d45624d9', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-samagra-kerala-class12-biology-file-inheritance-and-evolution', 'Kerala Samagra textbook portal (KITE): Class XII Biology file listed for Botany and Zoology, chapters on inheritance, DNA and Evolution', '{"id":"IN-KL-UNIT-samagra-kerala-class12-biology-file-inheritance-and-evolution","label":"Kerala Samagra textbook portal (KITE): Class XII Biology file listed for Botany and Zoology, chapters on inheritance, DNA and Evolution","sourceUrl":"https://samagra.kite.kerala.gov.in/files/samagra-resource/uploads/tbookscmq/Class_XII/Biology/Biology.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Class XII Biology PDF on the Samagra portal (path Class_XII/Biology, 286 pages; printed page numbers equal PDF page numbers): Chapter 5 Principles of Inheritance and Variation, pp. 69-94; Chapter 6 Molecular Basis of Inheritance, pp. 95-125; Chapter 7 Evolution, pp. 126-142.. The AI readers downloaded the file and read the opening pages of Chapters 5, 6 and 7 and sections 7.1 to 7.9 of the Evolution chapter. The file has no title or copyright page. Its text matches NCERT''s earlier Class 12 Biology (16 chapters): the unit-opening text and the Maheshwari box are word for word the same as in NCERT''s own Class 12 Biology ''Reprint 2026-27'' file. NCERT''s current book has a shorter reproduction unit, so this file is the older text. The Samagra catalogue lists Class 12 ''Botany'' and ''Zoology'' (English medium) as two subjects that both open this file. No date is printed, so no date is given. Not established: whether Kerala schools use this book or NCERT''s revised book in 2026-27, whether Botany and Zoology have separate books, and the Evolution chapter number in Kerala''s course. SCERT''s lists show no Higher Secondary Biology, Botany or Zoology book. Treat every link from this record as a statement about the file and not about Kerala''s Class 12 course. A second AI reader could not confirm all of it: Identification: the file has no title, publisher, edition or copyright page. The page 2 box on Panchanan Maheshwari only says he led NCERT''s 1964 Biology textbooks for Higher Secondary schools. The match to NCERT''s earlier Class 12 Biology can now be shown another way: NCERT''s own site serves its Class 12 Biology ''Reprint 2026-27'' (file lebo101.pdf), whose unit-opening text and Maheshwari box are word for word the same as this file, while the current NCERT book has fewer chapters (it starts with Sexual Reproduction in Flowering Plants). This file has 16 chapters, starting with Reproduction in Organisms, so it is the older NCERT text. That is a content match and not a publisher statement.; Use in Kerala: SCERT''s own pages could not settle it. SCERT''s revised Plus One list for 2026 (hss-2026) has no Biology, Botany or Zoology book, and its ''HSS - Additional Textbooks'' page (topics deleted by NCERT) lists six humanities books and no science book. The Samagra portal''s own catalogue (public API getSubjectTextbooks, English medium, Class 12) lists ''Botany'' and ''Zoology'' as two subjects that both point to this one Biology file (/Class_XII/Biology/Biology.pdf, 201,818,257 bytes, 286 pages). The Malayalam medium list has one ''Biology'' entry pointing to a different file (Class_XII/MAL_MED/Biology.pdf, about 21 MB), which was not opened. So the file is the Biology text that Kerala''s portal offers for Class 12, but no Kerala source seen says which edition schools use in 2026-27, or whether Kerala has moved to NCERT''s revised Class 12 Biology. The Dec 2025 upload stamps in the portal''s Class 12 Physics file names show the portal is updated, yet its Biology entry still points to the 2021 file.; Book-level questions in the task: no separate Botany and Zoology textbooks were found. A third-party study site lists Evolution as Chapter 5 of the Zoology course and another lists it as Chapter 7 of Botany; in this file it is Chapter 7. Which chapter number Kerala''s course uses was not established, so the record names Chapter 7 of this file only.; Date: 2021 comes only from the PDF properties (created 4 Aug 2021) and the server header (modified 6 Aug 2021; the portal''s copy under uploads2 is dated 10 Apr 2025). No date is printed. It is not an adoption date, so it is removed.; Page references: the file''s printed page numbers equal its PDF page numbers. Chapter 5 starts at p. 69 (the record says about p. 79). Chapter 6 starts at p. 95 (record: about p. 96). Chapter 7 runs pp. 126-142 and Chapter 8 starts at p. 143 (record: end page not confirmed).; Content claims checked and correct: Hardy-Weinberg principle with allele frequencies summing to one (pp. 136-137); five factors named as gene flow, genetic drift, mutation, genetic recombination and natural selection (p. 137); founder effect; stabilising, directional and disruptive selection (Figure 7.8); adaptive radiation (7.4); origin of life (7.1); human origins (7.9). The statement says the file ''teaches'' this, which presumes Kerala schools use it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Class XII Biology PDF on the Samagra portal (path Class_XII/Biology, 286 pages; printed page numbers equal PDF page numbers): Chapter 5 Principles of Inheritance and Variation, pp. 69-94; Chapter 6 Molecular Basis of Inheritance, pp. 95-125; Chapter 7 Evolution, pp. 126-142.","description":"A 286-page Class XII Biology file on Kerala''s Samagra portal covers Mendel''s laws, mutation and genetic disorders (Chapter 5), the molecular basis of inheritance (Chapter 6) and Evolution (Chapter 7). Chapter 7 covers origin of life, evidence, adaptive radiation, natural selection, the Hardy-Weinberg principle with five factors that change allele frequencies, and human origins.","verificationStatus":"primary-source-confirmed","issuingBody":"Text of NCERT''s earlier 16-chapter Class 12 Biology book, hosted on the Kerala Samagra textbook portal (KITE, General Education Department)","mandateType":"curriculum-unit","adoptionDate":"2021","dateGranularity":"year","statementText":"A 286-page Class XII Biology file on Kerala''s Samagra portal covers Mendel''s laws, mutation and genetic disorders (Chapter 5), the molecular basis of inheritance (Chapter 6) and Evolution (Chapter 7). Chapter 7 covers origin of life, evidence, adaptive radiation, natural selection, the Hardy-Weinberg principle with five factors that change allele frequencies, and human origins.","subject":"science","gradeFrom":12,"gradeTo":12,"topicTags":["evolution","Hardy-Weinberg","allele frequency","genetic drift","natural selection","inheritance","adaptive radiation"]}', ''),
  ('9a67f63d-e7ce-517a-836e-9c8fb5dbc21d', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-scert-kerala-basic-science-classes-5-8-guess-test-record-and-science-diary', 'SCERT Kerala, Basic Science Standards V to VIII (2024-2025): guess, test and record in a Science Diary', '{"id":"IN-KL-MANDATE-scert-kerala-basic-science-classes-5-8-guess-test-record-and-science-diary","label":"SCERT Kerala, Basic Science Standards V to VIII (2024-2025): guess, test and record in a Science Diary","sourceUrl":"https://scert.kerala.gov.in/curriculum-2024/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Basic Science, English medium: Standard V Part 1 (First Edition 2024), Chapter 3 Water and Life and Chapter 4 Seeds of Life (guess-and-check passages); Standard VI Part 1 (First Edition 2025), preface and Chapter 4 around pp. 62-66; Standard VII Part 1 (First Edition 2024), Chapter 2 around p. 33 and the history box on p. 46; Standard VIII Part 1 (2025), preface.. The AI reader read the prefaces of the Class 6 and Class 8 books and sampled passages in the Class 5, 6 and 7 books found by keyword search for ''guess'', ''assumption'' and ''Science Diary''. The sample is not a full read of the four books. Page numbers are given only where a printed page number could be matched (Class 6 and Class 7). Class 7 Part 1 has the instruction to experiment and check whether assumptions are right (about p. 33). Class 6 Part 1 asks pupils to record assumptions in the Science Diary (about pp. 62-66). The Class 5 floating-objects table asks for a guess and a finding in separate columns. The Class 5 and Class 7 books are 2024 editions and the Class 6 and Class 8 books are 2025 editions. This record describes a teaching pattern seen in the books. It is not stated as a requirement in the framework or in a syllabus, and no syllabus document was read. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Basic Science, English medium: Standard V Part 1 (First Edition 2024), Chapter 3 Water and Life and Chapter 4 Seeds of Life (guess-and-check passages); Standard VI Part 1 (First Edition 2025), preface and Chapter 4 around pp. 62-66; Standard VII Part 1 (First Edition 2024), Chapter 2 around p. 33 and the history box on p. 46; Standard VIII Part 1 (2025), preface.","description":"The Basic Science books for Classes 5 to 8 repeatedly ask pupils to make a guess or assumption, test it with a simple experiment, and write observations and inferences in a Science Diary. The Class 6 preface invites pupils to work as budding scientists through observation, experiment, seminars and projects. A few chapters add short histories of how a scientific idea developed.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education","mandateType":"other","adoptionDate":"2024","dateGranularity":"year","statementText":"The Basic Science books for Classes 5 to 8 repeatedly ask pupils to make a guess or assumption, test it with a simple experiment, and write observations and inferences in a Science Diary. The Class 6 preface invites pupils to work as budding scientists through observation, experiment, seminars and projects. A few chapters add short histories of how a scientific idea developed.","subject":"science","gradeFrom":5,"gradeTo":8,"topicTags":["nature of science","inquiry","science diary","experiment","guess and test","history of science"]}', ''),
  ('f604bd08-9901-52fd-9a97-271e3b1940f3', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2023-social-science-objectives-content-and-stage-guidance', 'SCERT Kerala, Kerala Curriculum Framework 2023 (marked draft on the SCERT page), section 8.4 Learning Social Science', '{"id":"IN-KL-MANDATE-kcf-2023-social-science-objectives-content-and-stage-guidance","label":"SCERT Kerala, Kerala Curriculum Framework 2023 (marked draft on the SCERT page), section 8.4 Learning Social Science","sourceUrl":"https://scert.kerala.gov.in/kerala-curriculum-framework-2023/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Kerala Curriculum Framework 2023 (School Education), English edition: Chapter 8 Approach to Subjects, section 8.4 Learning Social Science (8.4.1 Objectives, 8.4.2 Content with level-wise guidance, 8.4.3 Learning Process, 8.4.4 Learning Materials, 8.4.5 Assessment Methods), printed pages 165 to 173. Stage names: chapter 7 Different Stages of School Education (printed pages 117 to 129), section 7.1 from p. 118, with 7.1.2 Primary Education and 7.1.3 Secondary Education on pp. 121 to 126.. The checker read section 8.4 and chapter 7 in the English PDF linked from the SCERT page (223 pages; printed page numbers run 3 behind PDF page numbers). The SCERT page titles the framework ''Curriculum Framework 2023 (Draft)''. The PDF has no printed date and its foreword does not use the word draft. Its file properties show 20 May 2025 and were not used as a date. A Careers360 report of 10 Oct 2023 says the minister made the draft public at an event on the Monday before (the exact day is not stated); a school-news site lists 21 Sep 2023. No order or notification adopting a final text was found, so the year 2023 rests on the title and these reports, and the PDF read may differ from the October 2023 draft. The foreword is signed for the Core Committee on Curriculum Reform by the SCERT Director and the Principal Secretary, General Education. Section 8.4 gives objectives and content guidance. A text search for ''learning standard'', ''learning outcome'' and ''competency'' found no stage-wise learning standards for social science. Instructions use ''should'' or ''can''; no hours or marks are set, and the Class 11 and 12 core course is a recommendation. Kerala''s own stages (section 7.1): preschool; primary (Classes 1 to 7, with Classes 1 to 4 and 5 to 7 as two phases); secondary (Classes 8 to 12). Map by class number. The English text reads roughly in places, so only short phrases are quoted. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2023 (School Education), English edition: Chapter 8 Approach to Subjects, section 8.4 Learning Social Science (8.4.1 Objectives, 8.4.2 Content with level-wise guidance, 8.4.3 Learning Process, 8.4.4 Learning Materials, 8.4.5 Assessment Methods), printed pages 165 to 173. Stage names: chapter 7 Different Stages of School Education (printed pages 117 to 129), section 7.1 from p. 118, with 7.1.2 Primary Education and 7.1.3 Secondary Education on pp. 121 to 126.","description":"The framework asks for Social Science that draws on six disciplines: history, geography, political science, economics, sociology and business studies, with local, national and world examples. Its listed aims include reading media critically, understanding how cultures mix through migration, and holding values such as pluralism, social justice and gender justice. It recommends an integrated approach in Classes 1 to 7, says subject-based study can begin at the secondary stage (Class 8 on), and recommends a shared Social Science core course in Classes 11 and 12 across Science, Humanities and Commerce.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, for the Department of General Education, Government of Kerala","mandateType":"curriculum-framework","adoptionDate":"2023","dateGranularity":"year","statementText":"The framework asks for Social Science that draws on six disciplines: history, geography, political science, economics, sociology and business studies, with local, national and world examples. Its listed aims include reading media critically, understanding how cultures mix through migration, and holding values such as pluralism, social justice and gender justice. It recommends an integrated approach in Classes 1 to 7, says subject-based study can begin at the secondary stage (Class 8 on), and recommends a shared Social Science core course in Classes 11 and 12 across Science, Humanities and Commerce.","subject":"social-science","gradeFrom":1,"gradeTo":12,"topicTags":["social science","citizenship","constitutional values","gender justice","social institutions","cultural diversity","migration","curriculum framework"]}', ''),
  ('457efafd-f38e-5113-b03e-3fc89a397751', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-kcf-2023-aims-value-education-and-gender-justice', 'SCERT Kerala, Kerala Curriculum Framework 2023 (draft on SCERT page): aims, value education, gender justice', '{"id":"IN-KL-MANDATE-kcf-2023-aims-value-education-and-gender-justice","label":"SCERT Kerala, Kerala Curriculum Framework 2023 (draft on SCERT page): aims, value education, gender justice","sourceUrl":"https://scert.kerala.gov.in/kerala-curriculum-framework-2023/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Kerala Curriculum Framework 2023 (School Education), English edition: Chapter 5 Kerala and the Aims of School Education (printed pages 57 to 61; aim 7, Education that upholds constitutional values, on page 59); section 6.3 Education that is based on gender justice (pages 81 to 84); section 6.4 Value Education (pages 84 to 86).. The checker read these sections in the same English PDF as the previous framework record (see its notes on the draft label and the missing printed date). Chapter 5 runs printed pp. 57 to 61 with sixteen numbered aims; aim 7 is on p. 59. Section 6.3 runs pp. 81 to 84 and section 6.4 pp. 84 to 86. Section 6.4.1 says that adding values as a separate item is unacceptable, and that a critical-thinking, debate-friendly classroom is a prerequisite. Section 6.3.1 says the curriculum, syllabus, textbooks and learning process should be subjected to gender auditing ''on a regular basis'', says gender auditing should be an element in assessing school quality, and asks that school bodies (School Parliament, clubs, PTA, School Management Committee) reflect a gender-justice approach. All wording is ''should''; no hours or marks are set. The framework was compared only with itself. Section 6.4.2 names democracy, socialism, secularism, equality, freedom, unity, integration, dignity, equity, fraternity and justice as constitutional values; this record reports that wording as the document gives it. A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Curriculum Framework 2023 (School Education), English edition: Chapter 5 Kerala and the Aims of School Education (printed pages 57 to 61; aim 7, Education that upholds constitutional values, on page 59); section 6.3 Education that is based on gender justice (pages 81 to 84); section 6.4 Value Education (pages 84 to 86).","description":"The framework lists sixteen aims for school education, including social justice, responsible citizenship, inclusion, and education that upholds constitutional values and a democratic, secular outlook. It says values such as equality, freedom and fraternity should be absorbed through school life and a classroom open to debate. It asks that the curriculum, syllabus and textbooks be audited regularly for gender justice, and that school bodies such as the School Parliament reflect a gender-justice approach.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, for the Department of General Education, Government of Kerala","mandateType":"curriculum-framework","adoptionDate":"2023","dateGranularity":"year","statementText":"The framework lists sixteen aims for school education, including social justice, responsible citizenship, inclusion, and education that upholds constitutional values and a democratic, secular outlook. It says values such as equality, freedom and fraternity should be absorbed through school life and a classroom open to debate. It asks that the curriculum, syllabus and textbooks be audited regularly for gender justice, and that school bodies such as the School Parliament reflect a gender-justice approach.","subject":"general","topicTags":["constitutional values","value education","gender justice","citizenship","inclusion","democratic classroom"]}', ''),
  ('4340e002-e43d-538d-9fab-22eda7a740b0', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-scert-classes5-7-social-science-rules-law-state-constitution-and-culture', 'SCERT Kerala, Social Science textbooks for Classes 5 to 7 (2024 and 2025 editions): rules and law, state, Constitution, culture, justice', '{"id":"IN-KL-UNIT-scert-classes5-7-social-science-rules-law-state-constitution-and-culture","label":"SCERT Kerala, Social Science textbooks for Classes 5 to 7 (2024 and 2025 editions): rules and law, state, Constitution, culture, justice","sourceUrl":"https://samagra.kite.kerala.gov.in/#/textbook/page/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Class 5 Social Science Part 1, ch 6 People, by the People (pp. 84-96); Part 2, ch 9 Towards Equality (pp. 149-160) and ch 11 The Law and The Society (pp. 179-189). Class 6 Part 1, ch 3 State and Government (pp. 37-47) and ch 5 Culture and Cultural Diversities (pp. 60-74); Part 2, ch 9 An Introduction to Constitution (pp. 125-136, Preamble shown on p. 133). Class 7 Part 1, ch 3 Constitution: Path and Guiding Light (pp. 39-53) and ch 4 From Injustice to Justice (pp. 54-67); Part 2, ch 11 Against Discrimination (pp. 166-179).. The AI reader read the English-medium PDFs from the official Samagra textbook portal on 30 Oct 2026. Files (relative to https://samagra.kite.kerala.gov.in/files/samagra-resource/uploads2/tbookscmq/): Class_V/Social Science_E_Vol_II/SocialScienceEnglish.pdf (Part 1; the cover says Part 1) and PARTII/STD5/15_Social Science _5 (E)Part II.pdf; eng/6/15/Social Science ( E )_1752589459061_708357391.pdf (Part 1) and eng/6/15/Social Science-2_1760783194840_392074302.pdf (Part 2); Class_VII/Social Science_E_Vol_II/SocialScienceEnglish.pdf (Part 1) and PARTII/STD7/14_Social Science-7 (E) Vol-2.pdf (Part 2). Editions: Class 5 imprint 2024 (no edition line); Class 6 ''First Edition 2025''; Class 7 imprint 2024. The portal lists these as the current books; the AI reader could not tell which print run a school holds in 2026-27. The prefaces of Class 5 Part 1, Class 6 (both parts) and Class 7 (both parts) name the Kerala Curriculum Framework 2023; the Class 5 Part 2 preface does not. Read in full: Class 5 ch 11, ch 6 (pp. 84-92) and the opening of ch 9; Class 6 ch 3, ch 5 and ch 9; Class 7 ch 3, plus the opening pages of Class 7 ch 4 and ch 11 (ch 11 is about South Africa, Gandhi and apartheid). The Class 6 Preamble is a picture on p. 133 whose footnotes mark the words added in 1976. Class 5 says Classes 1 to 4 teach science and social science together as Environmental Studies. Those books were not read, so this record makes no claim about earlier teaching of rules and norms. A second checker re-opened all six files, matched every chapter title and page range to the contents pages, and re-read Class 5 ch 6 and ch 11, Class 6 ch 3, ch 5 and ch 9, Class 7 ch 3 and ch 4, and the opening pages of Class 7 Part 2 ch 11. Every Class 5 to 7 file also shows the Preamble as a full-page image before Chapter 1 (PDF page 6). The record year 2024 is the earlier imprint year; the Class 6 books are ''First Edition 2025''. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Class 5 Social Science Part 1, ch 6 People, by the People (pp. 84-96); Part 2, ch 9 Towards Equality (pp. 149-160) and ch 11 The Law and The Society (pp. 179-189). Class 6 Part 1, ch 3 State and Government (pp. 37-47) and ch 5 Culture and Cultural Diversities (pp. 60-74); Part 2, ch 9 An Introduction to Constitution (pp. 125-136, Preamble shown on p. 133). Class 7 Part 1, ch 3 Constitution: Path and Guiding Light (pp. 39-53) and ch 4 From Injustice to Justice (pp. 54-67); Part 2, ch 11 Against Discrimination (pp. 166-179).","description":"Class 5 teaches game and school rules, law as the accepted rules of a society, and two sources of law: unwritten social norms, and legislatures and courts. Class 6 defines the state and government with its three organs, explains culture as learnt, shared and changing, and introduces the Constitution and its Preamble. Class 7 covers how the Constitution was made, its main features, marginalisation and the struggles for justice, and a chapter on discrimination set in South Africa.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education, Government of Kerala","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"Class 5 teaches game and school rules, law as the accepted rules of a society, and two sources of law: unwritten social norms, and legislatures and courts. Class 6 defines the state and government with its three organs, explains culture as learnt, shared and changing, and introduces the Constitution and its Preamble. Class 7 covers how the Constitution was made, its main features, marginalisation and the struggles for justice, and a chapter on discrimination set in South Africa.","subject":"social-science","gradeFrom":5,"gradeTo":7,"topicTags":["rules and laws","social norms","state and government","constitution","preamble","culture","socialisation","marginalisation","democracy"]}', ''),
  ('f04bc015-2cbd-555a-97e2-9db116247bf8', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-scert-classes8-10-social-science-rights-democracy-institutions-and-movements', 'SCERT Kerala, Social Science textbooks for Classes 8 to 10 (2024, 2025): rights, democracy, institutions, public opinion, movements', '{"id":"IN-KL-UNIT-scert-classes8-10-social-science-rights-democracy-institutions-and-movements","label":"SCERT Kerala, Social Science textbooks for Classes 8 to 10 (2024, 2025): rights, democracy, institutions, public opinion, movements","sourceUrl":"https://samagra.kite.kerala.gov.in/#/textbook/page/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Class 8 Social Science Part 1, ch 5 Constitution of India: Rights and Duties (pp. 73-86) and ch 7 Media and Social Reflections (pp. 103-118); Part 2, ch 9 Democracy: Meaning and Scope (pp. 147-164). Class 9 Social Science I Part 1, ch 4 Distribution of Power in the Indian Constitution (pp. 63-82); Part 2, ch 7 Extension of Democracy through Institutions (pp. 129-150). Class 10 Social Science I Part 1, ch 5 Public Opinion in Democracy (pp. 87-102); Part 2, ch 8 Democracy: An Indian Experience (pp. 155-180).. The AI reader read the English-medium PDFs from the official Samagra textbook portal on 30 Oct 2026. Files (relative to https://samagra.kite.kerala.gov.in/files/samagra-resource/uploads2/tbookscmq/): eng/8/15/Social Science English_1750269107738_290267374.pdf (Part 1) and eng/8/15/SocialScienceEnglish_1762233580752_878746854.pdf (Part 2); Class 9/SocialScience_IX_I_Eng_vol_1/SocialScience_IX_I_Eng_vol_1.pdf and PARTII/18_SOCIAL SCIENCE-I_IX_(E) PART 2.pdf; eng/10/27/Social Science 1_1744353943105_196096560.pdf (Part 1) and eng/10/27/Social Science - Part-2_1760768692804_485187545.pdf (Part 2). Editions: Class 8 imprint 2025; Class 9 ''First Edition 2024''; Class 10 ''First Edition 2025''. The Class 8, 9 and 10 prefaces do not name the curriculum framework. For these chapters the AI reader read the contents pages, prefaces, section headings and selected paragraphs (political parties in Class 8 Part 2 ch 9, the Emergency and movements headings in Class 10 Part 2 ch 8). It did not read every paragraph, so details below the headings are unchecked. The Class 10 Part 1 preface lists the public-opinion chapter; the Part 2 preface (a later file) does not mention it. Class 8 ch 7 says media help shape public opinion and social norms. Class 10 Part 2 ch 8 includes a section on the Emergency and sections on Mandal Commission, Dalit, women''s and anti-arrack movements; this record reports headings only and takes no view on how they are treated. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Class 8 Social Science Part 1, ch 5 Constitution of India: Rights and Duties (pp. 73-86) and ch 7 Media and Social Reflections (pp. 103-118); Part 2, ch 9 Democracy: Meaning and Scope (pp. 147-164). Class 9 Social Science I Part 1, ch 4 Distribution of Power in the Indian Constitution (pp. 63-82); Part 2, ch 7 Extension of Democracy through Institutions (pp. 129-150). Class 10 Social Science I Part 1, ch 5 Public Opinion in Democracy (pp. 87-102); Part 2, ch 8 Democracy: An Indian Experience (pp. 155-180).","description":"Class 8 covers fundamental rights and duties, media, and democracy with its forms, parties and basic values. Class 9 covers how the Constitution divides power and how bodies such as the Election Commission and human rights commissions extend democracy. Class 10 covers public opinion, politics in India after independence including the Emergency, and movements by backward-class, Dalit and women''s groups.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education, Government of Kerala","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"Class 8 covers fundamental rights and duties, media, and democracy with its forms, parties and basic values. Class 9 covers how the Constitution divides power and how bodies such as the Election Commission and human rights commissions extend democracy. Class 10 covers public opinion, politics in India after independence including the Emergency, and movements by backward-class, Dalit and women''s groups.","subject":"social-science","gradeFrom":8,"gradeTo":10,"topicTags":["fundamental rights","democracy","federalism","election commission","public opinion","political parties","popular movements","media"]}', ''),
  ('1193965a-016c-58b5-b1fd-9d0715938c7b', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-scert-classes9-10-social-science-roles-norms-stratification-and-social-institutions', 'SCERT Kerala, Social Science I for Classes 9 and 10 (2024, 2025): gender roles and norms, sociological imagination, social institutions', '{"id":"IN-KL-UNIT-scert-classes9-10-social-science-roles-norms-stratification-and-social-institutions","label":"SCERT Kerala, Social Science I for Classes 9 and 10 (2024, 2025): gender roles and norms, sociological imagination, social institutions","sourceUrl":"https://samagra.kite.kerala.gov.in/#/textbook/page/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Class 9 Social Science I Part 2, ch 8 Towards a Gender-Neutral Society (pp. 151-166; status and role pp. 153-156, norms and laws pp. 157-158, stereotypes pp. 158-160). Class 10 Social Science I Part 1, ch 3 Social Analysis: Through Sociological Imagination (pp. 47-64); Part 2, ch 9 Know the Indian Social System (pp. 181-202; social institutions on pp. 181-184).. The AI reader read Class 9 ch 8 pp. 155-160 and Class 10 Part 2 ch 9 pp. 181-186 in full, and read only headings and a few paragraphs elsewhere in these chapters. Files (relative to https://samagra.kite.kerala.gov.in/files/samagra-resource/uploads2/tbookscmq/): PARTII/18_SOCIAL SCIENCE-I_IX_(E) PART 2.pdf (Class 9, ''First Edition 2024''); eng/10/27/Social Science 1_1744353943105_196096560.pdf and eng/10/27/Social Science - Part-2_1760768692804_485187545.pdf (Class 10, ''First Edition 2025''). Class 10 ch 9 compares society to a body and cites Herbert Spencer''s ''social organism''; the Social-Core model says it borrows no mechanism from biology, so a reviewer may want to see this. A text search of the Class 5 to 8 social science books found ''social control'' zero times, and found ''social norm'' in Class 5 Part 2 and Class 8 Part 1; ''social control'' appears in Class 9 and 10. A search is not a reading of the earlier classes, so this record makes no claim that Kerala teaches norm enforcement later than the model. Class 9 ch 8 deals with gender; the chapter text is quoted only as short phrases. The caste-system section is reported by its section headings. A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Class 9 Social Science I Part 2, ch 8 Towards a Gender-Neutral Society (pp. 151-166; status and role pp. 153-156, norms and laws pp. 157-158, stereotypes pp. 158-160). Class 10 Social Science I Part 1, ch 3 Social Analysis: Through Sociological Imagination (pp. 47-64); Part 2, ch 9 Know the Indian Social System (pp. 181-202; social institutions on pp. 181-184).","description":"Class 9 teaches status and role, social stratification, the difference between laws and unwritten social norms, and gender stereotypes. Class 10 introduces sociological imagination to tell personal problems from social causes. It then treats social institutions as parts of a social system that regulate behaviour, with the caste system and religion as worked cases.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education, Government of Kerala","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"Class 9 teaches status and role, social stratification, the difference between laws and unwritten social norms, and gender stereotypes. Class 10 introduces sociological imagination to tell personal problems from social causes. It then treats social institutions as parts of a social system that regulate behaviour, with the caste system and religion as worked cases.","subject":"social-science","gradeFrom":9,"gradeTo":10,"topicTags":["social norms","gender roles","stereotypes","social stratification","sociological imagination","social institutions","social control","caste system"]}', ''),
  ('87877f27-e448-5a95-be1c-c46c90319866', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-UNIT-scert-classes5-10-social-science-local-government-peoples-planning-and-cooperative-institutions', 'SCERT Kerala, Social Science textbooks for Classes 5 to 10: grama sabhas, People''s Planning, Kudumbashree and cooperative institutions', '{"id":"IN-KL-UNIT-scert-classes5-10-social-science-local-government-peoples-planning-and-cooperative-institutions","label":"SCERT Kerala, Social Science textbooks for Classes 5 to 10: grama sabhas, People''s Planning, Kudumbashree and cooperative institutions","sourceUrl":"https://samagra.kite.kerala.gov.in/#/textbook/page/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Class 5 Part 1, ch 6 People, by the People (pp. 84-96). Class 7 Part 2, ch 8 Power to the People (pp. 119-131); Class 7 Part 1, ch 7 From food production to food security (pp. 94-110; Kudumbashree on pp. 108-110). Class 8 Part 2, ch 12 Agricultural Sector and Innovative Trends (pp. 195-210; farmers'' associations and cooperative credit societies on p. 209). Class 10 Social Science I Part 2, ch 7 The Glimpses of Free India (pp. 131-154; land reform, Kudumbashree and decentralised planning on pp. 149-153). Class 10 Social Science II Part 1, ch 5 Money and Economy (pp. 102-123; cooperative banks on pp. 113 and 121). Also: Class 5 Part 1 p. 37 (Kudumbashree, ch 2); Class 6 Part 2, ch 11 Let''s Save for the Future (pp. 151-163; co-operative banks on pp. 159-160); Class 8 Part 1, ch 4 Basic Economic Problems and the Economy (pp. 59-72; Kudumbashree on p. 65).. The AI reader read Class 7 Part 2 ch 8 and Class 5 Part 1 ch 6 (pp. 84-92) in full, and read the paragraphs around each other mention. Files are the ones listed in the other Kerala textbook records, plus eng/10/28/Social Science 2_1744354306403_500721457.pdf (Class 10 Social Science II Part 1). Class 7 Part 2 ch 8 reports that women''s reservation in local bodies is 33% after the amendments and 50% after a 2005 Panchayati Raj Act amendment, and that 10% of plan funds go to women''s projects; these figures and the 1996 date are the textbook''s statements and were not checked against other sources. Kerala''s cooperative movement and people''s planning are named only in passing in the books read; no chapter is devoted to the cooperative movement. A second checker re-searched all 16 Class 5 to 10 social science PDFs for ''commons'', ''common property'', ''common resource'', ''collective resource'', ''community resource'', ''shared resource'', ''free rider'', ''public good'', ''common pool'', ''overuse'', ''overexploitation'', ''water conservation'', ''forest'', ''fishing'' and ''grazing'', and read the hits. No chapter teaches a shared-resource dilemma. Three passages come close and the earlier ''none found'' needs care. Class 10 Social Science II Part 2 ch 8 (pp. 183-206) opens with the Aral Sea as a case of overexploitation, sorts resources into personal, community, national and international, and asks pupils who is responsible for protecting community and national resources (pp. 186-187). Its ch 6 closes by saying resource use should aim at sufficient access through cooperation rather than competition (p. 157). Class 10 Social Science I Part 2 ch 8 lists fishermen''s and environmental movements (pp. 166-167). Class 8 Part 1 ch 6 (pp. 87-102) covers resource depletion and conservation with no dilemma, and Class 5 to 9 chapters give conservation messages only. Kudumbashree also appears in Class 5 Part 1 p. 37 and Class 8 Part 1 p. 65 (ch 4), and co-operative banks in Class 6 Part 2 ch 11 (pp. 159-160). Class 10 Social Science I Part 2 also describes a district cooperative milk union in Gujarat in its food-production section. The higher secondary additional book for Class 12 Political Science (see its record) describes Kerala''s development model as using land reform, the Total Literacy Programme and the People''s Plan Campaign. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Class 5 Part 1, ch 6 People, by the People (pp. 84-96). Class 7 Part 2, ch 8 Power to the People (pp. 119-131); Class 7 Part 1, ch 7 From food production to food security (pp. 94-110; Kudumbashree on pp. 108-110). Class 8 Part 2, ch 12 Agricultural Sector and Innovative Trends (pp. 195-210; farmers'' associations and cooperative credit societies on p. 209). Class 10 Social Science I Part 2, ch 7 The Glimpses of Free India (pp. 131-154; land reform, Kudumbashree and decentralised planning on pp. 149-153). Class 10 Social Science II Part 1, ch 5 Money and Economy (pp. 102-123; cooperative banks on pp. 113 and 121). Also: Class 5 Part 1 p. 37 (Kudumbashree, ch 2); Class 6 Part 2, ch 11 Let''s Save for the Future (pp. 151-163; co-operative banks on pp. 159-160); Class 8 Part 1, ch 4 Basic Economic Problems and the Economy (pp. 59-72; Kudumbashree on p. 65).","description":"Class 5 introduces grama sabhas and the local self-government bodies. Class 7 teaches decentralisation, the 73rd and 74th Amendments, Kerala''s People''s Planning from 1996 as the book dates it, and the limits local bodies face, with a class sabha role play. Kudumbashree appears in Classes 5, 7, 8 and 10, co-operative banks in Classes 6 and 10, and farmers'' associations and cooperative credit societies in Class 8.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Kerala, Department of General Education, Government of Kerala","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"Class 5 introduces grama sabhas and the local self-government bodies. Class 7 teaches decentralisation, the 73rd and 74th Amendments, Kerala''s People''s Planning from 1996 as the book dates it, and the limits local bodies face, with a class sabha role play. Kudumbashree appears in Classes 5, 7, 8 and 10, co-operative banks in Classes 6 and 10, and farmers'' associations and cooperative credit societies in Class 8.","subject":"social-science","gradeFrom":5,"gradeTo":10,"topicTags":["local self-government","grama sabha","people''s planning","decentralisation","kudumbashree","cooperative banks","farmers'' groups","land reform"]}', ''),
  ('e2db0484-2d10-52a0-b6b2-ae9dbbf19d8f', 'kerala-school-curriculum-repository', 'policy-timeline-event', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-EVENT-scert-additional-higher-secondary-textbooks-topics-dropped-by-ncert-2023-08', 'SCERT Kerala releases six additional textbooks for Classes 11 and 12 on topics deleted from NCERT books (August 2023)', '{"id":"IN-KL-EVENT-scert-additional-higher-secondary-textbooks-topics-dropped-by-ncert-2023-08","label":"SCERT Kerala releases six additional textbooks for Classes 11 and 12 on topics deleted from NCERT books (August 2023)","sourceUrl":"https://scert.kerala.gov.in/higher-secondary-additional-textbooks/","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: SCERT Kerala page ''HSS - Additional Textbooks: Higher Secondary Additional Textbooks Incorporating topics deleted by NCERT'' (six PDFs under /wp-content/uploads/2023/08/). Read: prefaces and contents of Class 12 Political Science (29 pp.; ch 3 Debating Emergency on pp. 11-13, ch 4 Rise of Popular Movements on pp. 14-19, ch 5 Gujarat Riots on p. 20), Class 12 Sociology (39 pp.; four units) and Class 11 Political Science (17 pp.; units Peace and Development).. No order, circular or SCERT notice for the release was found. The SCERT page lists the six PDFs in its 2023/08 upload folder and four file names carry ''230823''; the month rests on that and on news. The day comes from news. PTI, carried by The South First on 24 Aug 2023, says the Chief Minister released the books on Wednesday 23 Aug 2023; the SCERT file names end in 230823 and sit in the 2023/08 upload folder. The books themselves print only ''First Edition: 2023'', so the record uses month granularity. The AI reader read the prefaces, contents and reading instructions of the three social-science books named above. The Class 11 Political Science PDF has no text layer and was read as page images. All six imprints print ''First Edition : 2023'' (checked as text or as page images). The Class 11 Economics, Class 11 History and Class 12 History PDFs were downloaded but their contents were not read. Each book''s reading instructions say its chapters are to be read as continuations of named chapters in the NCERT textbooks. The four Class 11 and 12 Political Science and Sociology files that the AI reader opened on the Samagra portal are NCERT titles (for example Indian Constitution at Work and Introducing Sociology) and carry the page mark ''2018-19''. The Class 12 Political Science book includes a one-page chapter titled ''Gujarat Riots'' (p. 20) that credits an NCERT 2013 textbook. This record reports contents and dates only. It gives no reason for the removals or for Kerala''s decision, and political statements made at the release are in the press coverage and are not repeated here. The earlier NCERT rationalisation is covered by a national-level record. A second checker re-opened the Class 12 Political Science, Class 12 Sociology and Class 11 Political Science books (the last as page images), confirmed ''First Edition : 2023'' in all six (the Class 11 Economics imprint as a page image), and re-checked the Director''s preface and contents. News reports that the Chief Minister released the books on 23 Aug 2023 were seen as search summaries from ANI, Business Standard and Organiser, which were not opened. The SCERT page''s own heading says the books incorporate topics deleted by NCERT; the Director''s preface speaks of ''the deletion of certain topics''. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"SCERT Kerala page ''HSS - Additional Textbooks: Higher Secondary Additional Textbooks Incorporating topics deleted by NCERT'' (six PDFs under /wp-content/uploads/2023/08/). Read: prefaces and contents of Class 12 Political Science (29 pp.; ch 3 Debating Emergency on pp. 11-13, ch 4 Rise of Popular Movements on pp. 14-19, ch 5 Gujarat Riots on p. 20), Class 12 Sociology (39 pp.; four units) and Class 11 Political Science (17 pp.; units Peace and Development).","description":"SCERT Kerala published six additional textbooks (First Edition 2023) for Class 11 Economics, History and Political Science and Class 12 History, Political Science and Sociology. The Director''s preface in the books read says they fill gaps left by topics deleted from the prescribed Class 11 and 12 books, and each is to be read as a continuation of named NCERT chapters. The Political Science and Sociology books include popular movements, the Emergency debate, peace, development, social institutions and social change.","verificationStatus":"primary-source-confirmed","slug":"scert-additional-higher-secondary-textbooks-topics-dropped-by-ncert-2023-08","dateStart":"2023-08","dateGranularity":"month","eventType":"other","temporalStatus":"past-completed","topicTags":["additional textbooks","higher secondary","political science","sociology","popular movements","social change","textbook revision"]}', ''),
  ('ee5433ae-42b4-50ca-8e7c-3b64e52517d6', 'kerala-school-curriculum-repository', 'policy-timeline-event', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-EVENT-kerala-revised-textbooks-classes-1-10-two-phases-and-preamble-announced-2024', 'Kerala Department of General Education: revised Class 1 to 10 textbooks in two phases (2024, 2025); Preamble announced (Jan 2024)', '{"id":"IN-KL-EVENT-kerala-revised-textbooks-classes-1-10-two-phases-and-preamble-announced-2024","label":"Kerala Department of General Education: revised Class 1 to 10 textbooks in two phases (2024, 2025); Preamble announced (Jan 2024)","sourceUrl":"https://www.prd.kerala.gov.in/sites/default/files/inline-files/kerala%20calling%20june%202025.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: Kerala Calling, Vol 45 No 08, 1 June 2025 (Kerala government publication): the Minister for General Education and Labour''s article ''Priorities Matter'' (section Textbook Revision and Uniform Distribution, p. 10) and the SCERT Director''s article ''Resonating the World in Textbooks'' (section Evolving Texts, p. 13). Imprints of the Class 5 to 10 Social Science books on the Samagra portal. SCERT page scert.kerala.gov.in/textbook-2024-menu/ (revised textbooks for Classes I, III, V, VII, IX). Preamble announcement: PTI report in The Tribune, 17 Jan 2024; Careers360, 16 Jan 2024. Samagra portal English Class 5 to 10 Social Science files (16), PDF page 6, the Preamble page between the contents and Chapter 1.. Two parts have different support. The two-phase revision is read directly. Kerala Calling (Vol 45 No 08, 1 June 2025, a Kerala government publication) says in the Minister''s article (p. 10) that textbooks for Classes 1 to 10 were revised after a gap of 16 years, and the SCERT Director''s article (p. 13) says 238 titles for Classes 1, 3, 5, 7 and 9 in four languages were revised in the first phase and 205 titles for Classes 2, 4, 6, 8 and 10 in the second. The Class 5, 7 and 9 Social Science books carry 2024 imprints and the Class 6, 8 and 10 books carry 2025 imprints. The Preamble announcement rests on news only. PTI via The Tribune (17 Jan 2024) quotes the minister as saying it is the first time the Preamble is printed at the start of every textbook, quotes the SCERT Director as saying it will be part of all revised textbooks and of teacher training, and reports it for Classes 1 to 10. Careers360 (16 Jan 2024) reports 173 titles approved by the Steering Committee for Classes 1, 3, 5, 7 and 9 and quotes the state general education department as saying all textbooks will carry the Preamble in the introduction. The 173 and 238 title counts differ and were not reconciled. No Kerala government order, circular or release on the Preamble was found by two readers. A second checker opened all 16 English-medium Class 5 to 10 Social Science files on the Samagra portal: Class 5 Parts 1 and 2 and Class 7 Parts 1 and 2 (2024 imprints); Class 6 Parts 1 and 2 (''First Edition 2025''); Class 8 Parts 1 and 2 (2025 imprints); Class 9 Social Science I and II, Parts 1 and 2 (''First Edition 2024''); Class 10 Social Science I and II, Parts 1 and 2 (''First Edition 2025''). Every one of the 16 files shows the Preamble as a full-page image on the unnumbered page after the contents page (PDF page 6) and before Chapter 1. The earlier note that the Class 5 Part 1 and Class 8 Part 1 files show none was a miss, because that page is an image with no text layer. The Class 6 Part 2 file also shows the Preamble inside ch 9 on p. 133. No file shows it on the back pages, which carry Article 51A (Fundamental Duties) and in some books Children''s Rights. Classes 1 to 4, Malayalam-medium books and printed copies were not checked. The prefaces of Class 5 Part 1 and of Classes 6 and 7 (both parts) name the 2023 curriculum framework. The prefaces of Class 5 Part 2 and of Classes 8, 9 and 10 do not. The announcement is a values text and the Social-Core and Interdisciplinary strands teach how rules and institutions work, so the record has no link. A second AI reader could not confirm all of it: Statement says ''the Class 5 to 7 prefaces name the 2023 curriculum framework''. The Class 5 Part 2 preface does not name it (Class 5 Part 1, Class 6 and Class 7 do). Removed from the statement and kept in the notes.; Notes say the Class 5 Part 1 and Class 8 Part 1 files show no Preamble, so ''at the start of every textbook'' is unconfirmed. Wrong: all 16 English Class 5 to 10 Social Science files show a full-page Preamble on PDF page 6, after the contents and before Chapter 1 (listed in the notes). The drafter read the text layer only, and that page is an image.; Statement says the minister announced the Preamble ''with teacher training on it''. In The Tribune report the SCERT Director said it would also be included in teacher training. Attribution fixed.; The Preamble announcement and its January 2024 date rest on news only (The Tribune, PTI, 17 Jan 2024; Careers360, 16 Jan 2024). No order, circular or notice was found. Status changed to secondary-source-only for the record as a whole. The two-phase textbook revision is confirmed from Kerala Calling and the textbook imprints, and the record could be split in two.; Confirmed: Kerala Calling Vol 45 No 08 (1 June 2025) p. 10 and p. 13 say what the record says, including 238 and 205 titles and the 16-year gap. Social Science imprints are 2024 for Classes 5, 7, 9 and 2025 for Classes 6, 8, 10. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Kerala Calling, Vol 45 No 08, 1 June 2025 (Kerala government publication): the Minister for General Education and Labour''s article ''Priorities Matter'' (section Textbook Revision and Uniform Distribution, p. 10) and the SCERT Director''s article ''Resonating the World in Textbooks'' (section Evolving Texts, p. 13). Imprints of the Class 5 to 10 Social Science books on the Samagra portal. SCERT page scert.kerala.gov.in/textbook-2024-menu/ (revised textbooks for Classes I, III, V, VII, IX). Preamble announcement: PTI report in The Tribune, 17 Jan 2024; Careers360, 16 Jan 2024. Samagra portal English Class 5 to 10 Social Science files (16), PDF page 6, the Preamble page between the contents and Chapter 1.","description":"Kerala revised its school textbooks in two phases. Books for Classes 1, 3, 5, 7 and 9 came first (2024 imprints), then Classes 2, 4, 6, 8 and 10 (2025 imprints). News reports of 16 and 17 January 2024 say the minister announced that the Preamble would be printed at the start of every revised textbook, and the SCERT Director said teacher training would include it. The English Class 5 to 10 social science books checked each carry the Preamble on a full page before Chapter 1.","verificationStatus":"secondary-source-only","slug":"kerala-revised-textbooks-classes-1-10-two-phases-and-preamble-announced-2024","dateStart":"2024","dateGranularity":"year","eventType":"other","temporalStatus":"past-completed","topicTags":["textbook revision","preamble","constitutional values","curriculum framework","school textbooks"]}', ''),
  ('579e17d5-4775-59c1-877b-93ac523d809e', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-home-language-medium-and-three-language-formula', 'NEP 2020 (Ministry of Human Resource Development): home language, medium of instruction and the three-language formula', '{"id":"IN-MANDATE-nep-2020-home-language-medium-and-three-language-formula","label":"NEP 2020 (Ministry of Human Resource Development): home language, medium of instruction and the three-language formula","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020, Part I, Chapter 4 ''Multilingualism and the power of language'', paras 4.11 to 4.14 (printed pp. 13-14); para 5.4 on hiring teachers who can use the local language (printed p. 20). AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. A second AI reader re-read paras 4.11 to 4.14 and 5.4 in the PIB-hosted PDF on 30 October 2026. Page numbers are printed numbers (4.11 and 4.12 on p. 13, 4.13 and 4.14 on p. 14, 5.4 on p. 20). The document prints no date. The Union Cabinet approved the policy on 29 July 2020 (PIB release of that date), which is the date used. The document''s verbs are ''will be'' for the medium of instruction (with ''wherever possible'') and ''may'' for a student''s change of language. Para 4.14, which says all efforts will be made to prepare bilingual science and mathematics books, and the sentence in 4.11 on high-quality home-language textbooks, are left out of the statement for length. The AI reader did not read any State or court document on how the formula is applied, so the record says what the policy states and says nothing about practice. A second AI reader corrected this record against the source (8 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020, Part I, Chapter 4 ''Multilingualism and the power of language'', paras 4.11 to 4.14 (printed pp. 13-14); para 5.4 on hiring teachers who can use the local language (printed p. 20)","description":"NEP 2020 says the medium of instruction will, wherever possible, be the home language, mother tongue, or local or regional language until at least Class 5, preferably to Class 8 and beyond, in public and private schools. The three-language formula continues with greater flexibility and no language imposed on any State. States, regions and students choose the three, at least two native to India. A language may change in Class 6 or 7, given basic proficiency by the end of secondary school.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Human Resource Development, Government of India","mandateType":"policy-statement","adoptionDate":"2020-07-29","dateGranularity":"day","statementText":"NEP 2020 says the medium of instruction will, wherever possible, be the home language, mother tongue, or local or regional language until at least Class 5, preferably to Class 8 and beyond, in public and private schools. The three-language formula continues with greater flexibility and no language imposed on any State. States, regions and students choose the three, at least two native to India. A language may change in Class 6 or 7, given basic proficiency by the end of secondary school.","subject":"languages","topicTags":["multilingualism","medium of instruction","mother tongue","home language","three-language formula","bilingual textbooks"]}', '2020-07-29'),
  ('54cd2686-b00b-50f1-8662-dd66e705a2a4', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-languages-of-india-classical-languages-and-sign-language', 'NEP 2020 (Ministry of Human Resource Development): The Languages of India project, classical languages and Indian Sign Language', '{"id":"IN-MANDATE-nep-2020-languages-of-india-classical-languages-and-sign-language","label":"NEP 2020 (Ministry of Human Resource Development): The Languages of India project, classical languages and Indian Sign Language","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020, Part I, Chapter 4, paras 4.15 to 4.22 (printed pp. 14-15); Chapter 6, para 6.11 on NIOS modules in Indian Sign Language (printed p. 27). AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. A second AI reader re-read paras 4.15 to 4.22 (printed pp. 14-15) and 6.11 (p. 27) in the PIB-hosted PDF on 30 October 2026. The document prints no date. The Union Cabinet approved the policy on 29 July 2020 (PIB release of that date), which is the date used. Para 4.16 describes the project as joyful and says it involves no assessment. Para 4.19 says all students in all schools, public or private, will have the option of two years of a classical language in Classes 6 to 12. Para 4.20 says foreign languages will also be offered at secondary level, and para 6.11 says NIOS will develop modules to teach Indian Sign Language and to teach other basic subjects using it; both are left out of the statement for length. Para 4.22 says local sign languages will be respected and taught where possible and relevant. The AI reader did not check whether the project or the classical-language option has been put into State syllabuses. A second AI reader corrected this record against the source (8 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020, Part I, Chapter 4, paras 4.15 to 4.22 (printed pp. 14-15); Chapter 6, para 6.11 on NIOS modules in Indian Sign Language (printed p. 27)","description":"NEP 2020 says every student will take part in an unassessed project on The Languages of India in Classes 6 to 8, covering common scripts and grammar, word origins, influences and differences. All students will have the option of at least two years of a classical language in Classes 6 to 12. Sanskrit will be offered at all levels as an option, and other classical languages (Tamil, Telugu, Kannada, Malayalam, Odia, Pali, Persian, Prakrit) will be widely available. Indian Sign Language will be standardised for students with hearing impairment.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Human Resource Development, Government of India","mandateType":"policy-statement","adoptionDate":"2020-07-29","dateGranularity":"day","statementText":"NEP 2020 says every student will take part in an unassessed project on The Languages of India in Classes 6 to 8, covering common scripts and grammar, word origins, influences and differences. All students will have the option of at least two years of a classical language in Classes 6 to 12. Sanskrit will be offered at all levels as an option, and other classical languages (Tamil, Telugu, Kannada, Malayalam, Odia, Pali, Persian, Prakrit) will be widely available. Indian Sign Language will be standardised for students with hearing impairment.","subject":"languages","gradeFrom":6,"gradeTo":12,"topicTags":["languages of India","classical languages","Sanskrit","Indian Sign Language","sign language","language relations","foreign languages"]}', '2020-07-29'),
  ('a802b40d-96cd-553e-ae2f-e0842edb3f93', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-access-open-schooling-alternative-schools-and-boarding', 'NEP 2020 (Ministry of Human Resource Development): open schooling, alternative schools and boarding for children outside regular schools', '{"id":"IN-MANDATE-nep-2020-access-open-schooling-alternative-schools-and-boarding","label":"NEP 2020 (Ministry of Human Resource Development): open schooling, alternative schools and boarding for children outside regular schools","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020, Part I, Chapter 3 ''Curtailing dropout rates and ensuring universal access'', paras 3.1 to 3.6 (printed pp. 10-11); Chapter 6, paras 6.9, 6.12 and 6.15 (printed pp. 26-27). AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. A second AI reader re-read paras 3.1 to 3.6 (printed pp. 10-11) and 6.9, 6.11, 6.12 and 6.15 (pp. 26-27) in the PIB-hosted PDF on 30 October 2026. The document prints no date. The Union Cabinet approved the policy on 29 July 2020 (PIB release of that date), which is the date used. The 2030 target in para 3.1 is a 100 per cent gross enrolment ratio from pre-school to secondary level. The out-of-school figure is the policy''s own citation of a household survey and was not checked against the survey. Para 3.6 also says school requirements will be made less restrictive and public-philanthropic partnerships piloted; that part is left out of the statement. Para 6.15 says alternative forms of schools will be encouraged to preserve their traditions or alternative teaching styles and will receive financial assistance to introduce science, mathematics, social studies, Hindi, English, State languages or other subjects as they wish. The AI reader did not read the NIOS or Navodaya Vidyalaya Samiti websites. A second AI reader corrected this record against the source (6 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020, Part I, Chapter 3 ''Curtailing dropout rates and ensuring universal access'', paras 3.1 to 3.6 (printed pp. 10-11); Chapter 6, paras 6.9, 6.12 and 6.15 (printed pp. 26-27)","description":"NEP 2020 sets a goal of 100 per cent gross enrolment ratio from pre-school to secondary level by 2030 and cites 3.22 crore out-of-school children aged 6 to 17 (NSSO, 2017-18). It plans wider open schooling through NIOS and State Open Schools at levels equal to Classes 3, 5, 8, 10 and 12, alternative centres for migrant children, free boarding to the Navodaya standard, more Kendriya and Navodaya Vidyalayas, continued home-based education for children with severe and profound disabilities who cannot attend school, and support for alternative schools.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Human Resource Development, Government of India","mandateType":"policy-statement","adoptionDate":"2020-07-29","dateGranularity":"day","statementText":"NEP 2020 sets a goal of 100 per cent gross enrolment ratio from pre-school to secondary level by 2030 and cites 3.22 crore out-of-school children aged 6 to 17 (NSSO, 2017-18). It plans wider open schooling through NIOS and State Open Schools at levels equal to Classes 3, 5, 8, 10 and 12, alternative centres for migrant children, free boarding to the Navodaya standard, more Kendriya and Navodaya Vidyalayas, continued home-based education for children with severe and profound disabilities who cannot attend school, and support for alternative schools.","subject":"general","topicTags":["out-of-school children","open schooling","NIOS","alternative schools","boarding schools","Kendriya Vidyalaya","Navodaya Vidyalaya","home-based education","school access"]}', '2020-07-29'),
  ('8bc47897-ac99-5edf-8822-d40690fd6048', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-early-childhood-care-anganwadi-and-preparatory-class', 'NEP 2020 (Ministry of Human Resource Development): early childhood care through Anganwadis, pre-primary sections and a Preparatory Class', '{"id":"IN-MANDATE-nep-2020-early-childhood-care-anganwadi-and-preparatory-class","label":"NEP 2020 (Ministry of Human Resource Development): early childhood care through Anganwadis, pre-primary sections and a Preparatory Class","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020, Part I, Chapter 1 ''Early Childhood Care and Education'', paras 1.4 to 1.8 (printed pp. 7-8). AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. A second AI reader re-read paras 1.4 to 1.8 (printed pp. 7-8) in the PIB-hosted PDF on 30 October 2026. The document prints no date. The Union Cabinet approved the policy on 29 July 2020 (PIB release of that date), which is the date used. The existing record on the 5+3+3+4 stages covers the overall design; this record adds who delivers the early years. The UDISE+ 2024-25 report says its pre-primary figures leave out Anganwadi centres and private kindergartens (see the UDISE+ record). Para 1.8 also mentions another type of early-years setting in a context outside this round''s scope; it was left out. The AI reader did not read the Foundational Stage framework chapter on language and literacy, so this record has no language content for ages 3 to 8. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020, Part I, Chapter 1 ''Early Childhood Care and Education'', paras 1.4 to 1.8 (printed pp. 7-8)","description":"NEP 2020 plans universal access to early childhood care and education through four kinds of centre: stand-alone Anganwadis, Anganwadis beside primary schools, pre-primary sections covering at least ages 5 to 6 in primary schools, and stand-alone pre-schools. It is envisaged that before age 5 every child moves to a Preparatory Class (Balavatika) with an ECCE-qualified teacher and mainly play-based learning. Current Anganwadi workers will receive a 6-month certificate or one-year diploma in ECCE, depending on qualification, and Anganwadis will be integrated into school complexes.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Human Resource Development, Government of India","mandateType":"policy-statement","adoptionDate":"2020-07-29","dateGranularity":"day","statementText":"NEP 2020 plans universal access to early childhood care and education through four kinds of centre: stand-alone Anganwadis, Anganwadis beside primary schools, pre-primary sections covering at least ages 5 to 6 in primary schools, and stand-alone pre-schools. It is envisaged that before age 5 every child moves to a Preparatory Class (Balavatika) with an ECCE-qualified teacher and mainly play-based learning. Current Anganwadi workers will receive a 6-month certificate or one-year diploma in ECCE, depending on qualification, and Anganwadis will be integrated into school complexes.","subject":"general","topicTags":["early childhood care and education","Anganwadi","Balavatika","preparatory class","foundational stage","school complexes"]}', '2020-07-29'),
  ('6557973f-e537-5332-84c1-64a5155e7426', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-vocational-education-and-internships-in-school', 'NEP 2020 (Ministry of Human Resource Development): vocational courses and internships with local experts in Classes 6 to 12', '{"id":"IN-MANDATE-nep-2020-vocational-education-and-internships-in-school","label":"NEP 2020 (Ministry of Human Resource Development): vocational courses and internships with local experts in Classes 6 to 12","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020, Part I, Chapter 4, para 4.26 (printed p. 16); Part III, Chapter 16 ''Vocational Education'', paras 16.4 to 16.6 (printed p. 44). AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. A second AI reader re-read para 4.26 (printed p. 16) and paras 16.4 to 16.6 (p. 44) in the PIB-hosted PDF on 30 October 2026. The document prints no date. The Union Cabinet approved the policy on 29 July 2020 (PIB release of that date), which is the date used. Chapter 16 also states a target of exposure to vocational education for at least half of all learners by 2025, covering school and higher education together; whether that target was met was not checked. Para 4.9, which is not in the passage list, also says there will be no hard separation between vocational and academic streams. The AI reader searched the NEP text for apprenticeships in school and found them only in the higher-education parts. The course, the 10-day period and the internships are plans in the policy text; the AI reader did not check whether States have introduced them. A second AI reader corrected this record against the source (6 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020, Part I, Chapter 4, para 4.26 (printed p. 16); Part III, Chapter 16 ''Vocational Education'', paras 16.4 to 16.6 (printed p. 44)","description":"NEP 2020 says every student will take a course in Classes 6 to 8 sampling vocational crafts, chosen by States and local communities, and spend a 10-day bagless period interning with local vocational experts. Similar internships may run through Classes 6 to 12. The policy aims to overcome the social status hierarchy attached to vocational education, to have every child learn at least one vocation and be exposed to several more, and to bring vocational education into all secondary schools in phases over the next decade.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Human Resource Development, Government of India","mandateType":"policy-statement","adoptionDate":"2020-07-29","dateGranularity":"day","statementText":"NEP 2020 says every student will take a course in Classes 6 to 8 sampling vocational crafts, chosen by States and local communities, and spend a 10-day bagless period interning with local vocational experts. Similar internships may run through Classes 6 to 12. The policy aims to overcome the social status hierarchy attached to vocational education, to have every child learn at least one vocation and be exposed to several more, and to bring vocational education into all secondary schools in phases over the next decade.","subject":"vocational-education","gradeFrom":6,"gradeTo":12,"topicTags":["vocational education","internship","bagless days","crafts","skills","secondary school"]}', '2020-07-29'),
  ('32bcf56c-5aac-5394-84d1-5240e6a98c66', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-language-education-aims-and-three-languages', 'NCERT, NCF-SE 2023, Part C Chapter 2 Language Education: aims, the three languages R1, R2 and R3, and the medium of instruction', '{"id":"IN-MANDATE-ncf-se-2023-language-education-aims-and-three-languages","label":"NCERT, NCF-SE 2023, Part C Chapter 2 Language Education: aims, the three languages R1, R2 and R3, and the medium of instruction","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: NCF-SE 2023 (NCERT first edition, October 2024 print), Part C Chapter 2 Language Education, Sections 2.1 and 2.4 including Box 2.2i (printed pp. 215-220); summary in Part A Chapter 1, section 1.6.1 (printed pp. 22-23). AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. A second AI reader re-read Part C Chapter 2 Sections 2.1 and 2.4 including Box 2.2i, and Part A 1.6.1, on 30 October 2026. Date: the Ministry of Education released the framework on 23 August 2023 (PIB release of that date). The foreword is dated 29 July 2023 and the NCERT PDF is a first-edition print of October 2024. Page numbers are printed numbers; the PDF page is 14 higher. Box 2.2i says the framework makes no distinction between languages and dialects, that the state or other relevant bodies would decide the choices of R1, R2 and R3, and that where the mother tongue cannot be R1 the most familiar local language may be used. The AI reader did not read the Foundational Stage framework chapter on early literacy that Box 2.2i points to, or the competency tables for R1, R2 and R3. A second AI reader corrected this record against the source (8 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"NCF-SE 2023 (NCERT first edition, October 2024 print), Part C Chapter 2 Language Education, Sections 2.1 and 2.4 including Box 2.2i (printed pp. 215-220); summary in Part A Chapter 1, section 1.6.1 (printed pp. 22-23)","description":"NCF-SE 2023 aims for students to speak, read and write independently in three or more languages, two or more native to India, with R1 by Class 3, R2 by Class 6 and R3 by Class 9. R1, the language of first literacy, should preferably be the one most familiar to the child, the mother tongue, or else the state language. R1 must be the medium for other subjects, at least until the child is literate in another language. An Indian language must be an available medium option to Class 12.","verificationStatus":"primary-source-confirmed","issuingBody":"National Council of Educational Research and Training (NCERT)","mandateType":"curriculum-framework","adoptionDate":"2023-08-23","dateGranularity":"day","statementText":"NCF-SE 2023 aims for students to speak, read and write independently in three or more languages, two or more native to India, with R1 by Class 3, R2 by Class 6 and R3 by Class 9. R1, the language of first literacy, should preferably be the one most familiar to the child, the mother tongue, or else the state language. R1 must be the medium for other subjects, at least until the child is literate in another language. An Indian language must be an available medium option to Class 12.","subject":"languages","topicTags":["language education","multilingualism","R1 R2 R3","mother tongue","medium of instruction","three-language formula"]}', '2023-08-23'),
  ('34246007-87ae-54c5-a5ca-52a248a13662', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-language-stage-goals-nature-of-language-and-sign-language', 'NCERT, NCF-SE 2023, Part C Chapter 2: language goals by stage, Classes 11 and 12, nature of language and Indian Sign Language', '{"id":"IN-MANDATE-ncf-se-2023-language-stage-goals-nature-of-language-and-sign-language","label":"NCERT, NCF-SE 2023, Part C Chapter 2: language goals by stage, Classes 11 and 12, nature of language and Indian Sign Language","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: NCF-SE 2023 (NCERT first edition, October 2024 print), Part C Chapter 2, Section 2.2 ''Nature of Knowledge'' (printed p. 217), the stage description in Section 2.4 (printed pp. 220-221), Box 2.2ii ''Indian Sign Language'' (p. 221); Part B Chapter 4 Inclusion in Schools, Section 4.2(b) on home language and Indian Sign Language in inclusive classrooms (printed pp. 166-167). AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. A second AI reader re-read Part C Chapter 2 Sections 2.2 and 2.4 and Box 2.2ii, and Part B Section 4.2(b), on 30 October 2026. Date: the Ministry of Education released the framework on 23 August 2023 (PIB release of that date); the NCERT PDF is a first-edition print of October 2024. Page numbers are printed numbers; the PDF page is 14 higher. The framework gives no goals for Classes 11 and 12 language courses. Box 2.2ii also says students with hearing impairment often find it hard to be admitted to regular schools; the record leaves that out because the claim was not checked against other sources. The AI reader did not read the full tables of curricular goals and competencies for R1, R2 and R3. A second AI reader corrected this record against the source (7 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"NCF-SE 2023 (NCERT first edition, October 2024 print), Part C Chapter 2, Section 2.2 ''Nature of Knowledge'' (printed p. 217), the stage description in Section 2.4 (printed pp. 220-221), Box 2.2ii ''Indian Sign Language'' (p. 221); Part B Chapter 4 Inclusion in Schools, Section 4.2(b) on home language and Indian Sign Language in inclusive classrooms (printed pp. 166-167)","description":"NCF-SE 2023 describes language as a rule-governed system, part of culture, that changes over time and takes ideas from other languages. Stages: two spoken languages in the Foundational Stage; reading and writing in both in the Preparatory Stage; a third language from the Middle Stage; academic proficiency in two languages by the end of Class 10. Classes 11 and 12: at least two languages, one native to India. Schools could consider offering Indian Sign Language, which has its own grammar. All students should get basic familiarity with a few signs.","verificationStatus":"primary-source-confirmed","issuingBody":"National Council of Educational Research and Training (NCERT)","mandateType":"curriculum-framework","adoptionDate":"2023-08-23","dateGranularity":"day","statementText":"NCF-SE 2023 describes language as a rule-governed system, part of culture, that changes over time and takes ideas from other languages. Stages: two spoken languages in the Foundational Stage; reading and writing in both in the Preparatory Stage; a third language from the Middle Stage; academic proficiency in two languages by the end of Class 10. Classes 11 and 12: at least two languages, one native to India. Schools could consider offering Indian Sign Language, which has its own grammar. All students should get basic familiarity with a few signs.","subject":"languages","topicTags":["language education","nature of language","language change","stage-wise goals","Indian Sign Language","classical languages"]}', '2023-08-23'),
  ('0b212c0f-4413-5f6d-974b-3ea005f7d0d8', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-rte-act-2009-right-to-schooling-ages-6-14-and-school-types', 'Right to Education Act 2009 (Parliament of India): who has the right, ages 6 to 14, school types and the 25 per cent rule', '{"id":"IN-MANDATE-rte-act-2009-right-to-schooling-ages-6-14-and-school-types","label":"Right to Education Act 2009 (Parliament of India): who has the right, ages 6 to 14, school types and the 25 per cent rule","sourceUrl":"https://www.indiacode.nic.in/bitstream/123456789/2086/5/a2009-35.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Right of Children to Free and Compulsory Education Act, 2009, sections 1(5), 2(c), 2(f), 2(n), 2(p), 3, 4, 8, 10, 11 and 12 (India Code PDF, as amended to 2019). AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. The first AI reader read the India Code PDF through a Wayback Machine capture of 4 January 2025. A second AI reader could not open the India Code PDF, the Ministry''s copy or the Wayback capture on 30 October 2026, and checked the cited sections against a State government website''s transcription of the Act (as amended by Act 30 of 2012) and a legal-database copy; both agree with this record. The Act is dated 26 August 2009 and came into force on 1 April 2010 by notification. Section 1(5), on Madrasas, Vedic Pathsalas and institutions mainly giving religious instruction, was added by the 2012 amendment; section 1(4) makes the Act subject to Articles 29 and 30 of the Constitution. Section 3(3) lets a child with severe or multiple disability opt for home-based education. Section 11 says governments may provide free pre-school education from age three. Case law and State rules were not read. A second AI reader corrected this record against the source (7 points). The second reader could not open the source. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Right of Children to Free and Compulsory Education Act, 2009, sections 1(5), 2(c), 2(f), 2(n), 2(p), 3, 4, 8, 10, 11 and 12 (India Code PDF, as amended to 2019)","description":"The Act gives every child aged six to fourteen a right to free and compulsory education at a neighbourhood school up to Class 8. It covers four school types: government or local-authority, aided, specified-category (such as Kendriya Vidyalayas) and unaided. Government schools educate all admitted children free, aided schools in proportion to their aid (at least 25 per cent), and specified-category and unaided schools at least 25 per cent of Class 1, from weaker or disadvantaged groups. Madrasas, Vedic Pathsalas and institutions mainly giving religious instruction are outside the Act.","verificationStatus":"primary-source-confirmed","issuingBody":"Parliament of India (Act No. 35 of 2009)","mandateType":"policy-statement","adoptionDate":"2009-08-26","dateGranularity":"day","statementText":"The Act gives every child aged six to fourteen a right to free and compulsory education at a neighbourhood school up to Class 8. It covers four school types: government or local-authority, aided, specified-category (such as Kendriya Vidyalayas) and unaided. Government schools educate all admitted children free, aided schools in proportion to their aid (at least 25 per cent), and specified-category and unaided schools at least 25 per cent of Class 1, from weaker or disadvantaged groups. Madrasas, Vedic Pathsalas and institutions mainly giving religious instruction are outside the Act.","subject":"general","gradeFrom":1,"gradeTo":8,"topicTags":["right to education","school types","government schools","aided schools","unaided schools","25 per cent provision","neighbourhood school","compulsory education"]}', '2009-08-26'),
  ('822034f0-70fb-5a86-b89e-eb4a38955e5c', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-rte-act-2009-who-sets-the-curriculum-mother-tongue-clause-and-parent-committees', 'Right to Education Act 2009 (Parliament of India): who lays down the curriculum, the mother-tongue clause, school committees', '{"id":"IN-MANDATE-rte-act-2009-who-sets-the-curriculum-mother-tongue-clause-and-parent-committees","label":"Right to Education Act 2009 (Parliament of India): who lays down the curriculum, the mother-tongue clause, school committees","sourceUrl":"https://www.indiacode.nic.in/bitstream/123456789/2086/5/a2009-35.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Right of Children to Free and Compulsory Education Act, 2009, sections 7(6), 21, 29 and 30 (India Code PDF, as amended to 2019). AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. The first AI reader read sections 21, 29 and 30 in full and section 7(6) as part of the full text of the India Code PDF, through a Wayback Machine capture. A second AI reader could not open the India Code PDF, the Ministry''s copy or the Wayback capture on 30 October 2026, and checked the cited sections against a State government website''s transcription of the Act and a legal-database copy; both agree with this record. The mother-tongue wording is clause (f) of section 29(2), one of eight matters the academic authority must take into consideration. School Management Committees are required in every school other than an unaided school. Rajasthan has a State amendment to section 29(1) that adds the class-appropriate learning level; it is left out of the statement and was not checked. A Supreme Court judgment of 12 May 2026 (Padam Mehta v. State of Rajasthan) applies section 29(2)(f); it is not summarised here, and the AI reader read only its headnote. Case law and State rules are otherwise not covered. A second AI reader corrected this record against the source (8 points). The second reader could not open the source. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Right of Children to Free and Compulsory Education Act, 2009, sections 7(6), 21, 29 and 30 (India Code PDF, as amended to 2019)","description":"Section 29 says an academic authority, specified by each government, lays down the curriculum and evaluation for Classes 1 to 8. The authority must take eight listed matters into consideration, one being that the medium of instruction shall, as far as practicable, be the child''s mother tongue. The Centre is to develop a national curriculum framework with that authority''s help (section 7). School Management Committees, at least three-fourths parents or guardians, monitor schools and only advise in aided and minority-run schools. No board examination is required before Class 8 ends.","verificationStatus":"primary-source-confirmed","issuingBody":"Parliament of India (Act No. 35 of 2009)","mandateType":"policy-statement","adoptionDate":"2009-08-26","dateGranularity":"day","statementText":"Section 29 says an academic authority, specified by each government, lays down the curriculum and evaluation for Classes 1 to 8. The authority must take eight listed matters into consideration, one being that the medium of instruction shall, as far as practicable, be the child''s mother tongue. The Centre is to develop a national curriculum framework with that authority''s help (section 7). School Management Committees, at least three-fourths parents or guardians, monitor schools and only advise in aided and minority-run schools. No board examination is required before Class 8 ends.","subject":"general","gradeFrom":1,"gradeTo":8,"topicTags":["curriculum authority","medium of instruction","mother tongue","school management committee","parents","national curriculum framework"]}', '2009-08-26'),
  ('4c0d45b7-bbe5-59be-9452-56bbf7f70a2a', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management', 'Ministry of Education, UDISE+ 2024-25 report: schools and enrolment by management type, Kendriya and Navodaya Vidyalayas (Table 1)', '{"id":"IN-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management","label":"Ministry of Education, UDISE+ 2024-25 report: schools and enrolment by management type, Kendriya and Navodaya Vidyalayas (Table 1)","sourceUrl":"https://dashboard.udiseplus.gov.in/report-new-v.6-demo2025/static/media/UDISE%2B2024_25_Booklet_existing.118ba29d4773e6372f72.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Report on UDISE+ 2024-25 (booklet), Table 1 ''National Highlights of UDISE+ data, 2024-25'', printed p. 28; disclaimer p. 7; footnote p. 10 and para 3.1.2 on pre-primary coverage. AI-drafted from a direct reading of the primary document; no subject expert has reviewed this record. A second AI reader re-read Table 1 from a rendered image on 30 October 2026 and re-added every figure; none changed. Date: the Ministry of Education released the 2024-25 report on 28 August 2025 (PIB release of that date). This record describes the 2024-25 edition only. A later edition, UDISE+ 2025-26, was released on 7 July 2026 and has different figures. The report says its pre-primary numbers leave out Anganwadi centres and private kindergartens, that data cover schools with a UDISE+ code up to 31 March 2025, and that from 2024-25 they are not strictly comparable with reports up to 2021-22. The table also lists 19,690 recognised madrasas; the statement does not use that figure. A gross enrolment ratio compares enrolment of all ages with the population of the age group, so it can differ from the share of children enrolled. The report has no table on medium of instruction or out-of-school children. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Report on UDISE+ 2024-25 (booklet), Table 1 ''National Highlights of UDISE+ data, 2024-25'', printed p. 28; disclaimer p. 7; footnote p. 10 and para 3.1.2 on pre-primary coverage","description":"UDISE+ 2024-25 counts 1,471,473 schools and 246,932,680 students from pre-primary to Class 12. Government schools number 1,013,322 with 121,589,911 students, government-aided 79,349 with 24,761,526, private unaided recognised 339,583 with 95,856,710, and other schools 39,219 with 4,724,533. Government schools hold about 49 per cent of enrolment and private unaided about 39 per cent. The table lists 1,253 Kendriya and 653 Navodaya Vidyalayas and 46,517 residential schools.","verificationStatus":"primary-source-confirmed","issuingBody":"Department of School Education and Literacy, Ministry of Education, Government of India","mandateType":"other","adoptionDate":"2025-08-28","dateGranularity":"day","statementText":"UDISE+ 2024-25 counts 1,471,473 schools and 246,932,680 students from pre-primary to Class 12. Government schools number 1,013,322 with 121,589,911 students, government-aided 79,349 with 24,761,526, private unaided recognised 339,583 with 95,856,710, and other schools 39,219 with 4,724,533. Government schools hold about 49 per cent of enrolment and private unaided about 39 per cent. The table lists 1,253 Kendriya and 653 Navodaya Vidyalayas and 46,517 residential schools.","subject":"general","topicTags":["UDISE+","schools by management","enrolment","government schools","private schools","Kendriya Vidyalaya","Navodaya Vidyalaya","residential schools","gross enrolment ratio"]}', '2025-08-28'),
  ('d36f565a-1091-5c56-9ebc-d8092091915f', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-MANDATE-supreme-court-2014-medium-of-instruction-classes-1-4-order-1994', 'Supreme Court of India, 6 May 2014: Karnataka''s 1994 order on the mother tongue as medium in Classes 1 to 4', '{"id":"IN-KA-MANDATE-supreme-court-2014-medium-of-instruction-classes-1-4-order-1994","label":"Supreme Court of India, 6 May 2014: Karnataka''s 1994 order on the mother tongue as medium in Classes 1 to 4","sourceUrl":"https://api.sci.gov.in/jonew/judis/41504.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: State of Karnataka v. Associated Management of (Government Recognised-Unaided-English Medium) Primary and Secondary Schools, Civil Appeal Nos. 5166-5190 of 2013, judgment of 6 May 2014, Supreme Court copy of 67 pages: facts and clauses 2 to 8 of the 1994 order (pp. 2-5); questions referred (p. 12); answers to question (i) p. 36, (ii) pp. 46-47, (iii) pp. 47-62, (iv) pp. 62-65, (v) pp. 65-66; order dismissing the appeals p. 66; signed 6 May 2014 p. 67.. AI-drafted, unreviewed. The first drafter read a third-party copy. The checker re-read the judgment on the Supreme Court''s own site and compared the clauses of the 1994 order, the five referred questions and the answers. The 1994 order itself is known only as quoted in the judgment (clauses 2 to 8). Clause 6 lets only pupils whose mother tongue is English use English medium in Classes 1 to 4 of existing English-medium schools. Answer (i): in the Constitution, ''mother tongue'' means the language of the linguistic minority group in a State, and the parent or guardian decides the child''s mother tongue (p. 36). Answer (ii): the right to choose the medium at primary stage comes from Article 19(1)(a). The Court found no such right in Articles 21 and 21A, and said the State may decide the medium by law in schools where it provides free education under Article 21A (pp. 46-47). Answer (iii): the State cannot make mother-tongue medium a condition of recognition for minority schools and private unaided schools (p. 62). Answer (iv): recognised schools include aided and unaided schools (p. 65). Answer (v): Article 350A gives the State no power to compel linguistic minorities to use only the mother tongue as medium in primary schools (p. 66). The State''s appeals and the connected petitions were dismissed (p. 66). An earlier order of 19 June 1989, corrected on 22 June 1989, is described on pp. 2-3. Not read: any later Karnataka order on the medium of instruction. Press reports on English-medium or bilingual sections in government schools were not opened and are not used. Neutral wording: the record says what the order and the ruling contain and makes no comment on either. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"State of Karnataka v. Associated Management of (Government Recognised-Unaided-English Medium) Primary and Secondary Schools, Civil Appeal Nos. 5166-5190 of 2013, judgment of 6 May 2014, Supreme Court copy of 67 pages: facts and clauses 2 to 8 of the 1994 order (pp. 2-5); questions referred (p. 12); answers to question (i) p. 36, (ii) pp. 46-47, (iii) pp. 47-62, (iv) pp. 62-65, (v) pp. 65-66; order dismissing the appeals p. 66; signed 6 May 2014 p. 67.","description":"A Karnataka order of 29 April 1994 made mother tongue or Kannada the medium in Classes 1 to 4 of recognised schools and let pupils change medium from Class 5. On 6 May 2014 a Supreme Court Constitution Bench held that the parent or guardian decides the child''s mother tongue. It found the right to choose the medium at primary stage in Article 19(1)(a) and none in Articles 21 and 21A. It held the State cannot make mother-tongue medium a condition of recognition for minority schools and private unaided schools.","verificationStatus":"primary-source-confirmed","issuingBody":"Supreme Court of India (Constitution Bench), ruling on an order of the Government of Karnataka","mandateType":"policy-statement","adoptionDate":"2014-05-06","dateGranularity":"day","statementText":"A Karnataka order of 29 April 1994 made mother tongue or Kannada the medium in Classes 1 to 4 of recognised schools and let pupils change medium from Class 5. On 6 May 2014 a Supreme Court Constitution Bench held that the parent or guardian decides the child''s mother tongue. It found the right to choose the medium at primary stage in Article 19(1)(a) and none in Articles 21 and 21A. It held the State cannot make mother-tongue medium a condition of recognition for minority schools and private unaided schools.","subject":"language","gradeFrom":1,"gradeTo":4,"topicTags":["medium of instruction","mother tongue","kannada","primary classes","minority schools"]}', '2014-05-06'),
  ('e1069299-57e9-526e-9fe7-4db2322b53f4', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-MANDATE-kannada-language-learning-act-2015', 'Karnataka Act 22 of 2015, Kannada Language Learning Act: Kannada taught in Standards 1 to 10 of all schools', '{"id":"IN-KA-MANDATE-kannada-language-learning-act-2015","label":"Karnataka Act 22 of 2015, Kannada Language Learning Act: Kannada taught in Standards 1 to 10 of all schools","sourceUrl":"https://www.latestlaws.com/mobile/app/bare-acts/49581","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: Kannada Language Learning Act, 2015 (Karnataka Act No. 22 of 2015): preamble, section 2(e) definition of school, section 3(1) to 3(4).. AI-drafted, unreviewed. The drafter read the Act''s text on latestlaws.com. The checker re-read it there and compared it with a second third-party copy (casemine.com, read through a fetch tool), which gives the same section 3. The India Code PDF could not be opened (server error on three tries), so the record stays secondary-source-only. Printed dates: assent of the Governor 29 April 2015; first published in the Karnataka Gazette Extraordinary 2 May 2015. Section 1(2) says the Act comes into force on a date the Government appoints by notification. The casemine copy prints Notification No. ED 242 PGC 2015 of 22 May 2015 bringing the Act into force on 22 May 2015; this was not seen on an official copy. The adoption date above is the assent date. The Act''s heading for section 3 reads ''Kannada as a Compulsory Language''. The Act does not name a medium of instruction. Not read: the rules made under the Act, later orders on how Kannada is split between first and second language by board, and the Karnataka Kannada Language Comprehensive Development Act 2022. A news summary says the Act''s application to central-board schools was disputed; this was not verified. Neutral wording: the record gives what the Act says. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"Kannada Language Learning Act, 2015 (Karnataka Act No. 22 of 2015): preamble, section 2(e) definition of school, section 3(1) to 3(4).","description":"The Act requires every school in Karnataka, whether run by the State, local bodies or private agencies, to teach Kannada in all classes as a first or second language. Schools not already doing so introduce it in Standard 1 in 2015-16 and extend it to higher standards in later years, up to Standard 10. Schools must use the state-prescribed Kannada textbooks. A pupil who has not taken a home language other than Kannada as a first or second language may study that language as a third language.","verificationStatus":"secondary-source-only","issuingBody":"Karnataka State Legislature and Government of Karnataka","mandateType":"policy-statement","adoptionDate":"2015-04-29","dateGranularity":"day","statementText":"The Act requires every school in Karnataka, whether run by the State, local bodies or private agencies, to teach Kannada in all classes as a first or second language. Schools not already doing so introduce it in Standard 1 in 2015-16 and extend it to higher standards in later years, up to Standard 10. Schools must use the state-prescribed Kannada textbooks. A pupil who has not taken a home language other than Kannada as a first or second language may study that language as a third language.","subject":"language","gradeFrom":1,"gradeTo":10,"topicTags":["kannada","first language","second language","third language","mother tongue","school language policy"]}', '2015-04-29'),
  ('b2243b82-92b2-5a4f-88cf-559f7caf6d46', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management', 'Ministry of Education, UDISE+ 2024-25: Karnataka''s schools and pupils by management type', '{"id":"IN-KA-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management","label":"Ministry of Education, UDISE+ 2024-25: Karnataka''s schools and pupils by management type","sourceUrl":"https://dashboard.udiseplus.gov.in/report-new-v.6-demo2025/static/media/UDISE%2B2024_25_Booklet_existing.118ba29d4773e6372f72.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Report on UDISE+ 2024-25, Table 3.2 to 3.6 (schools by management, printed pp. 41-45) and Table 5.1 to 5.5 (enrolment by management, pp. 85-89); definitions of management types on p. 187.. AI-drafted, unreviewed. The checker re-opened the 189-page Ministry of Education report and checked every figure against the Karnataka rows of Tables 3.2 to 3.6 (printed pp. 41-45) and Tables 5.1 to 5.5 (pp. 85-89). Schools 74,859 = 48,844 + 6,905 + 19,105 + 5 (government, government aided, private unaided recognised, others). Pupils 11,780,251 = 4,734,360 + 1,381,517 + 5,663,887 + 487. All eight percentages were recomputed and round correctly to one decimal. The page and table numbers in sourcePassage are right; the printed page number equals the PDF page number. The report''s own definitions (p. 187, read as an image): ''government'' means State Government schools run by the education, tribal welfare, social welfare, minority affairs or labour departments, local bodies or other State bodies, plus central government schools (Kendriya Vidyalaya, Jawahar Navodaya, Sainik, railway, Central Tibetan and other central or PSU schools); ''government aided'' covers aided and partially aided schools; ''private unaided'' covers recognised schools only; ''others'' covers unrecognised schools, madrasas (recognised, unrecognised and aided) and Veda schools, gurukuls and pathashalas, so an aided madrasa is counted under ''others''. Pupil counts are the ''Total (pre-primary to 12)'' column. Table 2.7 (p. 38) lists 76 further pupils for Karnataka reported at block level; they are outside the 11,780,251 total used here. The report says the data come from voluntary uploads by schools with a cut-off of 31 March 2025 and that the Ministry accepts no liability for errors in them (Disclaimer, p. 7). No release date is printed in the report. Press coverage dates the release to 28 August 2025, which the checker did not confirm from an official page, so only the year is given. The statement leaves out the ''others'' group (5 schools, 487 pupils; under 0.1 percent of each). Karnataka''s own Department of School Education pages were not reachable, so no state-level school-type figures were read. The numbers describe who runs and who attends schools. They say nothing about quality or outcomes. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"Report on UDISE+ 2024-25, Table 3.2 to 3.6 (schools by management, printed pp. 41-45) and Table 5.1 to 5.5 (enrolment by management, pp. 85-89); definitions of management types on p. 187.","description":"In 2024-25 Karnataka had 74,859 schools and 11,780,251 pupils from pre-primary to Class 12. Government schools were 65.2 percent of schools and 40.2 percent of pupils; government-aided schools 9.2 and 11.7 percent; private unaided recognised schools 25.5 and 48.1 percent.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (Department of School Education and Literacy), Government of India","mandateType":"other","adoptionDate":"2025","dateGranularity":"year","statementText":"In 2024-25 Karnataka had 74,859 schools and 11,780,251 pupils from pre-primary to Class 12. Government schools were 65.2 percent of schools and 40.2 percent of pupils; government-aided schools 9.2 and 11.7 percent; private unaided recognised schools 25.5 and 48.1 percent.","subject":"general","topicTags":["school management","government schools","aided schools","private schools","enrolment"]}', ''),
  ('a3b4eee9-c1f9-532a-a929-9dd98e6c2252', 'maharashtra-curriculum-repository', 'institutional-mandate-record', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-MANDATE-gr-corrigendum-2025-06-17-hindi-generally-third-language-classes-1-5', 'Maharashtra School Education and Sports Department, corrigendum of 17 June 2025: Hindi ''generally'' the third language, Classes 1 to 5', '{"id":"IN-MH-MANDATE-gr-corrigendum-2025-06-17-hindi-generally-third-language-classes-1-5","label":"Maharashtra School Education and Sports Department, corrigendum of 17 June 2025: Hindi ''generally'' the third language, Classes 1 to 5","sourceUrl":"https://gr.maharashtra.gov.in/Site/Upload/Government%20Resolutions/Marathi/202506172233593421.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Government corrigendum (Shasan Shuddhipatrak), No. Sankirna-2025/Pra.Kra.94/SD-4, 17 June 2025, pp. 1-2: the paragraph under ''Language policy'' in para 3 of the decision of 16 April 2025, and its replacement.. AI-drafted, unreviewed. The checker downloaded the 3-page Marathi PDF from the state GR portal and read pages 1 and 2 as page images (the text layer is unreadable). Confirmed from the images: date 17 June 2025; number Sankirna-2025/Pra.Kra.94/SD-4; the heading names State Board schools of Marathi and English medium for Classes 1 to 5; the quoted paragraph being replaced (Hindi compulsory third language in Marathi and English medium schools; in schools of other media the medium language, Marathi and English; Classes 6 to 10 as per the 2024 State Curriculum Framework); the replacement wording ''generally'' for Hindi; another Indian language allowed if pupils wish and at least 20 pupils of a class in the school ask for it; a teacher to be made available, otherwise online teaching (the text does not say who provides the teacher); Marathi compulsory in schools of all media; all planning to be done at once at the level of the Commissioner (Education), Pune. The 16 April 2025 decision itself was not opened; it is known from this quotation and the reference line. What happened next is in the separate event record. Neutral wording: the record repeats the document''s provisions and says nothing on why they were issued or changed. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"Government corrigendum (Shasan Shuddhipatrak), No. Sankirna-2025/Pra.Kra.94/SD-4, 17 June 2025, pp. 1-2: the paragraph under ''Language policy'' in para 3 of the decision of 16 April 2025, and its replacement.","description":"The corrigendum of 17 June 2025 changes the department''s decision of 16 April 2025, which had made Hindi the compulsory third language in Classes 1 to 5 of Marathi and English medium State Board schools. It says Hindi will generally be the third language. Pupils may take another Indian language instead if at least 20 pupils of a class in the school ask for it. A teacher is then to be made available, otherwise the language is taught online. Marathi is compulsory in schools of all media.","verificationStatus":"primary-source-confirmed","issuingBody":"School Education and Sports Department, Government of Maharashtra","mandateType":"policy-statement","adoptionDate":"2025-06-17","dateGranularity":"day","statementText":"The corrigendum of 17 June 2025 changes the department''s decision of 16 April 2025, which had made Hindi the compulsory third language in Classes 1 to 5 of Marathi and English medium State Board schools. It says Hindi will generally be the third language. Pupils may take another Indian language instead if at least 20 pupils of a class in the school ask for it. A teacher is then to be made available, otherwise the language is taught online. Marathi is compulsory in schools of all media.","subject":"language","gradeFrom":1,"gradeTo":5,"topicTags":["three-language","third language","hindi","marathi","medium of instruction","primary classes"]}', '2025-06-17'),
  ('afd22174-f32b-56b3-939f-5e742646e90d', 'maharashtra-curriculum-repository', 'policy-timeline-event', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-EVENT-third-language-orders-cancelled-2025-06-29-and-review-committee-report-2026-02', 'Government of Maharashtra announces cancellation of its April and June 2025 third-language orders for Classes 1 to 5 and a review committee', '{"id":"IN-MH-EVENT-third-language-orders-cancelled-2025-06-29-and-review-committee-report-2026-02","label":"Government of Maharashtra announces cancellation of its April and June 2025 third-language orders for Classes 1 to 5 and a review committee","sourceUrl":"https://www.newsonair.gov.in/maharashtra-govt-withdraws-its-3-language-policy-for-schools","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: All India Radio (Akashvani) regional news item, 30 June 2025, ''Maharashtra govt withdraws its 3 language policy for schools''; and item of 9 February 2026 on the review committee presenting its three-language report.. AI-drafted, unreviewed. The drafter and the checker read two short news items on the All India Radio site (a public broadcaster). The cancelling order, the order setting up the committee and the committee''s report were not found on the state GR portal or in any other official source, so the record is secondary-source-only. The 30 June 2025 item says the announcement was made ''yesterday'', so 29 June 2025; press reports give the same date. The committee''s chair is named in the item and is left out here by project rule. The 30 June item describes the second order as making Hindi optional, while the text of the 17 June corrigendum says Hindi would ''generally'' be the third language, with other Indian languages allowed under a 20-pupil condition (see the mandate record). Press reports from 2026 on what the committee recommended and what the government may decide exist; they were not opened and nothing from them is used. No official later order was found as of 30 October 2026. A reviewer should look for the cancelling order and the committee''s order on the state GR portal, where the search needs a typed image code. Neutral wording: only decisions and dates are reported. A second AI reader could not confirm all of it: Both All India Radio items were re-read. The 30 June 2025 item (8:00 am) says the Government withdrew its two orders on the third language and that the Chief Minister announced it ''yesterday'' and said a committee would review the policy. The 9 February 2026 item says the committee had submitted its report to the state government, the Chief Minister confirmed it without giving contents, and it will go before the cabinet. The statement matches both items.; Title says the Government ''cancels'' the orders and ''sets up'' the committee. No cancelling order and no order forming the committee was found, so the record can only say the Government announced these steps. Title reworded.; The cancelling order of 29 June 2025, the order forming the committee and the committee''s report could not be found. The state GR portal (gr.maharashtra.gov.in) opens, but its search needs a typed image code and the default list shows only recent orders. Web searches in English and Marathi found no official copy. The record stays secondary-source-only.; Notes repeat what Deccan Chronicle reports said the committee favours, without having opened them. That is contested content from unread sources. Replaced with a plain statement that such reports exist and are not used.; Press reports (not official) describe the 29 June step as a cabinet decision announced by the Chief Minister. The record''s wording (the Chief Minister announced) follows the AIR item and is accurate. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"All India Radio (Akashvani) regional news item, 30 June 2025, ''Maharashtra govt withdraws its 3 language policy for schools''; and item of 9 February 2026 on the review committee presenting its three-language report.","description":"On 29 June 2025 the Chief Minister announced that the orders of 16 April and 17 June 2025 on a third language in Classes 1 to 5 were cancelled, and that a committee would review the three-language policy for primary classes. All India Radio reported on 9 February 2026 that the committee had given its report to the state government, to be placed before the cabinet. The contents and any cabinet decision were not found in an official source.","verificationStatus":"secondary-source-only","slug":"third-language-orders-cancelled-2025-06-29-and-review-committee-report-2026-02","dateStart":"2025-06-29","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","topicTags":["three-language","third language","hindi","review committee","primary classes","policy change"]}', '2025-06-29'),
  ('3ab4a8c3-0bff-52ae-af16-0125145413f0', 'maharashtra-curriculum-repository', 'institutional-mandate-record', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management', 'Ministry of Education, UDISE+ 2024-25: Maharashtra''s schools and pupils by management type', '{"id":"IN-MH-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management","label":"Ministry of Education, UDISE+ 2024-25: Maharashtra''s schools and pupils by management type","sourceUrl":"https://dashboard.udiseplus.gov.in/report-new-v.6-demo2025/static/media/UDISE%2B2024_25_Booklet_existing.118ba29d4773e6372f72.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Report on UDISE+ 2024-25, Table 3.2 to 3.6 (schools by management, printed pp. 41-45) and Table 5.1 to 5.5 (enrolment by management, pp. 85-89); definitions of management types on p. 187.. AI-drafted, unreviewed. The checker re-opened the 189-page Ministry of Education report and checked every figure against the Maharashtra rows of Tables 3.2 to 3.6 (printed pp. 41-45) and Tables 5.1 to 5.5 (pp. 85-89). Schools 108,250 = 64,884 + 24,406 + 18,746 + 214 (government, government aided, private unaided recognised, others). Pupils 21,272,611 = 5,108,544 + 9,589,225 + 6,535,992 + 38,850. All eight percentages were recomputed and round correctly to one decimal. The page and table numbers in sourcePassage are right; the printed page number equals the PDF page number. The report''s own definitions (p. 187, read as an image): ''government'' means State Government schools run by the education, tribal welfare, social welfare, minority affairs or labour departments, local bodies or other State bodies, plus central government schools (Kendriya Vidyalaya, Jawahar Navodaya, Sainik, railway, Central Tibetan and other central or PSU schools); ''government aided'' covers aided and partially aided schools; ''private unaided'' covers recognised schools only; ''others'' covers unrecognised schools, madrasas (recognised, unrecognised and aided) and Veda schools, gurukuls and pathashalas, so an aided madrasa is counted under ''others''. Pupil counts are the ''Total (pre-primary to 12)'' column. Table 2.7 (p. 38) lists 26,613 further pupils for Maharashtra reported at block level; they are outside the 21,272,611 total used here. The report says the data come from voluntary uploads by schools with a cut-off of 31 March 2025 and that the Ministry accepts no liability for errors in them (Disclaimer, p. 7). No release date is printed in the report. Press coverage dates the release to 28 August 2025, which the checker did not confirm from an official page, so only the year is given. The statement leaves out the ''others'' group (214 schools, 38,850 pupils; 0.2 percent of each). Maharashtra''s own education department pages could not be opened, so only the national report''s state rows were read. The numbers describe who runs and who attends schools. They say nothing about quality or outcomes. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"Report on UDISE+ 2024-25, Table 3.2 to 3.6 (schools by management, printed pp. 41-45) and Table 5.1 to 5.5 (enrolment by management, pp. 85-89); definitions of management types on p. 187.","description":"In 2024-25 Maharashtra had 108,250 schools and 21,272,611 pupils from pre-primary to Class 12. Government schools were 59.9 percent of schools and 24.0 percent of pupils; government-aided schools 22.5 and 45.1 percent; private unaided recognised schools 17.3 and 30.7 percent.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (Department of School Education and Literacy), Government of India","mandateType":"other","adoptionDate":"2025","dateGranularity":"year","statementText":"In 2024-25 Maharashtra had 108,250 schools and 21,272,611 pupils from pre-primary to Class 12. Government schools were 59.9 percent of schools and 24.0 percent of pupils; government-aided schools 22.5 and 45.1 percent; private unaided recognised schools 17.3 and 30.7 percent.","subject":"general","topicTags":["school management","government schools","aided schools","private schools","enrolment"]}', ''),
  ('2d19b337-28e0-563c-a9ac-7f3ad03c3d5f', 'uttar-pradesh-curriculum-repository', 'institutional-mandate-record', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-MANDATE-upmsp-language-subject-syllabi-classes-9-10-2026-27', 'UP Board (UPMSP) Classes 9 and 10 syllabus 2026-27: 21 language subjects including Hindi, English, Sanskrit and Urdu', '{"id":"IN-UP-MANDATE-upmsp-language-subject-syllabi-classes-9-10-2026-27","label":"UP Board (UPMSP) Classes 9 and 10 syllabus 2026-27: 21 language subjects including Hindi, English, Sanskrit and Urdu","sourceUrl":"https://upmsp.edu.in/Board_Syllabus.aspx","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: UPMSP syllabus page (Board_Syllabus.aspx), lists of subject syllabi for Class 9 and Class 10 (language subject codes 901 to 917 and 923 to 926, 21 subjects); Class 9 files 901 Hindi, 917 English, 923 Sanskrit and 904 Urdu, page 1 of each.. AI-drafted, unreviewed. The drafter and the checker read the Board''s syllabus page and downloaded the Class 9 and Class 10 files for Hindi, English, Sanskrit and Urdu. The Hindi, Sanskrit and Urdu files use an old font with no readable text, so page 1 of the Class 9 files was read as an image; the English text layer is readable. The 2026-27 session is printed on the files. The listing page prints no session. No issue date is printed, so the date is the year only. Only Class 9 content was read closely. Not found: an official Board order on the three-language scheme. A news item (National Herald, 20 June 2024, from IANS) says Board officials announced that Hindi is compulsory for Classes 9 and 10 and that pupils choose two more languages from 19 options; that item is not used in the statement. Not read: the basic-education (Classes 1 to 8) syllabus for Hindi, Sanskrit, Urdu and English; its site did not open. Neutral wording: the record lists what the syllabus page and files show. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"UPMSP syllabus page (Board_Syllabus.aspx), lists of subject syllabi for Class 9 and Class 10 (language subject codes 901 to 917 and 923 to 926, 21 subjects); Class 9 files 901 Hindi, 917 English, 923 Sanskrit and 904 Urdu, page 1 of each.","description":"The Board''s syllabus page links, for each of Classes 9 and 10, a syllabus file in each of 21 language subjects, among them Hindi, Urdu, English, Sanskrit, Tamil and Arabic. The files read are headed Academic Session 2026-27. The Class 9 Hindi, English, Sanskrit and Urdu files each give a 70-mark written paper and 30 marks of internal assessment. The Class 9 Hindi file has a 14-mark Sanskrit section and lists tatsam and tadbhav under word formation.","verificationStatus":"primary-source-confirmed","issuingBody":"Madhyamik Shiksha Parishad, Uttar Pradesh (UP Board, UPMSP)","mandateType":"curriculum-framework","adoptionDate":"2026","dateGranularity":"year","statementText":"The Board''s syllabus page links, for each of Classes 9 and 10, a syllabus file in each of 21 language subjects, among them Hindi, Urdu, English, Sanskrit, Tamil and Arabic. The files read are headed Academic Session 2026-27. The Class 9 Hindi, English, Sanskrit and Urdu files each give a 70-mark written paper and 30 marks of internal assessment. The Class 9 Hindi file has a 14-mark Sanskrit section and lists tatsam and tadbhav under word formation.","subject":"language","gradeFrom":9,"gradeTo":10,"topicTags":["language subjects","hindi","sanskrit","urdu","english","syllabus","secondary stage"]}', ''),
  ('0fd1dbac-5ebc-57fd-926e-387d41666234', 'uttar-pradesh-curriculum-repository', 'institutional-mandate-record', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management', 'Ministry of Education, UDISE+ 2024-25: Uttar Pradesh''s schools and pupils by management type', '{"id":"IN-UP-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management","label":"Ministry of Education, UDISE+ 2024-25: Uttar Pradesh''s schools and pupils by management type","sourceUrl":"https://dashboard.udiseplus.gov.in/report-new-v.6-demo2025/static/media/UDISE%2B2024_25_Booklet_existing.118ba29d4773e6372f72.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Report on UDISE+ 2024-25, Table 3.2 to 3.6 (schools by management, printed pp. 41-45) and Table 5.1 to 5.5 (enrolment by management, pp. 85-89); definitions of management types on p. 187.. AI-drafted, unreviewed. The checker re-opened the 189-page Ministry of Education report and checked every figure against the Uttar Pradesh rows of Tables 3.2 to 3.6 (printed pp. 41-45) and Tables 5.1 to 5.5 (pp. 85-89). Schools 262,358 = 137,172 + 8,262 + 104,508 + 12,416 (government, government aided, private unaided recognised, others). Pupils 42,789,347 = 14,892,455 + 4,503,248 + 22,122,053 + 1,271,591. All eight percentages were recomputed and round correctly to one decimal. The page and table numbers in sourcePassage are right; the printed page number equals the PDF page number. The report''s own definitions (p. 187, read as an image): ''government'' means State Government schools run by the education, tribal welfare, social welfare, minority affairs or labour departments, local bodies or other State bodies, plus central government schools (Kendriya Vidyalaya, Jawahar Navodaya, Sainik, railway, Central Tibetan and other central or PSU schools); ''government aided'' covers aided and partially aided schools; ''private unaided'' covers recognised schools only; ''others'' covers unrecognised schools, madrasas (recognised, unrecognised and aided) and Veda schools, gurukuls and pathashalas, so an aided madrasa is counted under ''others''. Pupil counts are the ''Total (pre-primary to 12)'' column. Table 2.7 (p. 38) lists 95 further pupils for Uttar Pradesh reported at block level; they are outside the 42,789,347 total used here. The report says the data come from voluntary uploads by schools with a cut-off of 31 March 2025 and that the Ministry accepts no liability for errors in them (Disclaimer, p. 7). No release date is printed in the report. Press coverage dates the release to 28 August 2025, which the checker did not confirm from an official page, so only the year is given. The ''others'' group (12,416 schools, 1,271,591 pupils) is now in the statement. The Basic Education Council and Basic Education Department sites did not open, so no state figures on Classes 1 to 8 beyond the national report were read. The numbers describe who runs and who attends schools. They say nothing about quality or outcomes. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"Report on UDISE+ 2024-25, Table 3.2 to 3.6 (schools by management, printed pp. 41-45) and Table 5.1 to 5.5 (enrolment by management, pp. 85-89); definitions of management types on p. 187.","description":"In 2024-25 Uttar Pradesh had 262,358 schools and 42,789,347 pupils from pre-primary to Class 12. Government schools were 52.3 percent of schools and 34.8 percent of pupils; government-aided schools 3.1 and 10.5 percent; private unaided recognised schools 39.8 and 51.7 percent. The report''s ''other schools'' group (unrecognised schools, madrasas, Veda schools and gurukuls) was 4.7 and 3.0 percent.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (Department of School Education and Literacy), Government of India","mandateType":"other","adoptionDate":"2025","dateGranularity":"year","statementText":"In 2024-25 Uttar Pradesh had 262,358 schools and 42,789,347 pupils from pre-primary to Class 12. Government schools were 52.3 percent of schools and 34.8 percent of pupils; government-aided schools 3.1 and 10.5 percent; private unaided recognised schools 39.8 and 51.7 percent. The report''s ''other schools'' group (unrecognised schools, madrasas, Veda schools and gurukuls) was 4.7 and 3.0 percent.","subject":"general","topicTags":["school management","government schools","aided schools","private schools","enrolment"]}', ''),
  ('854e14ef-b808-553b-909b-234b414c4d94', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-malayalam-language-learning-act-2017', 'Kerala Act 8 of 2017, Malayalam Language Learning Act: Malayalam taught in Classes 1 to 10 of all schools', '{"id":"IN-KL-MANDATE-malayalam-language-learning-act-2017","label":"Kerala Act 8 of 2017, Malayalam Language Learning Act: Malayalam taught in Classes 1 to 10 of all schools","sourceUrl":"https://oss-data-in.vaquill.ai/legislation/IND_state_20184/act.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Malayalam Language Learning Act, 2017 (Act 8 of 2017), English translation published by notification No. 8445/Leg.D2/2017/Law of 2 June 2017: sections 1 to 4, pp. 2-4 of the PDF.. AI-drafted, unreviewed. The drafter and the checker read the 5-page PDF of the Law Department''s gazette translation (notification No. 8445/Leg.D2/2017/Law of 2 June 2017 under Article 348(3)). It was reached on a third-party legal-data host because the Kerala Law Secretariat and India Code pages would not open from this machine; the document prints the department''s notification and date. The Act is deemed in force from 10 April 2017 (the date of the earlier ordinance, repealed by section 8); the assent date is not on the pages read. The long title and preamble say ''compulsory language'' while section 3(1) says Malayalam ''shall be taught as a language''; both are reported as printed. Section 3(2) and 3(3) bar restrictions on speaking Malayalam in schools and notices that another language alone is to be spoken; section 4 sets a fine of 5,000 rupees on a head teacher for breaches of those two subsections, with appeal to the Director of Public Instruction within 30 days, and allows recognition or the no-objection certificate to be cancelled after three breaches. Section 3(7) promises facilities for learning Malayalam in schools for linguistic minorities and oriental schools. The Kerala Curriculum Framework 2023 language record (separate) covers the three-language curriculum and mother-tongue instruction; this record adds the statute. Not read: the rules under the Act, later circulars, and how the exemption is applied. Neutral wording: only the text and dates are reported. A second AI reader corrected this record against the source (6 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Malayalam Language Learning Act, 2017 (Act 8 of 2017), English translation published by notification No. 8445/Leg.D2/2017/Law of 2 June 2017: sections 1 to 4, pp. 2-4 of the PDF.","description":"The Act says Malayalam is taught as a language in Classes 1 to 10 in all government, aided and unaided schools, including unaided CBSE and CISCE schools, from 2017-18. Where a school does not teach it, SCERT prepares the textbook. Pupils from other states or countries who cannot follow it in class may be exempted from the Class 10 Malayalam examination but are taught from SCERT books. It is a condition of recognition for unaided schools and of the no-objection certificate for CBSE and CISCE schools with a three-language curriculum.","verificationStatus":"primary-source-confirmed","issuingBody":"Government of Kerala and Kerala Legislature (Law Department gazette translation of 2 June 2017)","mandateType":"policy-statement","adoptionDate":"2017-04-10","dateGranularity":"day","statementText":"The Act says Malayalam is taught as a language in Classes 1 to 10 in all government, aided and unaided schools, including unaided CBSE and CISCE schools, from 2017-18. Where a school does not teach it, SCERT prepares the textbook. Pupils from other states or countries who cannot follow it in class may be exempted from the Class 10 Malayalam examination but are taught from SCERT books. It is a condition of recognition for unaided schools and of the no-objection certificate for CBSE and CISCE schools with a three-language curriculum.","subject":"language","gradeFrom":1,"gradeTo":10,"topicTags":["malayalam","school language policy","recognition","linguistic minority schools","cbse","cisce"]}', '2017-04-10'),
  ('6a92ac9a-b1f3-557b-9be0-ed4684a08a07', 'kerala-school-curriculum-repository', 'institutional-mandate-record', 'IN-KL', 'openlpm-starter-draft', 'IN-KL-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management', 'Ministry of Education, UDISE+ 2024-25: Kerala''s schools and pupils by management type', '{"id":"IN-KL-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management","label":"Ministry of Education, UDISE+ 2024-25: Kerala''s schools and pupils by management type","sourceUrl":"https://dashboard.udiseplus.gov.in/report-new-v.6-demo2025/static/media/UDISE%2B2024_25_Booklet_existing.118ba29d4773e6372f72.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Report on UDISE+ 2024-25, Table 3.2 to 3.6 (schools by management, printed pp. 41-45) and Table 5.1 to 5.5 (enrolment by management, pp. 85-89); definitions of management types on p. 187.. AI-drafted, unreviewed. The checker re-opened the 189-page Ministry of Education report and checked every figure against the Kerala rows of Tables 3.2 to 3.6 (printed pp. 41-45) and Tables 5.1 to 5.5 (pp. 85-89). Schools 15,757 = 4,808 + 7,164 + 3,018 + 767 (government, government aided, private unaided recognised, others). Pupils 6,164,059 = 1,717,915 + 2,655,094 + 1,688,176 + 102,874. All eight percentages were recomputed and round correctly to one decimal. The page and table numbers in sourcePassage are right; the printed page number equals the PDF page number. The report''s own definitions (p. 187, read as an image): ''government'' means State Government schools run by the education, tribal welfare, social welfare, minority affairs or labour departments, local bodies or other State bodies, plus central government schools (Kendriya Vidyalaya, Jawahar Navodaya, Sainik, railway, Central Tibetan and other central or PSU schools); ''government aided'' covers aided and partially aided schools; ''private unaided'' covers recognised schools only; ''others'' covers unrecognised schools, madrasas (recognised, unrecognised and aided) and Veda schools, gurukuls and pathashalas, so an aided madrasa is counted under ''others''. Pupil counts are the ''Total (pre-primary to 12)'' column. Table 2.7 (p. 38) lists 2,490 further pupils for Kerala reported at block level; they are outside the 6,164,059 total used here. The report says the data come from voluntary uploads by schools with a cut-off of 31 March 2025 and that the Ministry accepts no liability for errors in them (Disclaimer, p. 7). No release date is printed in the report. Press coverage dates the release to 28 August 2025, which the checker did not confirm from an official page, so only the year is given. The ''others'' group (767 schools, 102,874 pupils) is now in the statement. Kerala''s own education department pages were not used; only the national report''s state rows were read. The numbers describe who runs and who attends schools. They say nothing about quality or outcomes. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KL","sourcePassage":"Report on UDISE+ 2024-25, Table 3.2 to 3.6 (schools by management, printed pp. 41-45) and Table 5.1 to 5.5 (enrolment by management, pp. 85-89); definitions of management types on p. 187.","description":"In 2024-25 Kerala had 15,757 schools and 6,164,059 pupils from pre-primary to Class 12. Government schools were 30.5 percent of schools and 27.9 percent of pupils; government-aided schools 45.5 and 43.1 percent; private unaided recognised schools 19.2 and 27.4 percent. The report''s ''other schools'' group (unrecognised schools, madrasas, Veda schools and gurukuls) was 4.9 and 1.7 percent.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (Department of School Education and Literacy), Government of India","mandateType":"other","adoptionDate":"2025","dateGranularity":"year","statementText":"In 2024-25 Kerala had 15,757 schools and 6,164,059 pupils from pre-primary to Class 12. Government schools were 30.5 percent of schools and 27.9 percent of pupils; government-aided schools 45.5 and 43.1 percent; private unaided recognised schools 19.2 and 27.4 percent. The report''s ''other schools'' group (unrecognised schools, madrasas, Veda schools and gurukuls) was 4.9 and 1.7 percent.","subject":"general","topicTags":["school management","government schools","aided schools","private schools","enrolment"]}', '')
) AS v(id, repo_slug, record_type, jurisdiction, source_repo, source_record_id, title, content, event_date)
