-- ============================================================================
-- Corrections to earlier records
-- ============================================================================

-- INLP-EVENT-kerala-rejects-ncert-evolution-deletion: the first version, written from two news articles, said SCERT Kerala directed schools to keep teaching evolution content that NCERT removed. The sources found since show less than that.
UPDATE curriculum_repository_records SET
  title = 'Kerala''s Chief Minister criticises NCERT''s 2023 textbook changes; SCERT Kerala publishes six additional humanities books for Classes 11 and 12',
  content = content || jsonb_build_object('label', 'Kerala''s Chief Minister criticises NCERT''s 2023 textbook changes; SCERT Kerala publishes six additional humanities books for Classes 11 and 12'::text, 'description', 'News reports of 2023 say Kerala''s Chief Minister criticised the removals in NCERT''s rationalised textbooks. In August 2023 SCERT Kerala published six additional textbooks for Classes 11 and 12: Economics, History and Political Science for Class 11, and History, Political Science and Sociology for Class 12. The Director''s preface in the books read says they fill gaps left by topics deleted from the prescribed books. None of the six is a science book. SCERT Kerala''s own Class 10 Biology book (first edition 2025) has a full chapter on evolution. No SCERT circular or supplementary science book on evolution was found.'::text, 'correctionNote', 'Corrected on 2026-10-30. The first version said SCERT directed state schools to keep teaching evolution content that NCERT removed, and that it released supplementary textbooks on it. Two AI readers checked SCERT Kerala''s own pages and books: the additional books are humanities books, and no order about evolution content turned up. The Chief Minister''s criticism rests on news coverage. No Indian curriculum expert has reviewed this correction.'::text, 'correctedOn', '2026-10-30')
WHERE source_repo = 'india-lpm' AND source_record_id = 'INLP-EVENT-kerala-rejects-ncert-evolution-deletion';

-- ============================================================================
-- Each synthetic space is grounded in the Kerala repository
-- ============================================================================

INSERT INTO project_repository_links (project_id, repository_project_id, jurisdiction, note)
SELECT s.id, r.id, v.jurisdiction, v.note
FROM (VALUES
  ('bio-core-lpm-synth', 'kerala-school-curriculum-repository', 'IN-KL', 'India view: Kerala school curriculum goals and standards. AI-drafted from public documents; no Indian curriculum expert has reviewed it.'),
  ('social-core-lpm-synth', 'kerala-school-curriculum-repository', 'IN-KL', 'India view: Kerala school curriculum goals and standards. AI-drafted from public documents; no Indian curriculum expert has reviewed it.'),
  ('computational-core-lpm-synth', 'kerala-school-curriculum-repository', 'IN-KL', 'India view: Kerala school curriculum goals and standards. AI-drafted from public documents; no Indian curriculum expert has reviewed it.'),
  ('interdisciplinary-lpm-synth', 'kerala-school-curriculum-repository', 'IN-KL', 'India view: Kerala school curriculum goals and standards. AI-drafted from public documents; no Indian curriculum expert has reviewed it.')
) AS v(space_slug, repo_slug, jurisdiction, note)
JOIN projects s ON s.slug = v.space_slug
JOIN projects r ON r.slug = v.repo_slug
ON CONFLICT (project_id, repository_project_id, jurisdiction) DO NOTHING;

-- ============================================================================
-- Proposed links to the parts the spaces already have
-- ============================================================================
-- Rows are skipped when the part or the record is missing, or when the pair is already linked in any way.

-- computational-core-lpm-synth: 6 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('7d846794-560b-58b9-a9f0-267a680c308d', 'IN-KL-MANDATE-kcf-2023-mathematics-computational-thinking-and-data', 'proposed_relates_to', 'The framework''s list of computational thinking habits asks pupils to find the key elements, split a complex problem into parts, organise the steps and spot repeated operations (p.146). That resembles the model''s path from steps and loops to decomposition, but the framework gives no class bands.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'IN-KL-UNIT-ict-textbooks-classes-1-to-7-logic-games-scratch-spreadsheets-vision', 'proposed_relates_to', 'Class 4 has a short first Scratch activity (p.45-47). Class 5 (p.29-39) uses event, motion and forever-loop blocks to draw patterns. Class 6 adds an if-then block in a game (p.39-44). Kerala''s loop falls inside the model''s Class 3 to 5 band and the condition comes a year later.'),
  ('f95b2dff-2e43-597e-b8c6-a1857c0f60c7', 'IN-KL-UNIT-ict-textbooks-classes-1-to-7-logic-games-scratch-spreadsheets-vision', 'proposed_relates_to', 'Class 7 Information Analysis (p.7-18) has pupils enter data in a spreadsheet table, use sum, average and count functions and draw charts. Class 6 (p.70-80) covers tables and simple formulas and leaves averages and charts to later classes. The ICT books for Classes 3 to 5 have no such chapter. Kerala''s mathematics books for those classes were not read.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'IN-KL-UNIT-ict-textbooks-classes-8-to-10-machine-learning-python-databases-robotics', 'proposed_relates_to', 'Class 10 Python (p.45-66) defines an algorithm, then teaches input, if-elif-else with a flowchart, and while and for loops. These are the model''s sequence, loop and condition ideas in text form. Kerala''s pupils meet the block version in Scratch in Classes 4 to 7.'),
  ('06ca57c6-f90e-5354-84b4-ee88dd292147', 'IN-KL-MANDATE-higher-secondary-computer-science-and-computer-applications-2026', 'proposed_relates_to', 'Chapter 12 (p.241-252) teaches bubble and selection sort and compares linear and binary search, saying binary search needs fewer comparisons on a sorted list. The pages read give no argument of correctness or step count as input grows, which the model''s part also asks for.'),
  ('7d846794-560b-58b9-a9f0-267a680c308d', 'IN-KL-MANDATE-kcf-2023-aims-principles-stages-and-curricular-areas', 'proposed_relates_to', 'The framework calls computational thinking the chief part of its new view of mathematics and describes splitting a complex problem into small parts and organising the steps (printed pp. 146-147). It also suggests coding and Python in ICT (p. 101). The model strand teaches steps, programs and decomposition across Classes 1 to 12; the framework sets no class-wise content.')
) AS v(object_id, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo IN ('openlpm-starter-draft', 'india-lpm') AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- interdisciplinary-lpm-synth: 4 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('06af1b7b-19bb-5d77-87ac-52f34650f556', 'IN-KL-MANDATE-kcf-2023-integrated-learning-learner-experience-and-assessment', 'proposed_relates_to', 'The framework describes a classroom cycle: pose a problem, try your own solution, present it to the class, agree norms for judging it, then revise (printed p. 63). It also asks children to look back on their own learning. The model strand teaches testing and improving ideas. The framework does not mention analogy or searching.'),
  ('9d59fa89-cdc8-5147-a71e-95175b25fcee', 'IN-KL-MANDATE-kcf-2023-integrated-learning-learner-experience-and-assessment', 'proposed_relates_to', 'The framework lists awareness of technology and a historic and cultural sense among its 16 aims (printed pp. 59-60). Its social science content names family, social institutions and cultural change (pp. 168-170). The model strand teaches culture, tools and institutions across Classes 1 to 12. The match is by topic only; the framework sets no class-wise content.'),
  ('ad0173a4-5c64-5d05-96ac-2b61810c4153', 'IN-KL-UNIT-scert-classes5-7-social-science-rules-law-state-constitution-and-culture', 'proposed_relates_to', 'Class 6 teaches culture as learnt, shared, symbolic, changing and handed down from ancestors through socialisation, and treats the state as a permanent institution while governments change. That lines up with culture as transmitted and with institutions as stable structures. The book does not set institutions against norms.'),
  ('ad0173a4-5c64-5d05-96ac-2b61810c4153', 'IN-KL-UNIT-scert-classes5-10-social-science-local-government-peoples-planning-and-cooperative-institutions', 'proposed_relates_to', 'Class 7 sets out the tiers of local self-government, their powers, their sources of income and the 73rd and 74th Amendments. That shows institutions as stable, rule-based structures. The chapter is about local development and does not set institutions against norms.')
) AS v(object_id, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo IN ('openlpm-starter-draft', 'india-lpm') AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- bio-core-lpm-synth: 8 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'IN-KL-UNIT-scert-kerala-class10-biology-genetics-of-life-2025', 'proposed_contrasts_with', 'Kerala teaches genes, alleles and mutation as one unit in Class 10 Biology, Chapter 1 (pp. 16, 23, 28-31). Searches of the Class 3 to 9 science books found genes only in passing. Class 8 teaches chromosomes and meiosis (pp. 302-303) and Class 7 hybridisation. The model places genes and alleles in Classes 6 to 8.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-KL-UNIT-scert-kerala-class10-biology-paths-of-evolution-2025', 'proposed_contrasts_with', 'Kerala''s Class 10 chapter sets out natural selection in steps: surplus offspring, variation, competition, survival of better-suited individuals and passing on their traits (p. 42). The Class 3 to 9 books searched never use ''natural selection'' or ''Darwin''. Class 8 explains evolution as adaptation to changing surroundings (p. 122). The model teaches the mechanism in Classes 6 to 8.'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', 'IN-KL-UNIT-scert-kerala-class10-biology-paths-of-evolution-2025', 'proposed_contrasts_with', 'Class 10 explains that isolated populations gather variations until they can no longer breed together and become new species (p. 46). Class 8 defines a species (p. 257) and has one sentence linking habitat adaptation to the many ant species (p. 272). No isolation mechanism appears in Classes 3 to 9. The model places this in Classes 6 to 8.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-KL-UNIT-scert-kerala-class10-biology-paths-of-evolution-2025', 'proposed_relates_to', 'The chapter gives DNA, anatomy and fossil evidence for common ancestry, a tree with a last universal ancestor, a human fossil series, and a seminar task on mass extinctions. This matches the model''s use of evidence and extinction. Pupils read a given tree and prepare a human tree. They are not asked to compare extinction rates.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-KL-UNIT-scert-kerala-class8-basic-science-origin-of-life-and-diversity-2025', 'proposed_contrasts_with', 'Class 8 Chapter 8 says living things changed through adaptation to changing surroundings and shows whale ancestry from fossils (p. 122). It has no inherited variation and differential survival. Natural selection first appears in Class 10 among the Class 3 to 9 books searched. The model teaches the four-part mechanism in Classes 6 to 8.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-KL-UNIT-scert-kerala-class9-biology-evolution-evidence-and-classification-2024', 'proposed_relates_to', 'Class 9 pupils analyse a given evolutionary tree built from a table of shared features of four animals, and meet fossil evidence and DNA barcoding (pp. 106-107, 151-153). This resembles the model part''s use of structural and molecular evidence for relatedness. Pupils are not asked to build a tree, and background and mass extinction are not covered.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'IN-KL-UNIT-samagra-kerala-class12-biology-file-inheritance-and-evolution', 'proposed_relates_to', 'The Class XII Biology file''s Chapter 7 states the Hardy-Weinberg principle, with allele frequencies adding to one, and lists five factors that disturb it: gene flow, genetic drift, mutation, recombination and natural selection. This matches the model part''s focus on allele frequencies and on selection versus drift. Whether Kerala schools use this file is unconfirmed.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-KL-UNIT-samagra-kerala-class12-biology-file-inheritance-and-evolution', 'proposed_relates_to', 'The chapter covers fossil, homology and molecular evidence, adaptive radiation, speciation through drift or selection, and a short history of life. It says little about extinction and does not ask for a phylogeny to be built, so it matches the model part on evidence and deep time only in part.')
) AS v(object_id, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo IN ('openlpm-starter-draft', 'india-lpm') AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- social-core-lpm-synth: 2 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('925d0b84-162d-5a26-a26c-c15db8863af1', 'IN-KL-MANDATE-kcf-2023-social-science-objectives-content-and-stage-guidance', 'proposed_relates_to', 'The framework asks pupils to study how cultures blend through migration, to trace social change over time and to form their own views on social transformation. That matches the strand''s work on comparing societies and explaining change. It sets topics and aims only, with no skills listed class by class.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', 'IN-KL-UNIT-scert-classes9-10-social-science-roles-norms-stratification-and-social-institutions', 'proposed_relates_to', 'Class 9 asks pupils to sort statements into laws and norms and to say why some norms persist after they became illegal. Class 10 describes social institutions as regulating behaviour. Together they touch the part''s sorting of formal and informal constraints. Pupils are not asked to justify placements or trace changed incentives.')
) AS v(object_id, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo IN ('openlpm-starter-draft', 'india-lpm') AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);
